INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('smart-village-solutions/sva-studio/changelog-automation', 'changelog-automation', 'smart-village-solutions', 'sva-studio', 'community', 'changelog-automation smart-village-solutions sva-studio community changelog-automation AI智能代理是一种自动化更新和内容管理工具，用于实现Smart Village App和城市CMS的自动化更新 changelog-automation AIエージェントは自動化更新とコンテンツ管理ツールであり、Smart Village Appと都市CMSの自動化更新を実現する changelog-automation AI 에이전트는 자동화 업데이트와 콘텐츠 관리 도구로서 Smart Village App과 도시 CMS의 자동화 업데이트를實現한다 La automatización de registros de cambios es una función clave para mejorar la eficiencia del equipo de desarrollo, especialmente cuando se trabaja con sistemas headless y API-first como el SVA Studio L''automatisation du journal des modifications est une fonction clé pour améliorer l''efficacité de l''équipe de développement, en particulier lorsqu''on travaille avec des systèmes headless et API-first comme le SVA Studio Die Automatisierung von Changelogs ist eine wichtige Funktion, um die Effizienz des Entwicklungsteams zu verbessern, insbesondere wenn man mit headless- und API-first-Systemen wie dem SVA Studio arbeitet O skill de changelog-automation é uma ferramenta para automatizar o processo de atualização do changelog, permitindo que os desenvolvedores se concentrem em tarefas mais importantes. Навык changelog-automation - это инструмент для автоматизации процесса обновления changelog, позволяющий разработчикам сосредоточиться на более важных задачах. مهارة تلقيم سجل التغييرات هي أداة لتنسيق عملية تحديث سجل التغييرات، مما يسمح للمطورين بالتركيز على مهام أكثر أهمية. Das SVA Studio soll als Headless- und API-first-System sowohl die Smart Village App versorgen als auch als Stadt-CMS bzw. Content-Hub für externe Kanäle dienen (Websites, Stelen, Fachsoftware). 如何使用changelog-automation 什么是changelog-automation changelog-automation替代方案 changelog-automation vs 其他工具 changelog-automation安装指南 changelog-automation设置教程 Das SVA Studio soll als Headless- und API-first-System sowohl die Smart Village App versorgen als auch als Stadt-CMS bzw. Content-Hub für externe Kanäle dienen (Websites, Stelen, Fachsoftware).');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ollieb89/ugro/python-packaging', 'community', 'ollieb89', 'ugro', 'ollieb89/ugro', 'python-packaging', 0, 0, 60, '2026-03-04T13:07:01.813Z', '2026-03-04T14:34:36.393Z', '58082e4b1e32ba36e8bdac8c2f9c534282b8f426fd3f8ac40f485dce43521ee8', '{"id":"ollieb89/ugro/python-packaging","name":"python-packaging","description":{"zh":"python-packaging项目旨在将小规模的独立GPU机器转变为单一的高性能计算系统，支持分布式训练和推理","ja":"python-packagingプロジェクトは、独立したGPUマシンを単一の高性能コンピューティングシステムに変換し、分散トレーニングと推論をサポート","ko":"python-packaging 프로젝트는 독립적인 GPU 머신을 단일의 고성능 컴퓨팅 시스템으로 변환하여 분산 트레이닝과 추론을 지원","es":"Python-packaging es un proyecto que busca transformar máquinas GPU en un sistema de cómputo de alto rendimiento para entrenamiento distribuido y flujos de trabajo de desarrolladores","fr":"Python-packaging est un projet qui vise à transformer des machines GPU en un système de calcul haute performance pour la formation distribuée et les flux de travail de développeurs","de":"Python-packaging ist ein Projekt, das GPU-Maschinen in ein leistungsfähiges Rechnersystem für verteilter Training und Entwickler-Workflows umwandeln möchte","pt":"O python-packaging é um projeto que visa transformar máquinas GPU em um sistema de computação de alto desempenho para treinamento distribuído e inferência avançada","ru":"ИИ Агент python-packaging предназначен для преобразования независимых GPU-машин в единую систему высокопроизводительных расчетов","ar":"أداة الذكاء الاصطناعي python-packaging تهدف إلى تحويل أجهزة الكمبيوتر GPU إلى نظام حوسبة كحفي عالي الأداء","en":"This project aims to transform a small set of independently managed GPU machines into a **single, cohesive, high-power compute system** that can be dynamically orchestrated for **distributed training**, **advanced inference**, and **developer workflows**."},"seo":{"title":{"zh":"Python AIエージェント工具 - python-packaging","ja":"Python AIエージェント - python-packaging","ko":"Python AI 에이전트 - python-packaging","es":"Herramientas de inteligencia artificial: python-packaging","fr":"Outils d''intelligence artificielle: python-packaging","de":"KI-Tools: python-packaging für Entwickler","pt":"Ferramentas de IA: python-packaging para Computação de Al...","ru":"ИИ Агенты: python-packaging для Высокопроизводительных Ра...","ar":"أدوات الذكاء الاصطناعي: python-packaging لنظام الحوسبة ال...","en":"python-packaging"},"description":{"zh":"python-packaging项目旨在将小规模的独立GPU机器转变为单一的高性能计算系统，支持分布式训练和推理","ja":"python-packagingプロジェクトは、独立したGPUマシンを単一の高性能コンピューティングシステムに変換し、分散トレーニングと推論をサポート","ko":"python-packaging 프로젝트는 독립적인 GPU 머신을 단일의 고성능 컴퓨팅 시스템으로 변환하여 분산 트레이닝과 추론을 지원","es":"Python-packaging es un proyecto que busca transformar máquinas GPU en un sistema de cómputo de alto rendimiento para entrenamiento distribuido y flujos de tr...","fr":"Python-packaging est un projet qui vise à transformer des machines GPU en un système de calcul haute performance pour la formation distribuée et les flux de ...","de":"Python-packaging ist ein Projekt, das GPU-Maschinen in ein leistungsfähiges Rechnersystem für verteilter Training und Entwickler-Workflows umwandeln möchte","pt":"O python-packaging é um projeto que visa transformar máquinas GPU em um sistema de computação de alto desempenho para treinamento distribuído e inferência av...","ru":"ИИ Агент python-packaging предназначен для преобразования независимых GPU-машин в единую систему высокопроизводительных расчетов","ar":"أداة الذكاء الاصطناعي python-packaging تهدف إلى تحويل أجهزة الكمبيوتر GPU إلى نظام حوسبة كحفي عالي الأداء","en":"This project aims to transform a small set of independently managed GPU machines into a **single, cohesive, high-power compute system** that can be dynamical..."},"definition":{"en":"This project aims to transform a small set of independently managed GPU machines into a **single, cohesive, high-power compute system** that can be dynamically orchestrated for **distributed training**, **advanced inference**, and **developer workflows**."},"features":{"zh":["支持分布式训练","实现高性能计算","支持多种GPU机器","动态编排","高级推理支持"],"ja":["分散トレーニングのサポート","高性能コンピューティングの実現","複数のGPUマシンのサポート","動的オーケストレーション","高度な推論のサポート"],"ko":["분산 트레이닝 지원","고성능 컴퓨팅 구현","다수의 GPU 머신 지원","동적 오케스트레이션","고급 추론 지원"],"es":["Entrenamiento distribuido","Inferencia avanzada","Flujos de trabajo de desarrolladores","Orquestación dinámica","Sistema de cómputo de alto rendimiento","Compatibilidad con máquinas GPU"],"fr":["Formation distribuée","Inférence avancée","Flux de travail de développeurs","Orchestration dynamique","Système de calcul haute performance","Compatibilité avec les machines GPU"],"de":["Verteiltes Training","Erweiterte Inferenz","Entwickler-Workflows","Dynamische Orchestrierung","Leistungsfähiges Rechnersystem","Kompatibilität mit GPU-Maschinen"],"pt":["Treinamento distribuído","Inferência avançada","Orquestração dinâmica","Sistema de computação de alto desempenho","Suporte a máquinas GPU","Desenvolvimento de workflows"],"ru":["Распределенное обучение","Продвинутый вывод","Динамическая оркестрация","Система высокопроизводительных расчетов","Поддержка GPU-машин","Разработка рабочих процессов"],"ar":["التدريب الموزع","الاستدلال المتقدم","التحكم الديناميكي","نظام الحوسبة الكحفي العالي","دعم أجهزة الكمبيوتر GPU","تطوير سير العمل"]},"keywords":{"zh":["python-packaging安装","python-packaging设置指南","分布式训练工具","高性能计算平台","AI工具比较","python-packaging替代品","如何使用python-packaging"],"ja":["python-packagingのインストール","python-packagingの設定ガイド","分散トレーニングツール","高性能コンピューティングプラットフォーム","AIツールの比較","python-packagingの代替","python-packagingの使い方"],"ko":["python-packaging 설치","python-packaging 설정 가이드","분산 트레이닝 도구","고성능 컴퓨팅 플랫폼","AI 도구 비교","python-packaging 대체","python-packaging 사용법"],"es":["cómo usar python-packaging","qué es python-packaging","alternativas a python-packaging","python-packaging vs tensorflow","instalación de python-packaging","guía de configuración de python-packaging","desarrollo de aplicaciones con python-packaging"],"fr":["comment utiliser python-packaging","quoi est python-packaging","alternatives à python-packaging","python-packaging vs tensorflow","installation de python-packaging","guide de configuration de python-packaging","développement d''applications avec python-packaging"],"de":["wie man python-packaging verwendet","was ist python-packaging","alternativen zu python-packaging","python-packaging vs tensorflow","installation von python-packaging","einrichtungsanleitung für python-packaging","entwicklung von anwendungen mit python-packaging"],"pt":["como usar python-packaging","o que é python-packaging","alternativas para python-packaging","python-packaging vs outros","instalar python-packaging","guia de configuração do python-packaging","desenvolvimento de aplicações com python-packaging","treinamento de modelos com python-packaging"],"ru":["как использовать ИИ Агент python-packaging","что такое ИИ Агент python-packaging","альтернативы ИИ Агенту python-packaging","ИИ Агент python-packaging vs другие","установить ИИ Агент python-packaging","руководство по настройке ИИ Агента python-packaging","разработка приложений с ИИ Агентом python-packaging","обучение моделей с ИИ Агентом python-packaging"],"ar":["كيفية استخدام أداة الذكاء الاصطناعي python-packaging","ما هي أداة الذكاء الاصطناعي python-packaging","بديلات لأداة الذكاء الاصطناعي python-packaging","أداة الذكاء الاصطناعي python-packaging مقابل الأخرى","تثبيت أداة الذكاء الاصطناعي python-packaging","دليل إعداد أداة الذكاء الاصطناعي python-packaging","تطوير التطبيقات مع أداة الذكاء الاصطناعي python-packaging","تدريب النماذج مع أداة الذكاء الاصطناعي python-packaging"]}},"owner":"ollieb89","repo":"ugro","repoPath":"ollieb89/ugro","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.813Z","topics":[],"category":"community","skillMd":{"name":"python-packaging","description":"Create distributable Python packages with proper project structure, setup.py/pyproject.toml, and publishing to PyPI. Use when packaging Python libraries, creating CLI tools, or distributing Python code.","bodyPreview":"# Python Packaging\n\nComprehensive guide to creating, structuring, and distributing Python packages using modern packaging tools, pyproject.toml, and publishing to PyPI.\n\n## When to Use This Skill\n\n- Creating Python libraries for distribution\n- Building command-line tools with entry points\n- Publishing packages to PyPI or private repositories\n- Setting up Python project structure\n- Creating installable packages with dependencies\n- Building wheels and source distributions\n- Versioning and releasin","body":"# Python Packaging\n\nComprehensive guide to creating, structuring, and distributing Python packages using modern packaging tools, pyproject.toml, and publishing to PyPI.\n\n## When to Use This Skill\n\n- Creating Python libraries for distribution\n- Building command-line tools with entry points\n- Publishing packages to PyPI or private repositories\n- Setting up Python project structure\n- Creating installable packages with dependencies\n- Building wheels and source distributions\n- Versioning and releasing Python packages\n- Creating namespace packages\n- Implementing package metadata and classifiers\n\n## Core Concepts\n\n### 1. Package Structure\n- **Source layout**: `src/package_name/` (recommended)\n- **Flat layout**: `package_name/` (simpler but less flexible)\n- **Package metadata**: pyproject.toml, setup.py, or setup.cfg\n- **Distribution formats**: wheel (.whl) and source distribution (.tar.gz)\n\n### 2. Modern Packaging Standards\n- **PEP 517/518**: Build system requirements\n- **PEP 621**: Metadata in pyproject.toml\n- **PEP 660**: Editable installs\n- **pyproject.toml**: Single source of configuration\n\n### 3. Build Backends\n- **setuptools**: Traditional, widely used\n- **hatchling**: Modern, opinionated\n- **flit**: Lightweight, for pure Python\n- **poetry**: Dependency management + packaging\n\n### 4. Distribution\n- **PyPI**: Python Package Index (public)\n- **TestPyPI**: Testing before production\n- **Private repositories**: JFrog, AWS CodeArtifact, etc.\n\n## Quick Start\n\n### Minimal Package Structure\n\n```\nmy-package/\n├── pyproject.toml\n├── README.md\n├── LICENSE\n├── src/\n│   └── my_package/\n│       ├── __init__.py\n│       └── module.py\n└── tests/\n    └── test_module.py\n```\n\n### Minimal pyproject.toml\n\n```toml\n[build-system]\nrequires = [\"setuptools>=61.0\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[project]\nname = \"my-package\"\nversion = \"0.1.0\"\ndescription = \"A short description\"\nauthors = [{name = \"Your Name\", email = \"you@example.com\"}]\nreadme = \"README.md\"\nrequires-python = \">=3.8\"\ndependencies = [\n    \"requests>=2.28.0\",\n]\n\n[project.optional-dependencies]\ndev = [\n    \"pytest>=7.0\",\n    \"black>=22.0\",\n]\n```\n\n## Package Structure Patterns\n\n### Pattern 1: Source Layout (Recommended)\n\n```\nmy-package/\n├── pyproject.toml\n├── README.md\n├── LICENSE\n├── .gitignore\n├── src/\n│   └── my_package/\n│       ├── __init__.py\n│       ├── core.py\n│       ├── utils.py\n│       └── py.typed          # For type hints\n├── tests/\n│   ├── __init__.py\n│   ├── test_core.py\n│   └── test_utils.py\n└── docs/\n    └── index.md\n```\n\n**Advantages:**\n- Prevents accidentally importing from source\n- Cleaner test imports\n- Better isolation\n\n**pyproject.toml for source layout:**\n```toml\n[tool.setuptools.packages.find]\nwhere = [\"src\"]\n```\n\n### Pattern 2: Flat Layout\n\n```\nmy-package/\n├── pyproject.toml\n├── README.md\n├── my_package/\n│   ├── __init__.py\n│   └── module.py\n└── tests/\n    └── test_module.py\n```\n\n**Simpler but:**\n- Can import package without installing\n- Less professional for libraries\n\n### Pattern 3: Multi-Package Project\n\n```\nproject/\n├── pyproject.toml\n├── packages/\n│   ├── package-a/\n│   │   └── src/\n│   │       └── package_a/\n│   └── package-b/\n│       └── src/\n│           └── package_b/\n└── tests/\n```\n\n## Complete pyproject.toml Examples\n\n### Pattern 4: Full-Featured pyproject.toml\n\n```toml\n[build-system]\nrequires = [\"setuptools>=61.0\", \"wheel\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[project]\nname = \"my-awesome-package\"\nversion = \"1.0.0\"\ndescription = \"An awesome Python package\"\nreadme = \"README.md\"\nrequires-python = \">=3.8\"\nlicense = {text = \"MIT\"}\nauthors = [\n    {name = \"Your Name\", email = \"you@example.com\"},\n]\nmaintainers = [\n    {name = \"Maintainer Name\", email = \"maintainer@example.com\"},\n]\nkeywords = [\"example\", \"package\", \"awesome\"]\nclassifiers = [\n    \"Development Status :: 4 - Beta\",\n    \"Intended Audience :: Developers\",\n    \"License :: OSI Approved :: MIT License\",\n    \"Programming Language :: Python :: 3\",\n    \"Programming Language :: Python :: 3.8\",\n    \"Programming Language :: Python :: 3.9\",\n    \"Programming Language :: Python :: 3.10\",\n    \"Programming Language :: Python :: 3.11\",\n    \"Programming Language :: Python :: 3.12\",\n]\n\ndependencies = [\n    \"requests>=2.28.0,<3.0.0\",\n    \"click>=8.0.0\",\n    \"pydantic>=2.0.0\",\n]\n\n[project.optional-dependencies]\ndev = [\n    \"pytest>=7.0.0\",\n    \"pytest-cov>=4.0.0\",\n    \"black>=23.0.0\",\n    \"ruff>=0.1.0\",\n    \"mypy>=1.0.0\",\n]\ndocs = [\n    \"sphinx>=5.0.0\",\n    \"sphinx-rtd-theme>=1.0.0\",\n]\nall = [\n    \"my-awesome-package[dev,docs]\",\n]\n\n[project.urls]\nHomepage = \"https://github.com/username/my-awesome-package\"\nDocumentation = \"https://my-awesome-package.readthedocs.io\"\nRepository = \"https://github.com/username/my-awesome-package\"\n\"Bug Tracker\" = \"https://github.com/username/my-awesome-package/issues\"\nChangelog = \"https://github.com/username/my-awesome-package/blob/main/CHANGELOG.md\"\n\n[project.scripts]\nmy-cli = \"my_package.cli:main\"\nawesome-tool = \"my_package.tools:run\"\n\n[project.entry-points.\"my_package.plugins\"]\nplugin1 = \"my_package.plugins:plugin1\"\n\n[tool.setuptools]\npackage-dir = {\"\" = \"src\"}\nzip-safe = false\n\n[tool.setuptools.packages.find]\nwhere = [\"src\"]\ninclude = [\"my_package*\"]\nexclude = [\"tests*\"]\n\n[tool.setuptools.package-data]\nmy_package = [\"py.typed\", \"*.pyi\", \"data/*.json\"]\n\n# Black configuration\n[tool.black]\nline-length = 100\ntarget-version = [\"py38\", \"py39\", \"py310\", \"py311\"]\ninclude = ''\\.pyi?$''\n\n# Ruff configuration\n[tool.ruff]\nline-length = 100\ntarget-version = \"py38\"\n\n[tool.ruff.lint]\nselect = [\"E\", \"F\", \"I\", \"N\", \"W\", \"UP\"]\n\n# MyPy configuration\n[tool.mypy]\npython_version = \"3.8\"\nwarn_return_any = true\nwarn_unused_configs = true\ndisallow_untyped_defs = true\n\n# Pytest configuration\n[tool.pytest.ini_options]\ntestpaths = [\"tests\"]\npython_files = [\"test_*.py\"]\naddopts = \"-v --cov=my_package --cov-report=term-missing\"\n\n# Coverage configuration\n[tool.coverage.run]\nsource = [\"src\"]\nomit = [\"*/tests/*\"]\n\n[tool.coverage.report]\nexclude_lines = [\n    \"pragma: no cover\",\n    \"def __repr__\",\n    \"raise AssertionError\",\n    \"raise NotImplementedError\",\n]\n```\n\n### Pattern 5: Dynamic Versioning\n\n```toml\n[build-system]\nrequires = [\"setuptools>=61.0\", \"setuptools-scm>=8.0\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[project]\nname = \"my-package\"\ndynamic = [\"version\"]\ndescription = \"Package with dynamic version\"\n\n[tool.setuptools.dynamic]\nversion = {attr = \"my_package.__version__\"}\n\n# Or use setuptools-scm for git-based versioning\n[tool.setuptools_scm]\nwrite_to = \"src/my_package/_version.py\"\n```\n\n**In __init__.py:**\n```python\n# src/my_package/__init__.py\n__version__ = \"1.0.0\"\n\n# Or with setuptools-scm\nfrom importlib.metadata import version\n__version__ = version(\"my-package\")\n```\n\n## Command-Line Interface (CLI) Patterns\n\n### Pattern 6: CLI with Click\n\n```python\n# src/my_package/cli.py\nimport click\n\n@click.group()\n@click.version_option()\ndef cli():\n    \"\"\"My awesome CLI tool.\"\"\"\n    pass\n\n@cli.command()\n@click.argument(\"name\")\n@click.option(\"--greeting\", default=\"Hello\", help=\"Greeting to use\")\ndef greet(name: str, greeting: str):\n    \"\"\"Greet someone.\"\"\"\n    click.echo(f\"{greeting}, {name}!\")\n\n@cli.command()\n@click.option(\"--count\", default=1, help=\"Number of times to repeat\")\ndef repeat(count: int):\n    \"\"\"Repeat a message.\"\"\"\n    for i in range(count):\n        click.echo(f\"Message {i + 1}\")\n\ndef main():\n    \"\"\"Entry point for CLI.\"\"\"\n    cli()\n\nif __name__ == \"__main__\":\n    main()\n```\n\n**Register in pyproject.toml:**\n```toml\n[project.scripts]\nmy-tool = \"my_package.cli:main\"\n```\n\n**Usage:**\n```bash\npip install -e .\nmy-tool greet World\nmy-tool greet Alice --greeting=\"Hi\"\nmy-tool repeat --count=3\n```\n\n### Pattern 7: CLI with argparse\n\n```python\n# src/my_package/cli.py\nimport argparse\nimport sys\n\ndef main():\n    \"\"\"Main CLI entry point.\"\"\"\n    parser = argparse.ArgumentParser(\n        description=\"My awesome tool\",\n        prog=\"my-tool\"\n    )\n\n    parser.add_argument(\n        \"--version\",\n        action=\"version\",\n        version=\"%(prog)s 1.0.0\"\n    )\n\n    subparsers = parser.add_subparsers(dest=\"command\", help=\"Commands\")\n\n    # Add subcommand\n    process_parser = subparsers.add_parser(\"process\", help=\"Process data\")\n    process_parser.add_argument(\"input_file\", help=\"Input file path\")\n    process_parser.add_argument(\n        \"--output\", \"-o\",\n        default=\"output.txt\",\n        help=\"Output file path\"\n    )\n\n    args = parser.parse_args()\n\n    if args.command == \"process\":\n        process_data(args.input_file, args.output)\n    else:\n        parser.print_help()\n        sys.exit(1)\n\ndef process_data(input_file: str, output_file: str):\n    \"\"\"Process data from input to output.\"\"\"\n    print(f\"Processing {input_file} -> {output_file}\")\n\nif __name__ == \"__main__\":\n    main()\n```\n\n## Building and Publishing\n\n### Pattern 8: Build Package Locally\n\n```bash\n# Install build tools\npip install build twine\n\n# Build distribution\npython -m build\n\n# This creates:\n# dist/\n#   my-package-1.0.0.tar.gz (source distribution)\n#   my_package-1.0.0-py3-none-any.whl (wheel)\n\n# Check the distribution\ntwine check dist/*\n```\n\n### Pattern 9: Publishing to PyPI\n\n```bash\n# Install publishing tools\npip install twine\n\n# Test on TestPyPI first\ntwine upload --repository testpypi dist/*\n\n# Install from TestPyPI to test\npip install --index-url https://test.pypi.org/simple/ my-package\n\n# If all good, publish to PyPI\ntwine upload dist/*\n```\n\n**Using API tokens (recommended):**\n```bash\n# Create ~/.pypirc\n[distutils]\nindex-servers =\n    pypi\n    testpypi\n\n[pypi]\nusername = __token__\npassword = pypi-...your-token...\n\n[testpypi]\nusername = __token__\npassword = pypi-...your-test-token...\n```\n\n### Pattern 10: Automated Publishing with GitHub Actions\n\n```yaml\n# .github/workflows/publish.yml\nname: Publish to PyPI\n\non:\n  release:\n    types: [created]\n\njobs:\n  publish:\n    runs-on: ubuntu-latest\n\n    steps:\n      - uses: actions/checkout@v3\n\n      - name: Set up Python\n        uses: actions/setup-python@v4\n        with:\n          python-version: \"3.11\"\n\n      - name: Install dependencies\n        run: |\n          pip install build twine\n\n      - name: Build package\n        run: python -m build\n\n      - name: Check package\n        run: twine check dist/*\n\n      - name: Publish to PyPI\n        env:\n          TWINE_USERNAME: __token__\n          TWINE_PASSWORD: ${{ secrets.PYPI_API_TOKEN }}\n        run: twine upload dist/*\n```\n\n## Advanced Patterns\n\n### Pattern 11: Including Data Files\n\n```toml\n[tool.setuptools.package-data]\nmy_package = [\n    \"data/*.json\",\n    \"templates/*.html\",\n    \"static/css/*.css\",\n    \"py.typed\",\n]\n```\n\n**Accessing data files:**\n```python\n# src/my_package/loader.py\nfrom importlib.resources import files\nimport json\n\ndef load_config():\n    \"\"\"Load configuration from package data.\"\"\"\n    config_file = files(\"my_package\").joinpath(\"data/config.json\")\n    with config_file.open() as f:\n        return json.load(f)\n\n# Python 3.9+\nfrom importlib.resources import files\n\ndata = files(\"my_package\").joinpath(\"data/file.txt\").read_text()\n```\n\n### Pattern 12: Namespace Packages\n\n**For large projects split across multiple repositories:**\n\n```\n# Package 1: company-core\ncompany/\n└── core/\n    ├── __init__.py\n    └── models.py\n\n# Package 2: company-api\ncompany/\n└── api/\n    ├── __init__.py\n    └── routes.py\n```\n\n**Do NOT include __init__.py in the namespace directory (company/):**\n\n```toml\n# company-core/pyproject.toml\n[project]\nname = \"company-core\"\n\n[tool.setuptools.packages.find]\nwhere = [\".\"]\ninclude = [\"company.core*\"]\n\n# company-api/pyproject.toml\n[project]\nname = \"company-api\"\n\n[tool.setuptools.packages.find]\nwhere = [\".\"]\ninclude = [\"company.api*\"]\n```\n\n**Usage:**\n```python\n# Both packages can be imported under same namespace\nfrom company.core import models\nfrom company.api import routes\n```\n\n### Pattern 13: C Extensions\n\n```toml\n[build-system]\nrequires = [\"setuptools>=61.0\", \"wheel\", \"Cython>=0.29\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[tool.setuptools]\next-modules = [\n    {name = \"my_package.fast_module\", sources = [\"src/fast_module.c\"]},\n]\n```\n\n**Or with setup.py:**\n```python\n# setup.py\nfrom setuptools import setup, Extension\n\nsetup(\n    ext_modules=[\n        Extension(\n            \"my_package.fast_module\",\n            sources=[\"src/fast_module.c\"],\n            include_dirs=[\"src/include\"],\n        )\n    ]\n)\n```\n\n## Version Management\n\n### Pattern 14: Semantic Versioning\n\n```python\n# src/my_package/__init__.py\n__version__ = \"1.2.3\"\n\n# Semantic versioning: MAJOR.MINOR.PATCH\n# MAJOR: Breaking changes\n# MINOR: New features (backward compatible)\n# PATCH: Bug fixes\n```\n\n**Version constraints in dependencies:**\n```toml\ndependencies = [\n    \"requests>=2.28.0,<3.0.0\",  # Compatible range\n    \"click~=8.1.0\",              # Compatible release (~= 8.1.0 means >=8.1.0,<8.2.0)\n    \"pydantic>=2.0\",             # Minimum version\n    \"numpy==1.24.3\",             # Exact version (avoid if possible)\n]\n```\n\n### Pattern 15: Git-Based Versioning\n\n```toml\n[build-system]\nrequires = [\"setuptools>=61.0\", \"setuptools-scm>=8.0\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[project]\nname = \"my-package\"\ndynamic = [\"version\"]\n\n[tool.setuptools_scm]\nwrite_to = \"src/my_package/_version.py\"\nversion_scheme = \"post-release\"\nlocal_scheme = \"dirty-tag\"\n```\n\n**Creates versions like:**\n- `1.0.0` (from git tag)\n- `1.0.1.dev3+g1234567` (3 commits after tag)\n\n## Testing Installation\n\n### Pattern 16: Editable Install\n\n```bash\n# Install in development mode\npip install -e .\n\n# With optional dependencies\npip install -e \".[dev]\"\npip install -e \".[dev,docs]\"\n\n# Now changes to source code are immediately reflected\n```\n\n### Pattern 17: Testing in Isolated Environment\n\n```bash\n# Create virtual environment\npython -m venv test-env\nsource test-env/bin/activate  # Linux/Mac\n# test-env\\Scripts\\activate  # Windows\n\n# Install package\npip install dist/my_package-1.0.0-py3-none-any.whl\n\n# Test it works\npython -c \"import my_package; print(my_package.__version__)\"\n\n# Test CLI\nmy-tool --help\n\n# Cleanup\ndeactivate\nrm -rf test-env\n```\n\n## Documentation\n\n### Pattern 18: README.md Template\n\n```markdown\n# My Package\n\n[![PyPI version](https://badge.fury.io/py/my-package.svg)](https://pypi.org/project/my-package/)\n[![Python versions](https://img.shields.io/pypi/pyversions/my-package.svg)](https://pypi.org/project/my-package/)\n[![Tests](https://github.com/username/my-package/workflows/Tests/badge.svg)](https://github.com/username/my-package/actions)\n\nBrief description of your package.\n\n## Installation\n\n```bash\npip install my-package\n```\n\n## Quick Start\n\n```python\nfrom my_package import something\n\nresult = something.do_stuff()\n```\n\n## Features\n\n- Feature 1\n- Feature 2\n- Feature 3\n\n## Documentation\n\nFull documentation: https://my-package.readthedocs.io\n\n## Development\n\n```bash\ngit clone https://github.com/username/my-package.git\ncd my-package\npip install -e \".[dev]\"\npytest\n```\n\n## License\n\nMIT\n```\n\n## Common Patterns\n\n### Pattern 19: Multi-Architecture Wheels\n\n```yaml\n# .github/workflows/wheels.yml\nname: Build wheels\n\non: [push, pull_request]\n\njobs:\n  build_wheels:\n    name: Build wheels on ${{ matrix.os }}\n    runs-on: ${{ matrix.os }}\n    strategy:\n      matrix:\n        os: [ubuntu-latest, windows-latest, macos-latest]\n\n    steps:\n      - uses: actions/checkout@v3\n\n      - name: Build wheels\n        uses: pypa/cibuildwheel@v2.16.2\n\n      - uses: actions/upload-artifact@v3\n        with:\n          path: ./wheelhouse/*.whl\n```\n\n### Pattern 20: Private Package Index\n\n```bash\n# Install from private index\npip install my-package --index-url https://private.pypi.org/simple/\n\n# Or add to pip.conf\n[global]\nindex-url = https://private.pypi.org/simple/\nextra-index-url = https://pypi.org/simple/\n\n# Upload to private index\ntwine upload --repository-url https://private.pypi.org/ dist/*\n```\n\n## File Templates\n\n### .gitignore for Python Packages\n\n```gitignore\n# Build artifacts\nbuild/\ndist/\n*.egg-info/\n*.egg\n.eggs/\n\n# Python\n__pycache__/\n*.py[cod]\n*$py.class\n*.so\n\n# Virtual environments\nvenv/\nenv/\nENV/\n\n# IDE\n.vscode/\n.idea/\n*.swp\n\n# Testing\n.pytest_cache/\n.coverage\nhtmlcov/\n\n# Distribution\n*.whl\n*.tar.gz\n```\n\n### MANIFEST.in\n\n```\n# MANIFEST.in\ninclude README.md\ninclude LICENSE\ninclude pyproject.toml\n\nrecursive-include src/my_package/data *.json\nrecursive-include src/my_package/templates *.html\nrecursive-exclude * __pycache__\nrecursive-exclude * *.py[co]\n```\n\n## Checklist for Publishing\n\n- [ ] Code is tested (pytest passing)\n- [ ] Documentation is complete (README, docstrings)\n- [ ] Version number updated\n- [ ] CHANGELOG.md updated\n- [ ] License file included\n- [ ] pyproject.toml is complete\n- [ ] Package builds without errors\n- [ ] Installation tested in clean environment\n- [ ] CLI tools work (if applicable)\n- [ ] PyPI metadata is correct (classifiers, keywords)\n- [ ] GitHub repository linked\n- [ ] Tested on TestPyPI first\n- [ ] Git tag created for release\n\n## Resources\n\n- **Python Packaging Guide**: https://packaging.python.org/\n- **PyPI**: https://pypi.org/\n- **TestPyPI**: https://test.pypi.org/\n- **setuptools documentation**: https://setuptools.pypa.io/\n- **build**: https://pypa-build.readthedocs.io/\n- **twine**: https://twine.readthedocs.io/\n\n## Best Practices Summary\n\n1. **Use src/ layout** for cleaner package structure\n2. **Use pyproject.toml** for modern packaging\n3. **Pin build dependencies** in build-system.requires\n4. **Version appropriately** with semantic versioning\n5. **Include all metadata** (classifiers, URLs, etc.)\n6. **Test installation** in clean environments\n7. **Use TestPyPI** before publishing to PyPI\n8. **Document thoroughly** with README and docstrings\n9. **Include LICENSE** file\n10. **Automate publishing** with CI/CD\n"},"lastSynced":"2026-03-04T14:34:36.393Z","agentAnalysis":{"suitability":{"en":"Ideal for Python Development Agents requiring efficient package management and distribution capabilities.","zh":"适用于需要高效包管理和分发能力的Python开发代理。","ja":"Pythonパッケージの効率的な管理と配布が必要なPython開発エージェントに適しています。","ko":"효율적인 패키지 관리 및 배포 기능이 필요한 Python 개발 에이전트에 적합합니다.","es":"Ideal para Python Development Agents que requieren un manejo de paquetes y distribución eficiente.","fr":"Idéal pour les Python Development Agents nécessitant un gestion de paquet et une distribution efficace.","de":"Ideal für Python Development Agents, die eine effiziente Paketverwaltung und Distribution benötigen.","pt":"Ideal para Python Development Agents que requerem gerenciamento de pacotes e distribuição eficiente.","ru":"Идеально для Python Development Agents, требующих эффективного управления пакетами и распределения.","ar":"يเหมาะ Python Development Agents الذين يحتاجون إلى إدارة حزمة و توزيع فعال."},"recommendation":{"en":"Empowers agents to create, structure, and distribute Python packages using modern packaging tools like pyproject.toml, and publish to PyPI, enabling seamless dependency management and version control.","zh":"赋予代理创建、结构化和分发Python包的能力，使用现代打包工具如pyproject.toml，并发布到PyPI，从而实现无缝的依赖管理和版本控制。","ja":"pyproject.tomlなどのモダンなパッケージングツールを使用して、Pythonパッケージの作成、構造化、配布を可能にし、PyPIへの公開を通じて依存関係管理とバージョン管理をスムーズに行えるようにします。","ko":"최신 패키징 도구인 pyproject.toml을 사용하여 Python 패키지를 생성, 구조화, 배포할 수 있는 기능을 제공하고, PyPI에 배포함으로써 종속성 관리와 버전 관리를 무결점으로 수행할 수 있습니다.","es":"Empoderar a los agentes para crear, estructurar y distribuir paquetes Python utilizando herramientas de empaquetado modernas como pyproject.toml y publicar a PyPI, habilitando un manejo de dependencias y control de versiones sin problemas.","fr":"Empower les agents pour créer, structurer et distribuer des paquetes Python en utilisant des outils de empaquetage modernes comme pyproject.toml et publier à PyPI, permettant un gestion de dependencias et un contrôle de version sans problèmes.","de":"Empower die Agenten, um Python-Pakete zu erstellen, zu strukturieren und zu verteilen, indem sie moderne Verpackungstools wie pyproject.toml und PyPI verwenden, was ein Problemloses Dependency-Management und Versionskontrolle ermöglicht.","pt":"Empowers agents to create, structure, and distribute Python packages using modern packaging tools like pyproject.toml, and publish to PyPI, enabling seamless dependency management and version control.","ru":"Empowers agents to create, structure, and distribute Python packages using modern packaging tools like pyproject.toml, and publish to PyPI, enabling seamless dependency management and version control.","ar":"Empowers agents to create, structure, and distribute Python packages using modern packaging tools like pyproject.toml, and publish to PyPI, enabling seamless dependency management and version control."},"useCases":{"en":["Creating and publishing Python libraries to PyPI","Building and distributing command-line tools with entry points","Setting up and managing Python project structures with dependencies"],"zh":["创建和发布Python库到PyPI","使用入口点构建和分发命令行工具","使用依赖关系设置和管理Python项目结构"],"ja":["PyPIへのPythonライブラリの作成と公開","エントリポイントを使用したコマンドラインツールの構築と配布","依存関係を使用したPythonプロジェクト構造の設定と管理"],"ko":["PyPI에 Python 라이브러리를 생성하고 배포하는 것","입력점을 사용하여 명령줄 도구를 구축하고 배포하는 것","의존성을 사용하여 Python 프로젝트 구조를 설정하고 관리하는 것"],"es":["Crear y publicar bibliotecas Python a PyPI","Construir y distribuir herramientas de línea de comandos con puntos de entrada","Configurar y gestionar estructuras de proyectos Python con dependencias"],"fr":["Créer et publier des bibliothèques Python à PyPI","Construir et distribuer des outils de ligne de comandos avec des points d''entrée","Configurer et gérer des structures de projets Python avec des dependencias"],"de":["Erstellen und veröffentlichen von Python-Bibliotheken zu PyPI","Erstellen und verteilen von Kommandozeilen-Tools mit Einstiegspunkten","Konfigurieren und verwalten von Python-Projektstrukturen mit Abhängigkeiten"],"pt":["Creating and publishing Python libraries to PyPI","Building and distributing command-line tools with entry points","Setting up and managing Python project structures with dependencies"],"ru":["Creating and publishing Python libraries to PyPI","Building and distributing command-line tools with entry points","Setting up and managing Python project structures with dependencies"],"ar":["Creating and publishing Python libraries to PyPI","Building and distributing command-line tools with entry points","Setting up and managing Python project structures with dependencies"]},"limitations":{"en":["Requires Python environment","pyproject.toml configuration needed","Publishing to private repositories may require additional setup"],"zh":["需要Python环境","需要pyproject.toml配置","发布到私有仓库可能需要额外设置"],"ja":["Python環境が必要","pyproject.tomlの設定が必要","プライベートリポジトリへの公開には追加の設定が必要になる場合がある"],"ko":["Python 환경이 필요합니다.","pyproject.toml 설정이 필요합니다.","개인 저장소에 게시하는 경우 추가 설정이 필요할 수 있습니다."],"es":["Requiere un entorno Python","La configuración de pyproject.toml es necesaria","La publicación a repositorios privados puede requerir una configuración adicional"],"fr":["Requiert un environnement Python","La configuration de pyproject.toml est nécessaire","La publication à des répertoires privés peut nécessiter une configuration supplémentaire"],"de":["Erfordert eine Python-Umgebung","Die Konfiguration von pyproject.toml ist erforderlich","Die Veröffentlichung in private Repositorien kann eine zusätzliche Konfiguration erfordern"],"pt":["Requires Python environment","pyproject.toml configuration needed","Publishing to private repositories may require additional setup"],"ru":["Requires Python environment","pyproject.toml configuration needed","Publishing to private repositories may require additional setup"],"ar":["Requires Python environment","pyproject.toml configuration needed","Publishing to private repositories may require additional setup"]},"version":3},"contentHash":"58082e4b1e32ba36e8bdac8c2f9c534282b8f426fd3f8ac40f485dce43521ee8","qualityScore":60}');
