INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('danburonline/public-writings/scientific-writing', 'scientific-writing', 'danburonline', 'public-writings', 'community', 'scientific-writing danburonline public-writings community scientific-writing是一种开源的AI智能写作工具，用于存储和编辑文章、论文和报告 scientific-writingは、AIエージェントを使用した文章、論文、レポートの保管と編集を行うためのツールです scientific-writing은 AI 에이전트를 사용하여 작성한 글, 논문, 보고서를 저장하고 편집하는 툴입니다 La escritura científica con agentes de IA implica el uso de herramientas de código abierto para mejorar la calidad de los artículos y ensayos L''écriture scientifique avec les agents d''IA implique l''utilisation d''outils open source pour améliorer la qualité des articles et essais Das wissenschaftliche Schreiben mit KI-Agenten beinhaltet die Verwendung von Open-Source-Tools, um die Qualität von Artikeln und Aufsätzen zu verbessern Os agentes de IA podem ajudar a melhorar a escrita científica. Este recurso de escrita científica é de código aberto e permite contribuições. ИИ Агенты могут помочь улучшить научное письмо. Этот инструмент научного письма имеет открытый исходный код и позволяет вносить вклад. يمكن لوكلاء الذكاء الاصطناعي تحسين الكتابة العلمية. هذا المورد للكتابة العلمية مفتوح المصدر ويسمح بالمشاركة. This is where I keep all of my public writings; all of my articles, essays, and papers are archived and edited here. I keep it open source so that anyone can contribute improving them. AI智能写作工具 科学文章写作 开源写作工具 如何使用scientific-writing scientific-writing安装指南 AI写作工具比较 This is where I keep all of my public writings; all of my articles, essays, and papers are archived and edited here. I keep it open source so that anyone can contribute improving them.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chenjiongwei/zjsy/digital-brain', 'community', 'chenjiongwei', 'zjsy', 'chenjiongwei/zjsy', 'digital-brain', 0, 0, 60, '2026-03-04T13:07:01.848Z', '2026-03-04T14:49:22.975Z', '39ed6cd20dd787b6c71397aa0f75619887ed774c0fd390439d8e535f54bb3544', '{"id":"chenjiongwei/zjsy/digital-brain","name":"digital-brain","description":{"zh":"digital-brain 是一款用于珠江实业的SQL脚本开发的AI智能工具，能够提高开发效率和准确性","ja":"digital-brainはSQLスクリプト開発を支援するAIエージェントで、開発効率と精度を向上させます","ko":"digital-brain은 SQL 스크립트 개발을 지원하는 AI 에이전트로, 개발 효율과 정확도를 향상합니다","es":"Digital-brain es una herramienta de inteligencia artificial para desarrolladores de SQL que ofrece soluciones de desarrollo de scripts personalizadas","fr":"Digital-brain est un outil d''intelligence artificielle pour les développeurs SQL qui propose des solutions de développement de scripts sur mesure","de":"Digital-brain ist ein KI-Tool für SQL-Entwickler, das maßgeschneiderte Skriptentwicklungs-Lösungen bietet","pt":"O digital-brain é uma ferramenta de IA para desenvolvimento de SQL, oferecendo recursos avançados para melhorar a produtividade dos desenvolvedores.","ru":"Digital-brain - это инструмент ИИ для разработки SQL, предлагающий расширенные функции для повышения производительности разработчиков.","ar":"digital-brain هو أداة ذكاء اصطناعي لتطوير SQL، توفر ميزات متقدمة لتحسين إنتاجية المطورين.","en":"珠江实业的SQL脚本开发"},"seo":{"title":{"zh":"AI智能工具：珠江实业的SQL脚本开发 - digital-brain","ja":"AIエージェント：digital-brain - SQLスクリプト開発","ko":"AI 에이전트: digital-brain - SQL 스크립트 개발","es":"Herramientas de inteligencia artificial: digital-brain pa...","fr":"Outils d''intelligence artificielle: digital-brain pour SQL","de":"KI-Tools: digital-brain für SQL-Entwicklung","pt":"Ferramentas de IA: digital-brain para Desenvolvimento de SQL","ru":"ИИ Агенты: digital-brain для Разработки SQL","ar":"أدوات الذكاء الاصطناعي: digita