INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bybren-llc/safe-agentic-workflow/linear-sop', 'linear-sop', 'bybren-llc', 'safe-agentic-workflow', 'community', 'linear-sop bybren-llc safe-agentic-workflow community linear-sop是生产级SAFe多智能代理开发方法，使用Claude Code实现11个角色协作 linear-sopは生産レベルのSAFe多AIエージェント開発方法で、Claude Codeを使用して11の役割を協力して linear-sop은 생산 수준의 SAFe 다중 AI 에이전트 개발 방법으로 Claude Code를 사용하여 11개의 역할을 협력 linear-sop es una metodología de desarrollo de Agents de IA que trata a los agentes como miembros especializados del equipo linear-sop est une méthodologie de développement d''Agents d''IA qui traite les agents comme des membres spécialisés de l''équipe linear-sop ist eine Entwicklungsmethode für KI-Agents, die die Agents als spezialisierte Teammitglieder behandelt Metodologia de desenvolvimento de agentes de IA validada para produção com Claude Code e SAFe. Trate agentes de IA como membros especializados da equipe Методология разработки ИИ Агентов, проверенная на производстве с Claude Code и SAFe. Рассматривайте ИИ Агентов как специализированных членов команды منهجية تطوير وكلاء الذكاء الاصطناعي المعتمدة لإنتاج مع Claude Code و SAFe. معاملة وكلاء الذكاء الاصطناعي كأعضاء متخصصين في الفريق Production-validated SAFe multi-agent development methodology with Claude Code. Treat AI agents as specialized team members (11 roles: BSA, Architect, QAS, etc). Complete whitepaper + working template. AI智能代理开发 SAFe开发方法 Claude Code 多智能代理开发 生产级开发 智能代理工具 AI开发框架 SAFe框架 Claude Code教程 Production-validated SAFe multi-agent development methodology with Claude Code. Treat AI agents as specialized team members (11 roles: BSA, Architect, QAS, etc). Complete whitepaper + working template. ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('irahardianto/qurio/technical-constitution', 'community', 'irahardianto', 'qurio', 'irahardianto/qurio', 'technical-constitution', 0, 0, 60, '2026-03-04T13:07:01.899Z', '2026-03-04T14:56:38.051Z', '24aa73239d7da087bddf26ebc033b1f49821fd69f53f283f3f372efebfde632e', '{"id":"irahardianto/qurio/technical-constitution","name":"technical-constitution","description":{"zh":"Technical Constitution是一种自建RAG引擎，用于AI编码助手，能够本地摄取技术文档和代码仓库","ja":"Technical Constitutionは、AIコーディングアシスタント用の自社のRAGエンジンです。技術文書とコードリポジトリをローカルで取り込み、構造認識のチャンキングを実行します","ko":"Technical Constitution은 AI 코딩 어시스턴트용 zelf-hosted RAG 엔진으로, 기술 문서 및 코드 저장소를 로컬에서摄取하고 구조 인식 청킹을 수행합니다","es":"El motor RAG autónomo es una herramienta de AI que ingiere documentos técnicos y repositorios de código de forma local para proporcionar contexto en flujos de trabajo de desarrollo de software","fr":"Le moteur RAG autonome est un outil IA qui ingère des documents techniques et des référentiels de code de manière locale pour fournir un contexte dans les flux de travail de développement de logiciels","de":"Der selbstgehostete RAG-Motor ist ein KI-Tool, das technische Dokumente und Code-Repositorys lokal aufnimmt, um Kontext in Software-Entwicklungsworkflows bereitzustellen","pt":"O technical-constitution é um motor de RAG auto-hospedado que ingere documentos técnicos e repositórios de código localmente, fornecendo contexto fundamentado para prevenir alucinações em fluxos de trabalho de desenvolvimento de software","ru":"technical-constitution - это самохостящийся двиг РАГ, который принимает технические документы и кодовые репозитории локально, предоставляя основанный контекст для предотвращения галлюцинаций в потоках работы разработки программного обеспечения","ar":"technical-constitution هو محرك RAG مُضيف ذاتيًا يبتلع الوثائق الفنية ومخازن الشفرة المحلية، يوفر سياقًا مُؤسسًا لمنع الهلوسة في تدفقات العمل التطويرية للبرمجيات","en":"Self-hosted RAG engine for AI coding assistants. Ingests technical docs & code repositories locally with structure-aware chunking. Serves grounded context via MCP to prevent hallucinations in software development workflows."},"seo":{"title":{"zh":"AI智能助手 - Technical Constitution","ja":"AIエージェント - Technical Constitution","ko":"AI 에이전트 - Technical Constitution","es":"Herramientas de AI: Motor RAG autónomo para asistentes de...","fr":"Outils IA: Moteur RAG autonome pour assistants de codage","de":"KI-Tools: Selbstgehosteter RAG-Motor für KI-Coding-Assist...","pt":"Ferramentas de IA: technical-constitution para Desenvolve...","ru":"ИИ Агенты: technical-constitution для Разработчиков","ar":"أدوات الذكاء الاصطناعي: technical-constitution للמطورين","en":"technical-constitution"},"description":{"zh":"Technical Constitution是一种自建RAG引擎，用于AI编码助手，能够本地摄取技术文档和代码仓库","ja":"Technical Constitutionは、AIコーディングアシスタント用の自社のRAGエンジンです。技術文書とコードリポジトリをローカルで取り込み、構造認識のチャンキングを実行します","ko":"Technical Constitution은 AI 코딩 어시스턴트용 zelf-hosted RAG 엔진으로, 기술 문서 및 코드 저장소를 로컬에서摄取하고 구조 인식 청킹을 수행합니다","es":"El motor RAG autónomo es una herramienta de AI que ingiere documentos técnicos y repositorios de código de forma local para proporcionar contexto en flujos d...","fr":"Le moteur RAG autonome est un outil IA qui ingère des documents techniques et des référentiels de code de manière locale pour fournir un contexte dans les fl...","de":"Der selbstgehostete RAG-Motor ist ein KI-Tool, das technische Dokumente und Code-Repositorys lokal aufnimmt, um Kontext in Software-Entwicklungsworkflows ber...","pt":"O technical-constitution é um motor de RAG auto-hospedado que ingere documentos técnicos e repositórios de código localmente, fornecendo contexto fundamentad...","ru":"technical-constitution - это самохостящийся двиг РАГ, который принимает технические документы и кодовые репозитории локально, предоставляя основанный контекс...","ar":"technical-constitution هو مح