INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('asheshgoplani/agent-deck/session-share', 'session-share', 'asheshgoplani', 'agent-deck', 'community', 'session-share asheshgoplani agent-deck community session-share是一个终端会话管理器，用于管理AI智能代理的会话，支持多种AI工具，如Claude、Gemini、OpenCode、Codex等 session-shareは、AIエージェントのターミナルセッションを管理するためのツールです。Claude、Gemini、OpenCode、Codexなどに対応しています session-share는 AI 에이전트의 터미널 세션을 관리하는 데 사용되는 도구로, Claude, Gemini, OpenCode, Codex 등 여러 AI 툴을 지원합니다 Session-share es un administrador de sesiones de terminal para Agentes de IA, ofreciendo una interfaz de usuario única para Claude, Gemini, OpenCode, Codex y más Session-share est un gestionnaire de sessions de terminal pour Agents IA, offrant une interface utilisateur unique pour Claude, Gemini, OpenCode, Codex et plus Session-share ist ein Terminal-Sitzungs-Manager für KI-Agents, der eine einheitliche Benutzeroberfläche für Claude, Gemini, OpenCode, Codex und mehr bietet O session-share é um gerenciador de sessão de terminal para ferramentas de IA, oferecendo uma interface de usuário única para Claude, Gemini, OpenCode e mais Session-share - менеджер терминальных сессий для ИИ Агентов, предоставляющий единую консоль для Claude, Gemini, OpenCode и других session-share هو مدير جلسات Терمينال لأدوات الذكاء الاصطناعي، يقدم واجهة مستخدم موحدة ل Claude و Gemini و OpenCode وغيرها Terminal session manager for AI coding agents. One TUI for Claude, Gemini, OpenCode, Codex, and more. AI智能代理 终端会话管理 session-share AI工具 Claude Gemini OpenCode Codex 如何使用session-share session-share安装指南 Terminal session manager for AI coding agents. One TUI for Claude, Gemini, OpenCode, Codex, and more.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OleksandrKucherenko/e-bash/shellspec', 'community', 'OleksandrKucherenko', 'e-bash', 'OleksandrKucherenko/e-bash', 'shellspec', 0, 0, 60, '2026-03-04T13:07:01.901Z', '2026-03-04T14:57:00.073Z', 'd77f66933def4a44e841e3b972341967c4fbc0783f7b350c27cc3ce053da9762', '{"id":"OleksandrKucherenko/e-bash/shellspec","name":"shellspec","description":{"zh":"shellspec是一组BASH脚本，用于简化项目维护，包括版本管理、依赖关系、工具和CI/CD等","ja":"shellspecは、バージョン管理、依存関係、ツール、CI/CDなどを含むプロジェクトメンテナンスを簡素化するBASHスクリプトのセットです","ko":"shellspec는 버전 관리, 의존성, 도구 및 CI/CD 등을 포함한 프로젝트 유지 보수를 간소화하는 BASH 스크립트 세트입니다","es":"shellspec es una herramienta de AI que facilita el mantenimiento de proyectos con scripts BASH para versiones, dependencias, herramientas y más","fr":"shellspec est un outil IA qui facilite la maintenance de projets avec des scripts BASH pour les versions, les dépendances, les outils et plus","de":"shellspec ist ein KI-Tool, das die Projektwartung mit BASH-Skripten für Versionen, Abhängigkeiten, Tools und mehr erleichtert","pt":"O Shellspec é uma ferramenta que oferece scripts BASH para facilitar a manutenção de projetos, incluindo versionamento e gerenciamento de dependências","ru":"Shellspec - это инструмент, который предоставляет скрипты BASH для упрощения поддержки проектов, включая версионирование и управление зависимостями","ar":"شيلسبك هو أداة توفر سكريبتات BASH لتسهيل صيانة المشاريع، بما في ذلك إدارة النسخ وإدارة الاعتمادات","en":"Helper BASH scripts that make any project maintenance easier. versioning, dependencies, tools, CI/CD etc. "},"seo":{"title":{"zh":"AI工具 shellspec：项目维护BASH脚本","ja":"AIエージェント shellspec：プロジェクトメンテナンス用BASHスクリプト","ko":"AI 에이전트 shellspec: 프로젝트 유지 보수용 BASH 스크립트","es":"Herramientas de AI: shellspec para mantenimiento de proye...","fr":"Outils IA : shellspec pour la maintenance de projets","de":"KI-Tools: shellspec für Projektwartung","pt":"Ferramentas de Manutenção de Projeto com Shellspec","ru":"ИИ Агенты: Shellspec для Упрощения Проектной Поддержки","ar":"أدوات إدارة المشاريع مع Shellspec","en":"shellspec"},"description":{"zh":"shellspec是一组BASH脚本，用于简化项目维护，包括版本管理、依赖关系、工具和CI/CD等","ja":"shellspecは、バージョン管理、依存関係、ツール、CI/CDなどを含むプロジェクトメンテナンスを簡素化するBASHスクリプトのセットです","ko":"shellspec는 버전 관리, 의존성, 도구 및 CI/CD 등을 포함한 프로젝트 유지 보수를 간소화하는 BASH 스크립트 세트입니다","es":"shellspec es una herramienta de AI que facilita el mantenimiento de proyectos con scripts BASH para versiones, dependencias, herramientas y más","fr":"shellspec est un outil IA qui facilite la maintenance de projets avec des scripts BASH pour les versions, les dépendances, les outils et plus","de":"shellspec ist ein KI-Tool, das die Projektwartung mit BASH-Skripten für Versionen, Abhängigkeiten, Tools und mehr erleichtert","pt":"O Shellspec é uma ferramenta que oferece scripts BASH para facilitar a manutenção de projetos, incluindo versionamento e gerenciamento de dependências","ru":"Shellspec - это инструмент, который предоставляет скрипты BASH для упрощения поддержки проектов, включая версионирование и управление зависимостями","ar":"شيلسبك هو أداة توفر سكريبتات BASH لتسهيل صيانة المشاريع، بما في ذلك إدارة النسخ وإدارة الاعتمادات","en":"Helper BASH scripts that make any project maintenance easier. versioning, dependencies, tools, CI/CD etc. "},"definition":{"en":"Helper BASH scripts that make any project maintenance easier. versioning, dependencies, tools, CI/CD etc. "},"features":{"zh":["版本管理","依赖关系管理","工具集成","CI/CD支持","BASH脚本"],"ja":["バージョン管理","依存関係管理","ツール統合","CI/CDサポート","BASHスクリプト"],"ko":["버전 관리","의존성 관리","도구 통합","CI/CD 지원","BASH 스크립트"],"es":["Versiones y dependencias","Herramientas de CI/CD","Scripts BASH personalizables","Integración con herramientas de desarrollo","Mantenimiento de proyectos simplificado"],"fr":["Versions et dépendances","Outils de CI/CD","Scripts BASH personnalisables","Intégration avec des outils de développement","Maintenance de projets simplifiée"],"de":["Versionen und Abhängigkeiten","CI/CD-Tools","Anpassbare BASH-Skripte","Integration mit Entwicklungstools","Vereinfachte Projektwartung"],"pt":["Scripts BASH para versionamento","Gerenciamento de dependências","Ferramentas de CI/CD","Simplificação da manutenção de projetos"],"ru":["Скрипты BASH для версионирования","Управление зависимостями","Инструменты CI/CD","Упрощение поддержки проектов"],"ar":["سكريبتات BASH للنسخ","إدارة الاعتمادات","أدوات CI/CD","تبسيط صيانة المشاريع"]},"keywords":{"zh":["如何使用shellspec","什么是shellspec","shellspec替代品","shellspec与其他工具的比较","shellspec安装","shellspec设置指南","BASH脚本项目维护","CI/CD工具"],"ja":["shellspecの使い方","shellspecとは","shellspecの代替","shellspecと他のツールの比較","shellspecのインストール","shellspecの設定ガイド","BASHスクリプトによるプロジェクトメンテナンス","CI/CDツール"],"ko":["shellspec 사용 방법","shellspec란","shellspec 대체","shellspec와 다른 도구 비교","shellspec 설치","shellspec 설정 가이드","BASH 스크립트를 사용한 프로젝트 유지 보수","CI/CD 도구"],"es":["herramientas de AI para proyectos","cómo usar shellspec","shellspec vs herramientas de mantenimiento","instalación de shellspec","guía de configuración de shellspec","mejores prácticas para el mantenimiento de proyectos"],"fr":["outils IA pour les projets","comment utiliser shellspec","shellspec vs outils de maintenance","installation de shellspec","guide de configuration de shellspec","meilleures pratiques pour la maintenance de projets"],"de":["KI-Tools für Projekte","wie man shellspec verwendet","shellspec vs Wartungstools","Installation von shellspec","Konfigurationsanleitung für shellspec","beste Praktiken für die Projektwartung"],"pt":["como usar Shellspec","o que é Shellspec","Shellspec alternativa","Shellspec vs outras ferramentas","instalar Shellspec","guia de configuração do Shellspec"],"ru":["как использовать Shellspec","что такое Shellspec","альтернативы Shellspec","Shellspec vs другие инструменты","установка Shellspec","руководство по настройке Shellspec"],"ar":["كيفية استخدام شيلسبك","ما هو شيلسبك","بديل شيلسبك","شيلسبك مقابل أدوات أخرى","تثبيت شيلسبك","دليل إعداد شيلسبك"]}},"owner":"OleksandrKucherenko","repo":"e-bash","repoPath":"OleksandrKucherenko/e-bash","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.901Z","topics":[],"category":"community","skillMd":{"name":"shellspec","description":"Comprehensive unit testing framework for Bash and POSIX shell scripts using ShellSpec with TDD/BDD best practices. Use when writing tests for shell scripts, debugging test failures, refactoring scripts for testability, setting up test infrastructure, mocking external dependencies, or implementing test-driven development for Bash/shell projects. Covers test structure, isolation, mocking, output capture, coverage, CI integration, and troubleshooting.","bodyPreview":"# ShellSpec Unit Testing Guide\n\nShellSpec is a full-featured BDD unit testing framework for bash, ksh, zsh, dash and all POSIX shells. It brings professional-grade Test-Driven Development (TDD) practices to shell scripting.\n\n**Think of ShellSpec as**: A translator between natural language test intentions and shell execution verification - like having a bilingual interpreter who understands both \"what you want to test\" and \"how shells actually work.\"\n\n## Quick Start\n\n### Installation\n\n```bash\n# I","body":"# ShellSpec Unit Testing Guide\n\nShellSpec is a full-featured BDD unit testing framework for bash, ksh, zsh, dash and all POSIX shells. It brings professional-grade Test-Driven Development (TDD) practices to shell scripting.\n\n**Think of ShellSpec as**: A translator between natural language test intentions and shell execution verification - like having a bilingual interpreter who understands both \"what you want to test\" and \"how shells actually work.\"\n\n## Quick Start\n\n### Installation\n\n```bash\n# Install ShellSpec\ncurl -fsSL https://git.io/shellspec | sh -s -- -y\n\n# Initialize project\nshellspec --init\n```\n\n### Basic Test Example\n\n```bash\n# lib/calculator.sh\nadd() { echo \"$(($1 + $2))\"; }\n\n# spec/calculator_spec.sh\nDescribe ''Calculator''\n  Include lib/calculator.sh\n  \n  It ''performs addition''\n    When call add 2 3\n    The output should eq 5\n  End\nEnd\n```\n\n**Run tests**: `shellspec`\n\n## Project Structure\n\n```\nproject/\n├── .shellspec              # Project configuration (mandatory)\n├── .shellspec-local        # Local overrides (gitignored)\n├── lib/                    # Production code\n│   ├── module1.sh\n│   └── module2.sh\n├── spec/                   # Test specifications\n│   ├── spec_helper.sh      # Global test setup\n│   ├── support/            # Shared test utilities\n│   │   ├── mocks.sh\n│   │   └── helpers.sh\n│   └── lib/\n│       ├── module1_spec.sh\n│       └── module2_spec.sh\n├── coverage/               # Coverage reports (generated)\n└── report/                 # Test reports (generated)\n```\n\n## Test Structure\n\n### DSL Hierarchy\n\n```bash\nDescribe ''Feature Name''              # Top-level grouping\n  BeforeEach ''setup_function''        # Runs before each test\n  AfterEach ''cleanup_function''       # Runs after each test\n  \n  Context ''when condition X''         # Scenario grouping\n    It ''behaves in way Y''            # Individual test\n      # GIVEN: Setup (arrange)\n      local input=\"test data\"\n      \n      # WHEN: Execute (act)\n      When call function_under_test \"$input\"\n      \n      # THEN: Verify (assert)\n      The output should equal \"expected\"\n      The status should be success\n    End\n  End\nEnd\n```\n\n**Analogy**: Think of tests like a filing cabinet - `Describe` is the drawer, `Context` is the folder, `It` is the document.\n\n### Execution Modes\n\n| Mode              | Use Case            | Isolation         | Coverage |\n| ----------------- | ------------------- | ----------------- | -------- |\n| `When call func`  | Unit test functions | Same shell (fast) | Yes      |\n| `When run script` | Integration test    | New process       | Yes      |\n| `When run source` | Hybrid approach     | Subshell          | Yes      |\n\n**Recommended**: Use `When call` for unit tests (fastest), `When run script` for integration tests.\n\n## Making Scripts Testable\n\n### Pattern 0: Logger-Driven Testability (Foundation)\n\n**Analogy**: Like a black box flight recorder - captures execution paths for post-flight analysis, enabling verification of which code branches executed.\n\nFor scripts verification via tests, use the project''s logger (`.scripts/_logger.sh`). Each module declares its own unique logger tag that can be partially enabled or disabled via the `DEBUG` environment variable.\n\n**Module Setup**:\n\n```bash\n#!/bin/bash\n# my_module.sh\n\n# shellcheck source=.scripts/_logger.sh\nsource \"${E_BASH:-$(dirname \"$0\")}/_logger.sh\"\n\nprocess_data() {\n  local input=\"$1\"\n  \n  if [[ -z \"$input\" ]]; then\n    echo:Mymodule \"validation failed: empty input\"\n    return 1\n  fi\n  \n  echo:Mymodule \"processing: $input\"\n  # ... actual processing ...\n  echo:Mymodule \"completed successfully\"\n  return 0\n}\n\n# DO NOT allow execution of code bellow those line in shellspec tests\n${__SOURCED__:+return}\n\n# Declare unique logger for this module\nlogger:init \"mymodule\" \"[mymodule] \" \">&2\"\n\n```\n\n**Controlling Logger Output**:\n\n```bash\n# Enable specific loggers via DEBUG variable\nDEBUG=mymodule ./my_module.sh       # Enable only ''mymodule'' logger\nDEBUG=mymodule,hooks ./my_module.sh # Enable multiple loggers\nDEBUG=* ./my_module.sh              # Enable all loggers\nDEBUG=*,-mymodule ./my_module.sh    # Enable all except ''mymodule''\n```\n\n**Test Verification Strategy**:\n\n```bash\nDescribe ''my_module''\n  Include .scripts/_logger.sh\n  Include my_module.sh\n  \n  # Helper functions to strip ANSI color codes for comparison\n  # $1 = stdout, $2 = stderr, $3 = exit status\n  no_colors_stderr() { echo -n \"$2\" | sed -E $''s/\\x1B\\\\[[0-9;]*[A-Za-z]//g; s/\\x1B\\\\([A-Z]//g; s/\\x0F//g'' | tr -s '' ''; }\n  no_colors_stdout() { echo -n \"$1\" | sed -E $''s/\\x1B\\\\[[0-9;]*[A-Za-z]//g; s/\\x1B\\\\([A-Z]//g; s/\\x0F//g'' | tr -s '' ''; }\n  \n  BeforeEach ''enable_logger''\n  enable_logger() {\n    TAGS[mymodule]=1  # Enable logger output for verification\n  }\n  \n  Context ''when input is empty''\n    It ''logs validation failure and returns error''\n      When call process_data \"\"\n      The status should be failure\n      # Verify execution path via logger output\n      The stderr should include \"validation failed: empty input\"\n    End\n  End\n  \n  Context ''when input is valid''\n    It ''logs processing steps and succeeds''\n      When call process_data \"test-data\"\n      The status should be success\n      # Verify which branch executed via log messages\n      The result of no_colors_stderr should include \"processing: test-data\"\n      The result of no_colors_stderr should include \"completed successfully\"\n    End\n  End\nEnd\n```\n\n**Testability Balance**: Achieve comprehensive test coverage by combining:\n\n| Verification Method | Use Case                                    | Example                                                                    |\n| ------------------- | ------------------------------------------- | -------------------------------------------------------------------------- |\n| **Logger output**   | Verify execution paths, internal decisions  | `The stderr should include user-friendly message like \"branch A executed\"` |\n| **stdout**          | Verify user-facing output, function results | `The output should eq \"result\"`                                            |\n| **stderr**          | Verify error messages, warnings             | `The error should include \"warning\"`                                       |\n| **Exit status**     | Verify success/failure outcomes             | `The status should be failure`                                             |\n| **Mocks/Spies**     | Verify external command calls in isolation  | `Mock curl; ...; End`                                                      |\n\n**Test Isolation Pattern** (Mocking Logger Functions):\n\nThe practical approach used in tests is to:\n1. Set `DEBUG=tag` once at the file level to enable specific logger(s)\n2. Mock `logger:init` to suppress logger initialization side effects\n3. Mock `echo:Tag` and `printf:Tag` functions to redirect output for verification\n\n```bash\n#!/usr/bin/env bash\n# spec/mymodule_spec.sh\n\neval \"$(shellspec - -c) exit 1\"\n\n# 1. Enable debug output for this module at file level\nexport DEBUG=\"mymodule\"\n\n# 2. Mock logger initialization to prevent side effects\nMock logger:init\n  return 0\nEnd\n\n# 3. Mock logger output functions - redirect to stderr for test verification\nMock printf:Mymodule\n  printf \"$@\" >&2\nEnd\n\nMock echo:Mymodule\n  echo \"$@\" >&2\nEnd\n\n# Helper to strip ANSI color codes for comparison\n# $1 = stdout, $2 = stderr, $3 = exit status\nno_colors_stderr() { \n  echo -n \"$2\" | sed -E $''s/\\x1B\\\\[[0-9;]*[A-Za-z]//g; s/\\x1B\\\\([A-Z]//g; s/\\x0F//g'' | tr -s '' ''\n}\n\nInclude \".scripts/mymodule.sh\"\n\nDescribe ''mymodule''\n  It ''verifies execution path via logger output''\n    When call process_data \"test\"\n\n    The status should be success\n    # Verify which code branch executed via logger messages\n    The result of function no_colors_stderr should include \"processing: test\"\n  End\nEnd\n```\n\n**Alternative: Suppress Logger Output Entirely**:\n\nWhen you don''t need to verify logger output but want to prevent noise:\n\n```bash\n# Mock logger functions to suppress all output\nMock echo:Mymodule\n  :  # No-op - silently ignore\nEnd\n\nMock printf:Mymodule\n  :  # No-op - silently ignore\nEnd\n```\n\n**Pros**: Precise verification of code paths, debuggable tests, controlled verbosity\n**Cons**: Requires logger discipline in production code\n**Recommended action**: Add unique logger to each module, use `DEBUG=tag` to control output, verify logs in tests\n\n### Pattern 1: Source Guard (Critical)\n\n**Analogy**: Like a bouncer at a club - decides whether to let execution in based on context.\n\n```bash\n#!/bin/bash\n# my_script.sh\n\n# Testable functions\nprocess_data() {\n  validate_input \"$1\" || return 1\n  transform_data \"$1\"\n}\n\nvalidate_input() {\n  [[ -n \"$1\" ]] || return 1\n}\n\n# Source guard - prevents execution when sourced\nif [[ \"${BASH_SOURCE[0]}\" == \"${0}\" ]]; then\n  # Only runs when executed, not when sourced for testing\n  process_data \"$@\"\nfi\n```\n\n**Test file**:\n```bash\nDescribe ''my_script''\n  Include my_script.sh  # Loads functions without executing\n  \n  It ''validates input''\n    When call validate_input \"\"\n    The status should be failure\n  End\nEnd\n```\n\n**Pros**: Functions become unit-testable, zero test pollution in production code\n**Cons**: Requires discipline, legacy scripts need refactoring\n**Recommended action**: Always add source guards to new scripts\n\n### Pattern 2: Extract Functions from Pipelines\n\n```bash\n# ❌ BAD: Untestable inline pipeline\ncat /etc/passwd | grep \"^${USER}:\" | cut -d: -f6\n\n# ✅ GOOD: Testable functions\nget_user_home() {\n  local user=\"${1:-$USER}\"\n  grep \"^${user}:\" /etc/passwd | cut -d: -f6\n}\n\nprocess_user_homes() {\n  local home\n  home=$(get_user_home \"$1\")\n  [[ -n \"$home\" ]] && check_bashrc \"$home\"\n}\n```\n\n**Recommended action**: Extract every logical step into a named function\n\n### Pattern 3: Exit Call Interception for Testability\n\n**Problem**: Functions that call `exit 1` terminate the entire test suite, making them untestable.\n\n**Real Example**:\n```bash\nfunction check_working_tree_clean() {\n    if ! git diff-index --quiet HEAD --; then\n        echo \"❌ You have uncommitted changes.\"\n        exit 1  # ❌ Terminates entire test suite\n    fi\n}\n```\n\n**Solution**: Function-specific mocking that preserves logic but replaces `exit` with `return`:\n\n```bash\nDescribe ''git verification''\n  It ''prevents patching with uncommitted changes''\n    # Modify tracked file to create uncommitted changes\n    echo \"modification\" >> test_file.txt\n\n    # Mock the function to avoid test termination\n    check_working_tree_clean() {\n      if ! git diff-index --quiet HEAD --; then\n        echo \"❌ You have uncommitted changes.\"\n        return 1  # Return 1 instead of exit 1\n      fi\n      return 0\n    }\n\n    When call check_working_tree_clean\n    The status should be failure\n    The stderr should include \"uncommitted changes\"\n  End\nEnd\n```\n\n**Key Learning**: Test what the function does (detect uncommitted changes) rather than how it does it (calling exit).\n\n**Pros**: Makes functions with exit calls testable without modifying production code\n**Cons**: Requires duplicating function logic in tests\n**Recommended action**: For new code, use `return` instead of `exit` in library functions. For existing code, use the mock pattern above.\n\n## Dependency Isolation and Mocking\n\n### Three-Tier Mocking Strategy\n\n**1. Function-Based Mocks** (Fastest)\n```bash\nDescribe ''function mocking''\n  date() { echo \"2024-01-01 00:00:00\"; }\n  \n  It ''uses mocked date''\n    When call get_timestamp\n    The output should eq \"2024-01-01 00:00:00\"\n  End\nEnd\n```\n\n**2. Mock Block** (Cleaner)\n```bash\nDescribe ''command mocking''\n  Mock curl\n    echo ''{\"status\": \"success\"}''\n    return 0\n  End\n  \n  It ''handles API response''\n    When call fetch_data\n    The output should include \"success\"\n  End\nEnd\n```\n\n**3. Intercept Pattern** (For Built-ins)\n```bash\nDescribe ''intercepting built-ins''\n  Intercept command\n  \n  __command__() {\n    if [[ \"$2\" == \"rm\" ]]; then\n      echo \"MOCK: rm intercepted\"\n      return 0\n    fi\n    command \"$@\"\n  }\n  \n  It ''safely mocks dangerous operations''\n    When run source ./cleanup_script.sh\n    The output should include \"MOCK: rm intercepted\"\n  End\nEnd\n```\n\n**Decision Matrix**:\n\n| Dependency                  | Mock?       | Rationale           |\n| --------------------------- | ----------- | ------------------- |\n| Network (curl, wget)        | ✅ Always    | Slow, unreliable    |\n| Date/time                   | ✅ Always    | Reproducibility     |\n| Random values               | ✅ Always    | Deterministic tests |\n| System commands (grep, sed) | ❌ Rarely    | Fast, stable        |\n| File I/O                    | ⚠️ Sometimes | Use temp dirs       |\n\n**Recommended action**: Mock boundaries (network, time, random), trust stable commands\n\n## Output Capture and Comparison\n\n### Capturing stdout, stderr, and exit status\n\n```bash\nIt ''captures all output streams''\n  When call function_with_output\n  The output should eq \"stdout message\"      # stdout\n  The error should eq \"error message\"        # stderr\n  The status should be success               # exit code (0)\nEnd\n```\n\n### Comparing Without Color Codes\n\n```bash\n# Helper functions to strip ANSI color codes for comparison\n# $1 = stdout, $2 = stderr, $3 = exit status\nno_colors_stderr() { echo -n \"$2\" | sed -E $''s/\\x1B\\\\[[0-9;]*[A-Za-z]//g; s/\\x1B\\\\([A-Z]//g; s/\\x0F//g'' | tr -s '' ''; }\nno_colors_stdout() { echo -n \"$1\" | sed -E $''s/\\x1B\\\\[[0-9;]*[A-Za-z]//g; s/\\x1B\\\\([A-Z]//g; s/\\x0F//g'' | tr -s '' ''; }\n\nIt ''compares without colors''\n  When call colored_output\n  The result of no_colors_stdout should eq \"Plain text\"\n  The result of no_colors_stderr should eq \"Plain text\"\nEnd\n\n# Alternative: Disable colors via environment\nIt ''disables colors''\n  BeforeCall ''export NO_COLOR=1''\n  BeforeCall ''export TERM=dumb''\n  When call my_command\n  The output should not include pattern ''\\x1B\\[''\nEnd\n```\n\n**Recommended action**: Set `NO_COLOR=1` in test environment to avoid color-stripping\n\n## Test Environment Management\n\n### Temporary Directories\n\n```bash\neval \"$(shellspec - -c) exit 1\"\n\n# shellcheck disable=SC2288\n% TEST_DIR: \"$SHELLSPEC_TMPBASE/tmprepo\"\n\nDescribe ''isolated environment''\n  BeforeEach ''setup_test_env''\n  AfterEach ''cleanup_test_env''\n  \n  setup_test_env() {\n    mkdir -p \"$TEST_DIR\" || true\n    cd \"$TEST_DIR\" || exit 1\n  }\n  \n  cleanup_test_env() {\n    cd - >/dev/null\n    rm -rf \"$TEST_DIR\"\n  }\n  \n  It ''works in isolation''\n    When call touch test.txt\n    The path test.txt should be file\n  End\nEnd\n```\n\n**Pros**: Complete isolation, no test interference\n**Cons**: Requires discipline in cleanup\n**Recommended action**: Always use temp dirs, never write to fixed paths\n\n### Parameterized Tests\n\n```bash\nDescribe ''data-driven tests''\n  Parameters\n    \"#1\" \"valid\"   \"success\" 0\n    \"#2\" \"invalid\" \"error\"   1\n    \"#3\" \"empty\"   \"missing\" 1\n  End\n  \n  It \"handles $1 input\"\n    When call validate \"$2\"\n    The output should include \"$3\"\n    The status should eq $4\n  End\nEnd\n```\n\n**Recommended action**: Use Parameters to avoid copy-paste test code\n\n## Code Coverage\n\n### Enable Coverage\n\n```bash\n# .shellspec configuration\n--kcov\n--kcov-options \"--include-pattern=.sh\"\n--kcov-options \"--exclude-pattern=/spec/,/coverage/\"\n--kcov-options \"--fail-under-percent=80\"\n\n# Run with coverage\nshellspec --kcov\n\n# View report\nopen coverage/index.html\n```\n\n**Coverage Goals**:\n- Critical paths: 100%\n- Main functionality: 80-90%\n- Utility functions: 70-80%\n\n**Recommended action**: Enable coverage from day 1, set minimum thresholds\n\n## Test Execution\n\n### Running Tests\n\n```bash\n# All tests\nshellspec\n\n# Specific file\nshellspec spec/module_spec.sh\n\n# Specific line\nshellspec spec/module_spec.sh:42\n\n# Only previously failed\nshellspec --quick\n\n# Stop on first failure\nshellspec --fail-fast\n\n# Parallel execution (4 jobs)\nshellspec --jobs 4\n\n# With debug trace\nshellspec --xtrace\n\n# Focus mode (run only fIt, fDescribe)\nshellspec --focus\n```\n\n### Focus Mode for TDD\n\n```bash\nDescribe ''feature under development''\n  fIt ''focused test - runs only this''\n    When call new_feature\n    The status should be success\n  End\n  \n  It ''other test - skipped during focus''\n    When call other_feature\n  End\nEnd\n```\n\n**Recommended action**: Use `--quick` and `--focus` for rapid TDD cycles\n\n## Cross-Platform Testing\n\n### GNU vs BSD Tool Compatibility\n\n**Problem**: Shell scripts that work on Linux (GNU tools) often fail on macOS (BSD tools) due to command syntax differences.\n\n**Common Differences**:\n\n| Feature         | GNU (Linux)          | BSD (macOS)          | Portable Alternative    |\n| --------------- | -------------------- | -------------------- | ----------------------- |\n| Remove last line | `head -n -1`         | Not supported        | `sed ''$d''`              |\n| Remove first line | `tail -n +2`        | Works differently    | `sed ''1d''`              |\n| In-place editing | `sed -i ''s/old/new''` | `sed -i '''' ''s/...''`  | Use `sponge` or temp file |\n\n**Real Example**: Function to display function body\n\n```bash\n# ❌ GNU-only - fails on macOS\nshow_function() {\n  declare -f \"$1\" | tail -n +3 | head -n -1\n}\n\n# ✅ Cross-platform - works on both\nshow_function() {\n  declare -f \"$1\" | tail -n +3 | sed ''$d''\n}\n```\n\n**Test Detection Pattern**:\n```bash\n# Test failure on macOS looks like:\nhead: illegal line count -- -1\n```\n\n**Best Practices**:\n\n1. **Use portable alternatives by default**:\n```bash\n# Instead of: head -n -1 (remove last N lines)\nUse: sed ''$d''              # Delete last line\n\n# Instead of: tail -n +2 (skip first N lines)\nUse: sed ''1d''              # Delete first line\n```\n\n2. **Test on multiple platforms**:\n```yaml\n# .github/workflows/test.yml\njobs:\n  test:\n    strategy:\n      matrix:\n        os: [ubuntu-latest, macos-latest]\n    runs-on: ${{ matrix.os }}\n    steps:\n      - run: shellspec --kcov\n```\n\n3. **Use conditional logic only when necessary**:\n```bash\n# Detect platform when you must use different approaches\nif [[ \"$(uname -s)\" == \"Darwin\" ]]; then\n  # BSD-specific code\n  sed -i '''' ''s/old/new'' file\nelse\n  # GNU-specific code\n  sed -i ''s/old/new'' file\nfi\n```\n\n4. **Document platform-specific requirements** in your README\n\n**Prevention Checklist**:\n- [ ] Avoid `head -n -N` (negative line counts)\n- [ ] Avoid `tail -n +N` for offset beyond first line\n- [ ] Use portable `sed ''$d''` instead of `head -n -1`\n- [ ] Test on both Linux and macOS in CI\n- [ ] Document any platform-specific dependencies\n\n**Recommended action**: Always prefer portable commands, use platform detection only when unavoidable\n\n## CI/CD Integration\n\n### JUnit Reports\n\n```bash\n# .shellspec configuration\n--format junit\n--output report/junit.xml\n\n# Run in CI\nshellspec --kcov --format junit\n```\n\n### GitHub Actions Example\n\n```yaml\nname: ShellSpec Tests\non: [push, pull_request]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: actions/checkout@v3\n    - name: Install ShellSpec\n      run: curl -fsSL https://git.io/shellspec | sh -s -- -y\n    - name: Run tests\n      run: shellspec --kcov --format junit\n    - name: Upload coverage\n      uses: codecov/codecov-action@v3\n```\n\n**Recommended action**: Generate JUnit reports for CI integration\n\n## Troubleshooting\n\n### Debug Failed Tests\n\n```bash\n# Show execution trace\nshellspec --xtrace spec/failing_spec.sh\n\n# Check spec syntax\nshellspec --syntax-check spec/failing_spec.sh\n\n# See generated shell code\nshellspec --translate spec/failing_spec.sh\n\n# Inspect output during test\nIt ''debugs with Dump''\n  When call my_function\n  Dump  # Shows stdout, stderr, status\n  The output should not be blank\nEnd\n```\n\n### Common Issues\n\n**Problem**: File assertion fails even though code works correctly\n**Solution**: This is caused by ShellSpec''s execution order - `After` hooks run BEFORE file assertions\n\n**Critical: ShellSpec Execution Order Violation**\n\nShellSpec''s execution order violates the expected \"setup → test → cleanup\" flow:\n\n```\n# Expected flow: setup → test → cleanup\n# Actual flow: setup → test → After hooks → assertions → cleanup\n```\n\n**The Problem**: `After` hooks run **BEFORE** file assertions are evaluated. Any file cleanup in `After` will delete files before assertions can check them.\n\n**Pattern**: Negative assertions can mask cleanup issues, while positive assertions expose them.\n\n```bash\n# ✅ Negative assertions often pass (deleted file doesn''t contain content)\nThe file \".config\" should not include \"removed_setting\"\n\n# ❌ Positive assertions fail (file no longer exists after cleanup)\nThe file \".config\" should include \"preserved_setting\"\n```\n\n**The Fix**: Capture file content in the same execution as the command:\n\n```bash\n# ❌ WRONG - File assertion happens AFTER After hooks\nIt ''should check file content after command''\n  When run ./my_script.sh\n  The file \".config\" should include \"important_setting\"\nEnd\n\n# ✅ CORRECT - Capture content in same execution\nIt ''should check file content after command''\n  When run sh -c ''./my-script.sh && cat .config''\n  The output should include \"important_setting\"\nEnd\n\n# ✅ EVEN BETTER - Use separator for clarity\nIt ''should modify files and verify content''\n  When run sh -c ''./script.sh && echo \"=== FILE: config ===\" && cat config''\n  The output should include \"=== FILE: config ===\"\n  The output should include \"important_setting\"\nEnd\n```\n\n**When to Suspect This Issue**:\n- Test checks `The file \"somefile\" should include \"content\"`\n- Test runs a command that creates/modifies files\n- Test has `After` cleanup hooks\n- Manual verification shows the code works correctly\n\n**Problem**: \"Evaluation has already been executed. Only one Evaluation allow per Example.\"\n**Solution**: ShellSpec enforces exactly one `When run` per example - chain commands instead\n\n**One-Evaluation Rule**\n\n```bash\n# ❌ WRONG - Multiple evaluations not allowed\nIt ''should verify multiple things''\n  When run ./script.sh\n  When run cat result.txt  # ERROR: Evaluation already executed\n  The output should include \"success\"\nEnd\n\n# ✅ CORRECT - Chain commands in single execution\nIt ''should verify multiple things''\n  When run sh -c ''./script.sh && echo \"=== SEPARATOR ===\" && cat result.txt''\n  The output should include \"success\"\n  The output should include \"=== SEPARATOR ===\"\nEnd\n```\n\n**Problem**: Test passes alone but fails in suite\n**Solution**: Check for global state leakage, ensure cleanup in `AfterEach`\n\n**Problem**: Can''t mock external command\n**Solution**: Use `Mock` block or `Intercept` for built-ins\n\n**Problem**: Tests are slow\n**Solution**: Enable parallel execution with `--jobs 4`\n\n**Problem**: Coverage doesn''t work\n**Solution**: Ensure kcov is installed, check `--kcov-options`\n\n## Best Practices Checklist\n\n- [ ] All scripts have source guards\n- [ ] External dependencies are mocked\n- [ ] Tests use temporary directories\n- [ ] Each test verifies one behavior\n- [ ] Tests follow GIVEN/WHEN/THEN structure\n- [ ] Coverage is enabled and > 80%\n- [ ] Tests run in parallel (`--jobs`)\n- [ ] JUnit reports generated for CI\n- [ ] No hard-coded paths or commands\n- [ ] Side effects are documented and tested\n\n## Common Anti-Patterns to Avoid\n\n❌ **Global state mutation**\n```bash\nCOUNTER=0  # Bad: mutable global\nincrement() { COUNTER=$((COUNTER + 1)); }\n```\n\n✅ **Return values**\n```bash\nincrement() { echo $(($1 + 1)); }  # Good: pure function\ncounter=$(increment \"$counter\")\n```\n\n❌ **Testing implementation details**\n```bash\nIt ''calls grep with -E flag''  # Bad: too coupled\n```\n\n✅ **Testing behavior**\n```bash\nIt ''finds files matching pattern''  # Good: tests outcome\n```\n\n❌ **Unmocked network calls**\n```bash\nIt ''fetches real data'' curl https://api.com  # Bad: slow, flaky\n```\n\n✅ **Mocked dependencies**\n```bash\nMock curl; echo \"mock\"; End  # Good: fast, reliable\n```\n\n## Advanced Topics\n\nFor deeper coverage of advanced patterns, see:\n\n- **Advanced Patterns**: See [references/advanced-patterns.md](references/advanced-patterns.md) for complex mocking, spies, state management\n- **Troubleshooting Guide**: See [references/troubleshooting.md](references/troubleshooting.md) for systematic debugging\n- **Real-World Examples**: See [references/real-world-examples.md](references/real-world-examples.md) for production patterns from top OSS projects\n- **Collected Experience**: See [references/collected-experience.md](references/collected-experience.md) for lessons learned from multiple projects\n\n## Quick Reference\n\n```bash\n# Common commands\nshellspec                   # Run all tests\nshellspec --quick           # Re-run failures only\nshellspec --xtrace          # Debug trace\nshellspec --kcov            # With coverage\nshellspec --format junit    # JUnit output\n\n# DSL basics\nDescribe/Context/It/End     # Test structure\nWhen call/run/source        # Execution\nThe output/status/error     # Assertions\nMock/Intercept              # Mocking\nBeforeEach/AfterEach        # Hooks\nParameters                  # Data-driven tests\nDump                        # Debug helper\n```\n\n**Recommended action**: Start with simple unit tests, add coverage, then integrate into CI\n"},"lastSynced":"2026-03-04T14:57:00.073Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring advanced shell scripting and Test-Driven Development (TDD) capabilities in POSIX environments.","zh":"适用于需要高级shell脚本和测试驱动开发（TDD）功能的DevOps代理，在POSIX环境中。","ja":"POSIX環境で高度なシェルスクリプティングとテスト駆動開発（TDD）機能を必要とするDevOpsエージェントに適しています。","ko":"POSIX 환경에서 고급 셸 스크립팅 및 테스트 주도 개발(TDD) 기능을 필요로 하는 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren scripting de shell avanzado y capacidades de Desarrollo Dirigido por Pruebas (TDD) en entornos POSIX.","fr":"Idéal pour les agents DevOps nécessitant un scripting shell avancé et des capacités de développement piloté par les tests (TDD) dans des environnements POSIX.","de":"Ideal für DevOps-Agents, die erweitertes Shell-Scripting und Test-Driven Development (TDD)-Funktionen in POSIX-Umgebungen erfordern.","pt":"Ideal para Agentes DevOps que requerem capacidades avançadas de shell scripting e Desenvolvimento Orientado por Testes (TDD) em ambientes POSIX.","ru":"Идеально подходит для DevOps-агентов, требующих расширенных возможностей написания сценариев оболочки и разработки через тестирование (TDD) в POSIX-средах.","ar":"مثالي لوكلاء DevOps الذين يتطلبون قدرات متقدمة في كتابة نصوص Shell وتطوير يقوده الاختبار (TDD) في بيئات POSIX."},"recommendation":{"en":"Empowers agents to write unit tests for bash, ksh, zsh, and dash scripts using Behavior-Driven Development (BDD) practices, ensuring reliable and maintainable shell code through POSIX shell execution verification and natural language test intentions translation.","zh":"赋予代理编写bash、ksh、zsh和dash脚本的单元测试的能力，使用行为驱动开发（BDD）实践，通过POSIX shell执行验证和自然语言测试意图翻译，确保可靠且可维护的shell代码。","ja":"エージェントにbash、ksh、zsh、dashスクリプトのユニットテストを書く能力を与え、行動駆動開発（BDD）プラクティスを使用し、POSIXシェルの実行検証と自然言語のテスト意図の翻訳を通じて、信頼性が高く保守可能なシェルコードを確保します。","ko":"에이전트가 bash, ksh, zsh 및 dash 스크립트의 단위 테스트를 작성할 수 있는 능력을 부여하여 행동 주도 개발(BDD) 관행을 사용하고 POSIX 셸 실행 확인 및 자연어 테스트 의도 번역을 통해 안정적이고 유지 보수 가능한 셸 코드를 보장합니다.","es":"Habilita a los agentes a escribir pruebas unitarias para scripts bash, ksh, zsh y dash utilizando prácticas de Desarrollo Dirigido por el Comportamiento (BDD), garantizando un código de shell confiable y mantenible a través de la verificación de la ejecución de shell POSIX y la traducción de intenciones de pruebas de lenguaje natural.","fr":"Permet aux agents d''écrire des tests unitaires pour les scripts bash, ksh, zsh et dash en utilisant des pratiques de développement piloté par le comportement (BDD), garantissant un code shell fiable et maintenable grâce à la vérification de l''exécution du shell POSIX et à la traduction des intentions de test de langage naturel.","de":"Ermöglicht es Agenten, Unit-Tests für bash-, ksh-, zsh- und dash-Scripts unter Verwendung von Verhaltensgetriebener Entwicklung (BDD)-Praktiken zu schreiben, wodurch zuverlässiger und wartbarer Shell-Code durch POSIX-Shell-Ausführungsverifizierung und Übersetzung von Testabsichten in natürlicher Sprache sichergestellt wird.","pt":"Capacita os agentes a escrever testes unitários para scripts bash, ksh, zsh e dash usando práticas de Desenvolvimento Orientado por Comportamento (BDD), garantindo código shell confiável e sustentável por meio da verificação de execução de shell POSIX e tradução de intenções de teste em linguagem natural.","ru":"Позволяет агентам писать модульные тесты для сценариев bash, ksh, zsh и dash с использованием практик поведения, управляемого разработкой (BDD), обеспечивая надежный и сопровождаемый код оболочки за счет проверки выполнения POSIX shell и перевода намерений тестирования на естественный язык.","ar":"يمكن الوكلاء من كتابة اختبارات الوحدة لنصوص bash و ksh و zsh و dash باستخدام ممارسات التطوير القائم على السلوك (BDD)، مما يضمن كود Shell موثوقًا وقابلًا للصيانة من خلال التحقق من تنفيذ Shell POSIX وترجمة نوايا الاختبار إلى لغة طبيعية."},"useCases":{"en":["Automating shell script testing","Validating CI/CD pipeline scripts","Debugging complex bash scripts"],"zh":["自动化shell脚本测试","验证CI/CD管道脚本","调试复杂的bash脚本"],"ja":["シェルスクリプトのテストの自動化","CI/CDパイプラインスクリプトの検証","複雑なbashスクリプトのデバッグ"],"ko":["셸 스크립트 테스트 자동화","CI/CD 파이프라인 스크립트 검증","복잡한 bash 스크립트 디버깅"],"es":["Automatización de pruebas de scripts de shell","Validación de scripts de canalizaciones CI/CD","Depuración de scripts bash complejos"],"fr":["Automatisation des tests de scripts shell","Validation des scripts de pipeline CI/CD","Débogage de scripts bash complexes"],"de":["Automatisierung von Shell-Script-Tests","Validierung von CI/CD-Pipeline-Scripts","Fehlerbehebung in komplexen bash-Scripts"],"pt":["Automatização de testes de scripts shell","Validação de scripts de pipeline de CI/CD","Depuração de scripts bash complexos"],"ru":["Автоматизация тестирования сценариев оболочки","Проверка сценариев конвейера CI/CD","Отладка сложных сценариев bash"],"ar":["أتمتة اختبار نصوص Shell","التحقق من صحة نصوص خط أنابيب CI/CD","تصحيح أخطاء نصوص Bash المعقدة"]},"limitations":{"en":["Requires POSIX shell compatibility","Limited to shell scripting languages"],"zh":["需要POSIX shell兼容性","仅限shell脚本语言"],"ja":["POSIXシェルの互換性が必要","シェルスクリプト言語に限定される"],"ko":["POSIX 셸 호환성이 필요","셸 스크립트 언어로 제한"],"es":["Requiere compatibilidad con shell POSIX","Limitado a lenguajes de scripting de shell"],"fr":["Nécessite la compatibilité du shell POSIX","Limité aux langages de scripting shell"],"de":["Erfordert POSIX-Shell-Kompatibilität","Begrenzt auf Shell-Scripting-Sprachen"],"pt":["Requer compatibilidade com shell POSIX","Limitado a linguagens de script shell"],"ru":["Требует совместимости с POSIX shell","Ограничено языками написания сценариев оболочки"],"ar":["يتطلب توافقًا مع Shell POSIX","يقتصر على لغات كتابة نصوص Shell"]},"version":3},"contentHash":"d77f66933def4a44e841e3b972341967c4fbc0783f7b350c27cc3ce053da9762","qualityScore":60}');
