INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HoangNguyen0403/agent-skills-standard/Flutter Notifications', 'Flutter Notifications', 'HoangNguyen0403', 'agent-skills-standard', 'community', 'Flutter Notifications HoangNguyen0403 agent-skills-standard community Flutter通知是使用Firebase Cloud Messaging和flutter_local_notifications实现的推送通知和本地通知 Flutter通知はFirebase Cloud Messagingとflutter_local_notificationsを使用したプッシュ通知とローカル通知です Flutter 알림은 Firebase Cloud Messaging과 flutter_local_notifications를 사용하여 푸시 알림 및 로컬 알림을 구현합니다 Notificaciones push y locales para Flutter utilizando Firebase Cloud Messaging y flutter_local_notifications Notifications push et locales pour Flutter utilisant Firebase Cloud Messaging et flutter_local_notifications Push- und Lokalbenachrichtigungen für Flutter mit Firebase Cloud Messaging und flutter_local_notifications Notificações push e locais para Flutter usando Firebase Cloud Messaging e flutter_local_notifications Уведомления Flutter: push-уведомления и локальные уведомления с помощью Firebase Cloud Messaging и flutter_local_notifications إشعارات Flutter: إشعارات الضغط والمحلية باستخدام Firebase Cloud Messaging و flutter_local_notifications Push notifications and local notifications for Flutter using Firebase Cloud Messaging and flutter_local_notifications. Flutter通知实现 Firebase Cloud Messaging教程 flutter_local_notifications使用 Flutter推送通知 Flutter本地通知 AIエージェント技术 移动应用程序通知 Push notifications and local notifications for Flutter using Firebase Cloud Messaging and flutter_local_notifications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('langwatch/langwatch/e2e', 'community', 'langwatch', 'langwatch', 'langwatch/langwatch', 'e2e', 2833, 254, 59, '2026-02-24T16:59:56Z', '2026-02-26T08:27:17.695Z', '63e2b31f0fbd4aaed2474d2be69213131ebe35498abcea6fbf953d76de82a05f', '{"id":"langwatch/langwatch/e2e","name":"e2e","description":{"zh":"e2e平台为LLM评估和AI智能体测试提供了一个全面的解决方案，帮助开发者提高AI模型的性能和可靠性","ja":"e2eプラットフォームは、LLM評価とAIエージェントのテストのための包括的なソリューションを提供し、開発者がAIモデルのパフォーマンスと信頼性を向上させることができます","ko":"e2e 플랫폼은 LLM 평가 및 AI 에이전트 테스트를 위한 포괄적인 솔루션을 제공하여 개발자가 AI 모델의 성능과 신뢰성을 향상시킬 수 있습니다","es":"e2e es la plataforma para evaluar y probar agentes de AI y LLM, ideal para desarrolladores","fr":"e2e est la plateforme pour évaluer et tester les agents d''IA et LLM, idéale pour les développeurs","de":"e2e ist die Plattform für die Evaluierung und den Test von KI-Agents und LLM, ideal für Entwickler","pt":"A plataforma e2e é uma ferramenta de avaliação de LLM e teste de agentes de IA para desenvolvedores.","ru":"Платформа e2e - это инструмент для оценки LLM и тестирования ИИ агентов для разработчиков.","ar":"المنصة e2e هي أداة لتقييم LLM واختبار وكلاء الذكاء الاصطناعي للمطورين.","en":"The platform for LLM evaluations and AI agent testing"},"seo":{"title":{"zh":"AI智能体e2e评估和测试平台","ja":"AIエージェントのe2e評価とテストプラットフォーム","ko":"AI 에이전트 e2e 평가 및 테스트 플랫폼","es":"Herramientas de AI: Evaluación de LLM con e2e","fr":"Outils d''IA: Évaluation de LLM avec e2e","de":"KI-Tools: LLM-Evaluierung mit e2e","pt":"Ferramentas de IA: e2e para Avaliação de LLM","ru":"ИИ Агенты: e2e для Оценки LLM","ar":"أدوات الذكاء الاصطناعي: e2e لتقييم LLM","en":"e2e"},"description":{"zh":"e2e平台为LLM评估和AI智能体测试提供了一个全面的解决方案，帮助开发者提高AI模型的性能和可靠性","ja":"e2eプラットフォームは、LLM評価とAIエージェントのテストのための包括的なソリューションを提供し、開発者がAIモデルのパフォーマンスと信頼性を向上させることができます","ko":"e2e 플랫폼은 LLM 평가 및 AI 에이전트 테스트를 위한 포괄적인 솔루션을 제공하여 개발자가 AI 모델의 성능과 신뢰성을 향상시킬 수 있습니다","es":"e2e es la plataforma para evaluar y probar agentes de AI y LLM, ideal para desarrolladores","fr":"e2e est la plateforme pour évaluer et tester les agents d''IA et LLM, idéale pour les développeurs","de":"e2e ist die Plattform für die Evaluierung und den Test von KI-Agents und LLM, ideal für Entwickler","pt":"A plataforma e2e é uma ferramenta de avaliação de LLM e teste de agentes de IA para desenvolvedores.","ru":"Платформа e2e - это инструмент для оценки LLM и тестирования ИИ агентов для разработчиков.","ar":"المنصة e2e هي أداة لتقييم LLM واختبار وكلاء الذكاء الاصطناعي للمطورين.","en":"The platform for LLM evaluations and AI agent testing"},"definition":{"en":"The platform for LLM evaluations and AI agent testing"},"features":{"zh":["支持LLM评估和AI智能体测试","提供全面的AI模型性能分析","支持多种AI模型和框架","提供低代码开发环境","支持实时监控和可观察性"],"ja":["LLM評価とAIエージェントのテストをサポート","包括的なAIモデルのパフォーマンス分析を提供","複数のAIモデルとフレームワークをサポート","低コード開発環境を提供","リアルタイムの監視と可観測性をサポート"],"ko":["LLM 평가 및 AI 에이전트 테스트 지원","전반적인 AI 모델 성능 분석 제공","다중 AI 모델 및 프레임워크 지원","저코드 개발 환경 제공","リアルタイム 모니터링 및 관측 가능성 지원"],"es":["Evaluación de LLM","Pruebas de agentes de AI","Análisis de datos","Observabilidad","Integración con OpenAI","Soporte para low-code"],"fr":["Évaluation de LLM","Tests d''agents d''IA","Analyse de données","Observabilité","Intégration avec OpenAI","Support pour le low-code"],"de":["Evaluierung von LLM","Tests von KI-Agents","Datenanalyse","Observierbarkeit","Integration mit OpenAI","Unterstützung für Low-Code"],"pt":["Avaliação de LLM","Teste de agentes de IA","Análise de dados","Suporte a low-code","Integração com OpenAI","Observabilidade de desempenho"],"ru":["Оценка LLM","Тестирование ИИ агентов","Анализ данных","Поддержка low-code","Интеграция с OpenAI","Наблюдаемость производительности"],"ar":["تقييم LLM","اختبار وكلاء الذكاء الاصطناعي","تحليل البيانات","دعم low-code","التكامل مع OpenAI","مراقبة الأداء"]},"keywords":{"zh":["AI智能体","LLM评估","AI模型性能分析","低代码开发","实时监控","如何使用e2e","e2e与其他AI平台的比较","e2e安装指南","e2e设置教程"],"ja":["AIエージェント","LLM評価","AIモデルのパフォーマンス分析","低コード開発","リアルタイムの監視","e2eの使い方","e2eと他のAIプラットフォームの比較","e2eのインストールガイド","e2eの設定チュートリアル"],"ko":["AI 에이전트","LLM 평가","AI 모델 성능 분석","저코드 개발","リアルタイム 모니터링","e2e 사용 방법","e2e와 다른 AI 플랫폼 비교","e2e 설치 가이드","e2e 설정 튜토리얼"],"es":["herramientas de AI","evaluación de LLM","pruebas de agentes de AI","cómo usar e2e","e2e alternativa","e2e vs OpenAI","instalación de e2e","guía de configuración de e2e"],"fr":["outils d''IA","évaluation de LLM","tests d''agents d''IA","comment utiliser e2e","e2e alternative","e2e vs OpenAI","installation de e2e","guide de configuration de e2e"],"de":["KI-Tools","Evaluierung von LLM","Tests von KI-Agents","wie man e2e verwendet","e2e Alternative","e2e vs OpenAI","Installation von e2e","Konfigurationsanleitung für e2e"],"pt":["como usar e2e","o que é LLM","ferramentas de IA","e2e vs alternativas","instalar e2e","guia de configuração do e2e","desenvolvimento de agentes de IA","avaliação de LLM","tutoriais de e2e"],"ru":["как использовать e2e","что такое LLM","инструменты ИИ","e2e vs альтернативы","установить e2e","руководство по настройке e2e","разработка ИИ агентов","оценка LLM","уроки по e2e"],"ar":["كيفية استخدام e2e","ما هو LLM","أدوات الذكاء الاصطناعي","e2e مقابل البديلات","تثبيت e2e","دليل إعداد e2e","تطوير وكلاء الذكاء الاصطناعي","تقييم LLM","دروس في e2e"]}},"owner":"langwatch","repo":"langwatch","repoPath":"langwatch/langwatch","stars":2833,"forks":254,"updatedAt":"2026-02-24T16:59:56Z","topics":["ai","analytics","datasets","dspy","evaluation","gpt","llm","llm-ops","llmops","low-code","observability","openai","prompt-engineering"],"category":"community","skillMd":{"name":"e2e","description":"Generate and verify E2E tests for a feature. Explores live app, creates test plan, generates tests, runs and fixes until passing.","bodyPreview":"# E2E Test Generation Workflow\n\nYou coordinate E2E test creation and verification. You invoke specialized agents in sequence and verify the outcome.\n\n## Prerequisites\n\nBefore running this workflow:\n1. The app must be running locally (`make dev` or equivalent)\n2. E2E infrastructure must be up (`cd agentic-e2e-tests && docker compose up -d`)\n3. The feature should already be implemented and reviewed\n\n## Input\n\nYou receive either:\n- A feature file path (e.g., `specs/scenarios/scenario-editor.feature","body":"# E2E Test Generation Workflow\n\nYou coordinate E2E test creation and verification. You invoke specialized agents in sequence and verify the outcome.\n\n## Prerequisites\n\nBefore running this workflow:\n1. The app must be running locally (`make dev` or equivalent)\n2. E2E infrastructure must be up (`cd agentic-e2e-tests && docker compose up -d`)\n3. The feature should already be implemented and reviewed\n\n## Input\n\nYou receive either:\n- A feature file path (e.g., `specs/scenarios/scenario-editor.feature`)\n- A scenario description to verify\n\nExtract the `@e2e` tagged scenarios from the feature file if provided.\n\n## Workflow\n\n### 1. Explore and Plan\n\nInvoke the `playwright-test-planner` agent via Task tool:\n\n```\nTask(subagent_type: \"playwright-test-planner\", prompt: \"\"\"\nExplore the live app at http://localhost:5570 and create a test plan for:\n\n<scenarios>\n[List the @e2e scenarios from the feature file]\n</scenarios>\n\nFocus on:\n- Discovering the actual UI elements and navigation\n- Creating step-by-step test plans that match the scenarios\n- Documenting expected outcomes\n\nSave the plan to: agentic-e2e-tests/plans/[feature-name].plan.md\n\"\"\")\n```\n\n**Verify:** Plan file exists and covers all scenarios.\n\n### 2. Generate Tests\n\nInvoke the `playwright-test-generator` agent via Task tool:\n\n```\nTask(subagent_type: \"playwright-test-generator\", prompt: \"\"\"\nGenerate Playwright tests from the test plan:\n\n<plan-file>agentic-e2e-tests/plans/[feature-name].plan.md</plan-file>\n\nFor each scenario in the plan:\n1. Set up the page using generator_setup_page\n2. Execute each step in the browser\n3. Generate the test code from the execution log\n4. Save to: agentic-e2e-tests/tests/[feature-name]/[scenario-name].spec.ts\n\nFollow the project conventions in agentic-e2e-tests/README.md:\n- Use step functions from steps.ts (Given/When/Then naming)\n- Handle Chakra UI duplicates with .last()\n- No \"should\" in test names\n\"\"\")\n```\n\n**Verify:** Test files exist for each scenario.\n\n### 3. Run and Heal\n\nInvoke the `playwright-test-healer` agent via Task tool:\n\n```\nTask(subagent_type: \"playwright-test-healer\", prompt: \"\"\"\nRun and fix the generated E2E tests:\n\n1. Run all tests in agentic-e2e-tests/tests/[feature-name]/\n2. For any failures, diagnose the root cause:\n\n   **Test Issue** (healer fixes):\n   - Wrong selector (element changed)\n   - Timing issue (race condition)\n   - Incorrect assertion syntax\n   - Missing wait or setup step\n\n   **App Bug** (needs code fix):\n   - Feature doesn''t work as specified\n   - Expected element/behavior missing\n   - Error thrown during user flow\n   - Data not saved/displayed correctly\n\n3. For test issues: fix and re-run\n4. For app bugs: mark as test.fixme() with detailed explanation:\n   - What the spec expects\n   - What the app actually does\n   - Why this is an app bug, not a test issue\n\nContinue until all tests pass or are marked fixme with clear rationale.\n\"\"\")\n```\n\n**Verify:**\n- All tests pass → continue to review\n- Tests marked fixme → examine rationale to determine if app bug or inconclusive\n\n### 4. Review Tests (Optional)\n\nIf tests required significant healing, invoke `test-reviewer`:\n\n```\nTask(subagent_type: \"test-reviewer\", prompt: \"\"\"\nReview the E2E tests in agentic-e2e-tests/tests/[feature-name]/\n\nFocus on:\n- Naming conventions (no \"should\")\n- Proper pyramid placement (these should be E2E, not integration)\n- Step function quality\n- Locator robustness\n\"\"\")\n```\n\n## Output\n\nReturn a summary to the orchestrator with clear status:\n\n### If All Tests Pass\n```\n## E2E Verification Complete ✓\n\n**Feature:** [feature name]\n**Scenarios Tested:** [count]\n**Status:** ALL PASSING\n\n### Tests Generated\n- [test-file-1.spec.ts] - passing\n- [test-file-2.spec.ts] - passing\n\n### Coverage\n- [scenario 1] ✓ covered\n- [scenario 2] ✓ covered\n```\n\n### If Tests Fail Due to App Bugs\n```\n## E2E Verification Failed - App Bug Detected\n\n**Feature:** [feature name]\n**Status:** NEEDS CODE FIX\n\n### Failing Scenarios\n- **Scenario:** [scenario name]\n  **Expected:** [what the spec says should happen]\n  **Actual:** [what the app actually does]\n  **Evidence:** [screenshot path or error details]\n\n### Recommendation\nThe implementation does not match the spec. Send back to /code with:\n- Scenario: [scenario name]\n- Expected behavior: [from spec]\n- Actual behavior: [observed]\n- Fix needed: [specific change required]\n```\n\n### If Tests Marked as Fixme (Inconclusive)\n```\n## E2E Verification Partial\n\n**Feature:** [feature name]\n**Status:** NEEDS REVIEW\n\n### Tests with Issues\n- [test-file.spec.ts] - marked fixme\n  **Reason:** [why it couldn''t be determined if app or test is wrong]\n\n### Recommendation\nManual review needed to determine if this is an app bug or test issue.\n```\n\n## Boundaries\n\nYou coordinate, you don''t write tests directly:\n- `playwright-test-planner` explores and plans\n- `playwright-test-generator` generates tests\n- `playwright-test-healer` fixes failures\n- `test-reviewer` checks quality\n\nYou verify outcomes and report status.\n"},"lastSynced":"2026-02-26T08:27:17.695Z","agentAnalysis":{"suitability":{"en":"Perfect for QA Automation Agents needing comprehensive end-to-end testing workflows.","zh":"非常适合需要全方位端到端测试工作流的QA自动化代理。","ja":"QA自動化エージェントが包括的なエンドツーエンドのテストワークフローを必要とする場合に最適です。","ko":"포괄적인 엔드 투 엔드 테스트 워크플로우가 필요한 QA 자동화 에이전트에 적합합니다.","es":"Perfecto para agentes de automatización de QA que necesitan flujos de trabajo de testing de extremo a extremo integrales.","fr":"Parfait pour les agents d''automatisation QA nécessitant des flux de travail de testing de bout en bout complets.","de":"Perfekt für QA-Automatisierungsagenten, die umfassende End-to-End-Testworkflows benötigen.","pt":"Perfeito para Agentes de Automação de QA que precisam de fluxos de trabalho de teste abrangentes de ponta a ponta.","ru":"Идеально подходит для агентов автоматизации QA, которым требуются комплексные рабочие процессы тестирования от начала до конца.","ar":"مثالي لعميل آلي لتحسين جودة التطبيق الذي يحتاج إلى سير عمل اختبار متكامل من النهاية إلى النهاية."},"recommendation":{"en":"Coordinates complete E2E test creation and verification by invoking specialized agents in sequence. Provides automated outcome verification for AI agent testing against running applications with Docker-based infrastructure.","zh":"通过依次调用专用代理来协调完整的E2E测试创建和验证。为AI代理测试提供了针对使用Docker基础设施的运行应用程序的自动化结果验证。","ja":"シーケンスで専用エージェントを呼び出して、完全なE2Eテストの作成と検証を調整します。Dockerベースのインフラストラクチャを使用する実行中のアプリケーションに対するAIエージェントのテストに対して自動化された結果の検証を提供します。","ko":"순서대로 전문 에이전트를 호출하여 전체적인 E2E 테스트 생성 및 검증을 조정합니다. Docker 기반 인프라를 사용하는 실행 중인 애플리케이션에 대한 AI 에이전트 테스트를 위한 자동화된 결과 검증을 제공합니다.","es":"Coordina la creación y verificación completa de pruebas E2E invocando agentes especializados en secuencia. Proporciona verificación automatizada de resultados para pruebas de agentes de inteligencia artificial contra aplicaciones en ejecución con infraestructura basada en Docker.","fr":"Coordonne la création et la vérification complètes des tests E2E en invoquant des agents spécialisés dans une séquence. Fournit une vérification automatique des résultats pour les tests d''agents d''intelligence artificielle contre les applications en cours d''exécution avec une infrastructure basée sur Docker.","de":"Koordiniert die komplette Erstellung und Überprüfung von E2E-Tests durch Aufrufen spezialisierter Agenten in einer Sequenz. Bietet automatisierte Ergebnisüberprüfung für AI-Agent-Tests gegen laufende Anwendungen mit Docker-basierter Infrastruktur.","pt":"Coordena a criação e verificação completa de testes E2E, invocando agentes especializados em sequência. Fornece verificação automática de resultados para testes de agentes de IA contra aplicativos em execução com infraestrutura baseada em Docker.","ru":"Координирует создание и проверку полных тестов E2E, вызывая специализированные агенты в последовательности. Предоставляет автоматическую проверку результатов для тестирования агентов ИИ против работающих приложений с инфраструктурой на основе Docker.","ar":"ينسق إنشاء اختبار E2E الكامل وتحققها عن طريق استدعاء وكلاء متخصصين بالتسلسل. يوفر التحقق التلقائي للنتائج لاختبار عميل آلي للذكاء الاصطناعي مقابل التطبيقات التي تعمل على بنية تحتية تعمل بالدッカー."},"useCases":{"en":["Generating comprehensive test scenarios from feature files","Verifying AI agent behavior against implemented features","Coordinating specialized testing agents in sequence","Running E2E infrastructure with Docker compose"],"zh":["从功能文件生成全面的测试场景","验证AI代理行为与实现的功能","协调顺序中的专用测试代理","使用Docker compose运行E2E基础设施"],"ja":["機能ファイルから包括的なテストシナリオを生成する","実装された機能に対するAIエージェントの動作を検証する","シーケンス内の専用テストエージェントを調整する","Docker Composeを使用してE2Eインフラストラクチャを実行する"],"ko":["기능 파일에서 포괄적인 테스트 시나리오 생성","구현된 기능에 대한 AI 에이전트 동작 검증","순서에 따른 전문 테스트 에이전트 조정","Docker Compose를 사용하여 E2E 인프라스트럭처 실행"],"es":["Generación de escenarios de prueba integrales a partir de archivos de características","Verificación del comportamiento de los agentes de inteligencia artificial frente a características implementadas","Coordinación de agentes de prueba especializados en secuencia","Ejecución de infraestructura E2E con Docker compose"],"fr":["Génération de scénarios de test complets à partir de fichiers de fonctionnalités","Vérification du comportement des agents d''intelligence artificielle par rapport aux fonctionnalités mises en œuvre","Coordination d''agents de test spécialisés dans une séquence","Exécution d''une infrastructure E2E avec Docker compose"],"de":["Erzeugung umfassender Testsszenarien aus Feature-Dateien","Überprüfung des Verhaltens von AI-Agents gegenüber implementierten Features","Koordination spezialisierter Testagenten in einer Sequenz","Ausführung von E2E-Infrastruktur mit Docker compose"],"pt":["Gerar cenários de teste abrangentes a partir de arquivos de recursos","Verificar o comportamento do agente de IA em relação às funcionalidades implementadas","Coordenar agentes de teste especializados em sequência","Executar infraestrutura E2E com Docker compose"],"ru":["Генерирование полных сценариев тестирования из файлов функций","Проверка поведения агента ИИ по отношению к реализованным функциям","Координация специализированных агентов тестирования в последовательности","Запуск инфраструктуры E2E с помощью Docker compose"],"ar":["إنشاء سيناريوهات اختبار شاملة من ملفات الميزات","التحقق من سلوك عميل الذكاء الاصطناعي تجاه الميزات المنفذة","تنسيق وكلاء اختبار متخصصين بالتسلسل","تشغيل البنية التحتية للنهاية إلى النهاية مع تجميع الدッカー"]},"limitations":{"en":["Requires app running locally (make dev)","Needs E2E infrastructure via Docker compose","Depends on pre-implemented and reviewed features"],"zh":["需要应用程序在本地运行（make dev）","需要通过Docker compose的E2E基础设施","依赖于预先实现和审查的功能"],"ja":["ローカルでアプリケーションを実行する必要がある（make dev）","Docker Composeを介したE2Eインフラストラクチャが必要","事前に実装およびレビューされた機能に依存する"],"ko":["로컬에서 애플리케이션을 실행해야 함（make dev）","Docker Compose를 통한 E2E 인프라스트럭처 필요","사전에 구현 및 검토된 기능에 의존"],"es":["Requiere que la aplicación se ejecute localmente (make dev)","Necesita infraestructura E2E a través de Docker compose","Depende de características preimplementadas y revisadas"],"fr":["Nécessite que l''application s''exécute localement (make dev)","A besoin d''une infrastructure E2E via Docker compose","Dépend de fonctionnalités préimplémentées et examinées"],"de":["Erfordert, dass die App lokal ausgeführt wird (make dev)","Benötigt E2E-Infrastruktur über Docker compose","Hängt von vorab implementierten und überprüften Features ab"],"pt":["Exige que o aplicativo esteja em execução localmente (faça dev)","Necessita de infraestrutura E2E via Docker compose","Depende de funcionalidades pré-implementadas e revisadas"],"ru":["Требует запуска приложения локально (make dev)","Требует инфраструктуры E2E через Docker compose","Зависит от предварительно реализованных и рассмотренных функций"],"ar":["يتطلب تشغيل التطبيق على المستوى المحلي (قم بالتطوير)","يحتاج إلى بنية تحتية للنهاية إلى النهاية عبر تجميع الدッカー","يعتمد على الميزات المنفذة والمراجعة مسبقًا"]},"version":3},"contentHash":"63e2b31f0fbd4aaed2474d2be69213131ebe35498abcea6fbf953d76de82a05f","qualityScore":59}');
