INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jiahao-jayden/vibe-any-tanstack/ai-elements', 'ai-elements', 'jiahao-jayden', 'vibe-any-tanstack', 'community', 'ai-elements jiahao-jayden vibe-any-tanstack community ai-elements是一个全栈启动器，用于构建AI驱动的Web应用，提供身份验证、数据库、登录页面、博客、文档、国际化和管理面板 AIエージェントは、AI駆動のWebアプリを構築するためのフルスタックスターターです。認証、データベース、ランディングページ、ブログ、ドキュメント、国際化、管理パネルなど ai-elements는 AI 구동 웹 애플리케이션을 구축하기 위한 풀 스택 시작점으로, 인증, 데이터베이스, 랜딩 페이지, 블로그, 문서, 국제화, 관리 패널 등 ai-elements es un kit de inicio full-stack para construir aplicaciones web con inteligencia artificial. Incluye autenticación, base de datos y más ai-elements est un kit de démarrage full-stack pour créer des applications web avec intelligence artificielle. Inclut authentification, base de données et plus ai-elements ist ein Full-Stack-Starterkit für den Bau von Webanwendungen mit künstlicher Intelligenz. Enthält Authentifizierung, Datenbank und mehr ai-elements é um kit de inicialização full-stack para construir aplicações web com IA. Inclui autenticação, banco de dados e outros recursos ai-elements — это полнофункциональный стартовый комплект для создания веб-приложений с ИИ. Включает аутентификацию, базу данных и другие функции ai-elements هو حزمة بدء تشغيل كاملة للإنشاء التطبيقات الويب بالذكاء الاصطناعي. يتضمن المصادقة وقاعدة البيانات والميزات الأخرى Full-stack starter for building AI-powered web apps with TanStack Start.Ships with authentication, database, landing page, blog, docs, i18n, admin panel, and more — ready to deploy in minutes. AI智能元素 构建AI驱动的Web应用 ai-elements安装 ai-elements教程 AI驱动的Web应用开发 AI智能工具 AI驱动的Web应用框架 Full-stack starter for building AI-powered web apps with TanStack Start.Ships with authentication, database, landing page, blog, docs, i18n, admin panel, and more — ready to deploy in minutes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mj-meyer/choo-choo-ralph/release-skills', 'community', 'mj-meyer', 'choo-choo-ralph', 'mj-meyer/choo-choo-ralph', 'release-skills', 27, 2, 59, '2026-02-23T14:29:56Z', '2026-02-27T13:10:04.159Z', '220b163cfe79562e417d5fe8a2586d254aabac186a86bb667a087743196d94be', '{"id":"mj-meyer/choo-choo-ralph/release-skills","name":"release-skills","description":{"zh":"release-skills 是一个 Claude Code 插件，添加结构化的工作流公式，基于 Beads 构建","ja":"release-skills は Claude Code のプラグインであり、構造化されたワークフローフォーミュラを追加し、Beads に基づいて構築されています","ko":"release-skills는 Claude Code 플러그인으로 구조화된 워크플로우 공식을 추가하며 Beads를 기반으로 합니다","es":"Release-skills es un plugin de Claude Code que agrega fórmulas de flujo de trabajo estructuradas y personalizables al ciclo de Ralph, construido sobre Beads","fr":"Release-skills est un plugin Claude Code qui ajoute des formules de workflow structurées et personnalisables à la boucle Ralph, construit sur Beads","de":"Release-skills ist ein Claude-Code-Plugin, das strukturierte, anpassbare Workflow-Formeln zum Ralph-Zyklus hinzufügt, aufgebaut auf Beads","pt":"O release-skills é um plugin Claude Code que adiciona fórmulas de workflow estruturadas e personalizáveis ao loop Ralph, construído em Beads","ru":"Release-skills - это плагин Claude Code, который добавляет структурированные и настраиваемые формулы рабочего процесса в цикл Ralph, построенный на Beads","ar":"release-skills هو إضافة Claude Code التي تضيف صيغ عمل متطورة وقابلة للتعديل إلى حلقة Ralph، مبني على Beads","en":"A Claude Code plugin that adds structured, customizable workflow formulas to the Ralph loop. Built on Beads."},"seo":{"title":{"zh":"AI智能代理 release-skills 插件","ja":"AIエージェント release-skills プラグイン","ko":"AI 에이전트 release-skills 플러그인","es":"Herramientas de AI: release-skills para Claude Code","fr":"Outils d''IA: release-skills pour Claude Code","de":"KI-Tools: release-skills für Claude Code","pt":"Ferramentas de IA: release-skills para Desenvolvedores","ru":"ИИ Агенты: release-skills для Разработчиков","ar":"أدوات الذكاء الاصطناعي: release-skills للمطورين","en":"release-skills"},"description":{"zh":"release-skills 是一个 Claude Code 插件，添加结构化的工作流公式，基于 Beads 构建","ja":"release-skills は Claude Code のプラグインであり、構造化されたワークフローフォーミュラを追加し、Beads に基づいて構築されています","ko":"release-skills는 Claude Code 플러그인으로 구조화된 워크플로우 공식을 추가하며 Beads를 기반으로 합니다","es":"Release-skills es un plugin de Claude Code que agrega fórmulas de flujo de trabajo estructuradas y personalizables al ciclo de Ralph, construido sobre Beads","fr":"Release-skills est un plugin Claude Code qui ajoute des formules de workflow structurées et personnalisables à la boucle Ralph, construit sur Beads","de":"Release-skills ist ein Claude-Code-Plugin, das strukturierte, anpassbare Workflow-Formeln zum Ralph-Zyklus hinzufügt, aufgebaut auf Beads","pt":"O release-skills é um plugin Claude Code que adiciona fórmulas de workflow estruturadas e personalizáveis ao loop Ralph, construído em Beads","ru":"Release-skills - это плагин Claude Code, который добавляет структурированные и настраиваемые формулы рабочего процесса в цикл Ralph, построенный на Beads","ar":"release-skills هو إضافة Claude Code التي تضيف صيغ عمل متطورة وقابلة للتعديل إلى حلقة Ralph، مبني على Beads","en":"A Claude Code plugin that adds structured, customizable workflow formulas to the Ralph loop. Built on Beads."},"definition":{"en":"A Claude Code plugin that adds structured, customizable workflow formulas to the Ralph loop. Built on Beads."},"features":{"zh":["结构化的工作流公式","自定义工作流","基于 Beads 构建","提高开发效率","简单易用"],"ja":["構造化されたワークフローフォーミュラ","カスタマイズ可能なワークフロー","Beads に基づいて構築","開発効率の向上","シンプルで使いやすい"],"ko":["구조화된 워크플로우 공식","사용자 정의 워크플로우","Beads를 기반으로构築","개발 효율성 향상","간단하고 사용하기 쉬움"],"es":["Fórmulas de flujo de trabajo estructuradas y personalizables","Integración con el ciclo de Ralph","Construido sobre Beads","Permite la creación de workflows personalizados","Mejora la eficiencia y la productividad"],"fr":["Formules de workflow structurées et personnalisables","Intégration avec la boucle Ralph","Construit sur Beads","Permet la création de workflows personnalisés","Améliore l''efficacité et la productivité"],"de":["Strukturierte und anpassbare Workflow-Formeln","Integration mit dem Ralph-Zyklus","Aufgebaut auf Beads","Ermöglicht die Erstellung von anpassbaren Workflows","Verbessert die Effizienz und Produktivität"],"pt":["Fórmulas de workflow estruturadas e personalizáveis","Integração com o loop Ralph","Construído em Beads","Customização avançada","Melhoria da produtividade"],"ru":["Структурированные и настраиваемые формулы рабочего процесса","Интеграция с циклом Ralph","Построен на Beads","Расширенная настройка","Повышение производительности"],"ar":["صيغ عمل متطورة وقابلة للتعديل","التكامل مع حلقة Ralph","مبني على Beads","التعديل المتقدم","تحسين الإنتاجية"]},"keywords":{"zh":["AI智能代理","release-skills 插件","如何使用 release-skills","什么是 release-skills","release-skills 安装","release-skills 设置指南","release-skills 与 Claude Code","release-skills 代替方案"],"ja":["AIエージェント","release-skills プラグイン","release-skills の使い方","release-skills とは","release-skills のインストール","release-skills の設定ガイド","release-skills と Claude Code","release-skills の代替"],"ko":["AI 에이전트","release-skills 플러그인","release-skills 사용법","release-skills是什么","release-skills 설치","release-skills 설정 가이드","release-skills 와 Claude Code","release-skills 대안"],"es":["cómo usar release-skills","qué es release-skills","alternativas a release-skills","release-skills vs Claude Code","instalación de release-skills","guía de configuración de release-skills","herramientas de AI para desarrollo","plugins de Claude Code"],"fr":["comment utiliser release-skills","quoi est release-skills","alternatives à release-skills","release-skills vs Claude Code","installation de release-skills","guide de configuration de release-skills","outils d''IA pour le développement","plugins de Claude Code"],"de":["wie man release-skills verwendet","was ist release-skills","alternativen zu release-skills","release-skills vs Claude Code","installation von release-skills","konfigurationsanleitung für release-skills","KI-Tools für die Entwicklung","Claude-Code-Plugins"],"pt":["como usar release-skills","o que é release-skills","release-skills alternativa","release-skills vs Claude Code","instalar release-skills","guia de configuração do release-skills","desenvolvimento de software com release-skills","ferramentas de IA para desenvolvedores"],"ru":["как использовать release-skills","что такое release-skills","release-skills альтернатива","release-skills vs Claude Code","установить release-skills","руководство по настройке release-skills","разработка программного обеспечения с release-skills","ИИ инструменты для разработчиков"],"ar":["كيفية استخدام release-skills","ما هي release-skills","release-skills بديل","release-skills مقابل Claude Code","تثبيت release-skills","دليل إعداد release-skills","تطوير البرمجيات مع release-skills","أدوات الذكاء الاصطناعي للمطورين"]}},"owner":"mj-meyer","repo":"choo-choo-ralph","repoPath":"mj-meyer/choo-choo-ralph","stars":27,"forks":2,"updatedAt":"2026-02-23T14:29:56Z","topics":[],"category":"community","skillMd":{"name":"release-skills","description":"Universal release workflow. Auto-detects version files and changelogs. Supports Node.js, Python, Rust, Claude Plugin, and generic projects. Use when user says release, 发布, new version, bump version, push, 推送.","bodyPreview":"# Release Skills\n\nUniversal release workflow supporting any project type with multi-language changelog.\n\n## Quick Start\n\nJust run `/release-skills` - auto-detects your project configuration.\n\n## Supported Projects\n\n| Project Type | Version File | Auto-Detected |\n|--------------|--------------|---------------|\n| Node.js | package.json | ✓ |\n| Python | pyproject.toml | ✓ |\n| Rust | Cargo.toml | ✓ |\n| Claude Plugin | marketplace.json + plugin.json | ✓ |\n| Generic | VERSION / version.txt | ✓ |\n\n## O","body":"# Release Skills\n\nUniversal release workflow supporting any project type with multi-language changelog.\n\n## Quick Start\n\nJust run `/release-skills` - auto-detects your project configuration.\n\n## Supported Projects\n\n| Project Type | Version File | Auto-Detected |\n|--------------|--------------|---------------|\n| Node.js | package.json | ✓ |\n| Python | pyproject.toml | ✓ |\n| Rust | Cargo.toml | ✓ |\n| Claude Plugin | marketplace.json + plugin.json | ✓ |\n| Generic | VERSION / version.txt | ✓ |\n\n## Options\n\n| Flag | Description |\n|------|-------------|\n| `--dry-run` | Preview changes without executing |\n| `--major` | Force major version bump |\n| `--minor` | Force minor version bump |\n| `--patch` | Force patch version bump |\n\n## Workflow\n\n### Step 1: Detect Project Configuration\n\n1. Check for `.releaserc.yml` (optional config override)\n2. Auto-detect version file by scanning (priority order):\n   - `package.json` (Node.js)\n   - `pyproject.toml` (Python)\n   - `Cargo.toml` (Rust)\n   - `marketplace.json` or `.claude-plugin/marketplace.json` (Claude Plugin) - also update `plugin.json` or `.claude-plugin/plugin.json` if present\n   - `VERSION` or `version.txt` (Generic)\n3. Scan for changelog files using glob patterns:\n   - `CHANGELOG*.md`\n   - `HISTORY*.md`\n   - `CHANGES*.md`\n4. Identify language of each changelog by filename suffix\n5. Display detected configuration\n\n**Language Detection Rules**:\n\n| Filename Pattern | Language |\n|------------------|----------|\n| `CHANGELOG.md` (no suffix) | en (default) |\n| `CHANGELOG.zh.md` / `CHANGELOG_CN.md` / `CHANGELOG.zh-CN.md` | zh |\n| `CHANGELOG.ja.md` / `CHANGELOG_JP.md` | ja |\n| `CHANGELOG.ko.md` / `CHANGELOG_KR.md` | ko |\n| `CHANGELOG.de.md` / `CHANGELOG_DE.md` | de |\n| `CHANGELOG.fr.md` / `CHANGELOG_FR.md` | fr |\n| `CHANGELOG.es.md` / `CHANGELOG_ES.md` | es |\n| `CHANGELOG.{lang}.md` | Corresponding language code |\n\n**Output Example**:\n```\nProject detected:\n  Version file: package.json (1.2.3)\n  Changelogs:\n    - CHANGELOG.md (en)\n    - CHANGELOG.zh.md (zh)\n    - CHANGELOG.ja.md (ja)\n```\n\n### Step 2: Analyze Changes Since Last Tag\n\n```bash\nLAST_TAG=$(git tag --sort=-v:refname | head -1)\ngit log ${LAST_TAG}..HEAD --oneline\ngit diff ${LAST_TAG}..HEAD --stat\n```\n\nCategorize by conventional commit types:\n\n| Type | Description |\n|------|-------------|\n| feat | New features |\n| fix | Bug fixes |\n| docs | Documentation |\n| refactor | Code refactoring |\n| perf | Performance improvements |\n| test | Test changes |\n| style | Formatting, styling |\n| chore | Maintenance (skip in changelog) |\n\n**Breaking Change Detection**:\n- Commit message starts with `BREAKING CHANGE`\n- Commit body/footer contains `BREAKING CHANGE:`\n- Removed public APIs, renamed exports, changed interfaces\n\nIf breaking changes detected, warn user: \"Breaking changes detected. Consider major version bump (--major flag).\"\n\n### Step 3: Determine Version Bump\n\nRules (in priority order):\n1. User flag `--major/--minor/--patch` → Use specified\n2. BREAKING CHANGE detected → Major bump (1.x.x → 2.0.0)\n3. `feat:` commits present → Minor bump (1.2.x → 1.3.0)\n4. Otherwise → Patch bump (1.2.3 → 1.2.4)\n\nDisplay version change: `1.2.3 → 1.3.0`\n\n### Step 4: Generate Multi-language Changelogs\n\nFor each detected changelog file:\n\n1. **Identify language** from filename suffix\n2. **Detect third-party contributors**:\n   - Check merge commits: `git log ${LAST_TAG}..HEAD --merges --pretty=format:\"%H %s\"`\n   - For each merged PR, identify the PR author via `gh pr view <number> --json author --jq ''.author.login''`\n   - Compare against repo owner (`gh repo view --json owner --jq ''.owner.login''`)\n   - If PR author ≠ repo owner → third-party contributor\n3. **Generate content in that language**:\n   - Section titles in target language\n   - Change descriptions written naturally in target language (not translated)\n   - Date format: YYYY-MM-DD (universal)\n   - **Third-party contributions**: Append contributor attribution `(by @username)` to the changelog entry\n4. **Insert at file head** (preserve existing content)\n\n**Section Title Translations** (built-in):\n\n| Type | en | zh | ja | ko | de | fr | es |\n|------|----|----|----|----|----|----|-----|\n| feat | Features | 新功能 | 新機能 | 새로운 기능 | Funktionen | Fonctionnalités | Características |\n| fix | Fixes | 修复 | 修正 | 수정 | Fehlerbehebungen | Corrections | Correcciones |\n| docs | Documentation | 文档 | ドキュメント | 문서 | Dokumentation | Documentation | Documentación |\n| refactor | Refactor | 重构 | リファクタリング | 리팩토링 | Refactoring | Refactorisation | Refactorización |\n| perf | Performance | 性能优化 | パフォーマンス | 성능 | Leistung | Performance | Rendimiento |\n| breaking | Breaking Changes | 破坏性变更 | 破壊的変更 | 주요 변경사항 | Breaking Changes | Changements majeurs | Cambios importantes |\n\n**Changelog Format**:\n\n```markdown\n## {VERSION} - {YYYY-MM-DD}\n\n### Features\n- Description of new feature\n- Description of third-party contribution (by @username)\n\n### Fixes\n- Description of fix\n\n### Documentation\n- Description of docs changes\n```\n\nOnly include sections that have changes. Omit empty sections.\n\n**Third-Party Attribution Rules**:\n- Only add `(by @username)` for contributors who are NOT the repo owner\n- Use GitHub username with `@` prefix\n- Place at the end of the changelog entry line\n- Apply to all languages consistently (always use `(by @username)` format, not translated)\n\n**Multi-language Example**:\n\nEnglish (CHANGELOG.md):\n```markdown\n## 1.3.0 - 2026-01-22\n\n### Features\n- Add user authentication module (by @contributor1)\n- Support OAuth2 login\n\n### Fixes\n- Fix memory leak in connection pool\n```\n\nChinese (CHANGELOG.zh.md):\n```markdown\n## 1.3.0 - 2026-01-22\n\n### 新功能\n- 新增用户认证模块 (by @contributor1)\n- 支持 OAuth2 登录\n\n### 修复\n- 修复连接池内存泄漏问题\n```\n\nJapanese (CHANGELOG.ja.md):\n```markdown\n## 1.3.0 - 2026-01-22\n\n### 新機能\n- ユーザー認証モジュールを追加 (by @contributor1)\n- OAuth2 ログインをサポート\n\n### 修正\n- コネクションプールのメモリリークを修正\n```\n\n### Step 5: Group Changes by Skill/Module\n\nAnalyze commits since last tag and group by affected skill/module:\n\n1. **Identify changed files** per commit\n2. **Group by skill/module**:\n   - `skills/<skill-name>/*` → Group under that skill\n   - Root files (CLAUDE.md, etc.) → Group as \"project\"\n   - Multiple skills in one commit → Split into multiple groups\n3. **For each group**, identify related README updates needed\n\n**Example Grouping**:\n```\nbaoyu-cover-image:\n  - feat: add new style options\n  - fix: handle transparent backgrounds\n  → README updates: options table\n\nbaoyu-comic:\n  - refactor: improve panel layout algorithm\n  → No README updates needed\n\nproject:\n  - docs: update CLAUDE.md architecture section\n```\n\n### Step 6: Commit Each Skill/Module Separately\n\nFor each skill/module group (in order of changes):\n\n1. **Check README updates needed**:\n   - Scan `README*.md` for mentions of this skill/module\n   - Verify options/flags documented correctly\n   - Update usage examples if syntax changed\n   - Update feature descriptions if behavior changed\n\n2. **Stage and commit**:\n   ```bash\n   git add skills/<skill-name>/*\n   git add README.md README.zh.md  # If updated for this skill\n   git commit -m \"<type>(<skill-name>): <meaningful description>\"\n   ```\n\n3. **Commit message format**:\n   - Use conventional commit format: `<type>(<scope>): <description>`\n   - `<type>`: feat, fix, refactor, docs, perf, etc.\n   - `<scope>`: skill name or \"project\"\n   - `<description>`: Clear, meaningful description of changes\n\n**Example Commits**:\n```bash\ngit commit -m \"feat(baoyu-cover-image): add watercolor and minimalist styles\"\ngit commit -m \"fix(baoyu-comic): improve panel layout for long dialogues\"\ngit commit -m \"docs(project): update architecture documentation\"\n```\n\n**Common README Updates Needed**:\n| Change Type | README Section to Check |\n|-------------|------------------------|\n| New options/flags | Options table, usage examples |\n| Renamed options | Options table, usage examples |\n| New features | Feature description, examples |\n| Breaking changes | Migration notes, deprecation warnings |\n| Restructured internals | Architecture section (if exposed to users) |\n\n### Step 7: Generate Changelog and Update Version\n\n1. **Generate multi-language changelogs** (as described in Step 4)\n2. **Update version file**:\n   - Read version file (JSON/TOML/text)\n   - Update version number\n   - Write back (preserve formatting)\n\n**Version Paths by File Type**:\n\n| File | Path |\n|------|------|\n| package.json | `$.version` |\n| pyproject.toml | `project.version` |\n| Cargo.toml | `package.version` |\n| marketplace.json | `$.metadata.version` and `$.plugins[0].version` |\n| plugin.json | `$.version` |\n| VERSION / version.txt | Direct content |\n\n### Step 8: User Confirmation\n\nBefore creating the release commit, ask user to confirm:\n\n**Use AskUserQuestion with two questions**:\n\n1. **Version bump** (single select):\n   - Show recommended version based on Step 3 analysis\n   - Options: recommended (with label), other semver options\n   - Example: `1.2.3 → 1.3.0 (Recommended)`, `1.2.3 → 1.2.4`, `1.2.3 → 2.0.0`\n\n2. **Push to remote** (single select):\n   - Options: \"Yes, push after commit\", \"No, keep local only\"\n\n**Example Output Before Confirmation**:\n```\nCommits created:\n  1. feat(baoyu-cover-image): add watercolor and minimalist styles\n  2. fix(baoyu-comic): improve panel layout for long dialogues\n  3. docs(project): update architecture documentation\n\nChangelog preview (en):\n  ## 1.3.0 - 2026-01-22\n  ### Features\n  - Add watercolor and minimalist styles to cover-image\n  ### Fixes\n  - Improve panel layout for long dialogues in comic\n\nReady to create release commit and tag.\n```\n\n### Step 9: Create Release Commit and Tag\n\nAfter user confirmation:\n\n1. **Stage version and changelog files**:\n   ```bash\n   git add <version-file>\n   git add CHANGELOG*.md\n   ```\n\n2. **Create release commit**:\n   ```bash\n   git commit -m \"chore: release v{VERSION}\"\n   ```\n\n3. **Create tag**:\n   ```bash\n   git tag v{VERSION}\n   ```\n\n4. **Push if user confirmed** (Step 8):\n   ```bash\n   git push origin main\n   git push origin v{VERSION}\n   ```\n\n**Note**: Do NOT add Co-Authored-By line. This is a release commit, not a code contribution.\n\n**Post-Release Output**:\n```\nRelease v1.3.0 created.\n\nCommits:\n  1. feat(baoyu-cover-image): add watercolor and minimalist styles\n  2. fix(baoyu-comic): improve panel layout for long dialogues\n  3. docs(project): update architecture documentation\n  4. chore: release v1.3.0\n\nTag: v1.3.0\nStatus: Pushed to origin  # or \"Local only - run git push when ready\"\n```\n\n## Configuration (.releaserc.yml)\n\nOptional config file in project root to override defaults:\n\n```yaml\n# .releaserc.yml - Optional configuration\n\n# Version file (auto-detected if not specified)\nversion:\n  file: package.json\n  path: $.version  # JSONPath for JSON, dotted path for TOML\n\n# Changelog files (auto-detected if not specified)\nchangelog:\n  files:\n    - path: CHANGELOG.md\n      lang: en\n    - path: CHANGELOG.zh.md\n      lang: zh\n    - path: CHANGELOG.ja.md\n      lang: ja\n\n  # Section mapping (conventional commit type → changelog section)\n  # Use null to skip a type in changelog\n  sections:\n    feat: Features\n    fix: Fixes\n    docs: Documentation\n    refactor: Refactor\n    perf: Performance\n    test: Tests\n    chore: null\n\n# Commit message format\ncommit:\n  message: \"chore: release v{version}\"\n\n# Tag format\ntag:\n  prefix: v  # Results in v1.0.0\n  sign: false\n\n# Additional files to include in release commit\ninclude:\n  - README.md\n  - package.json\n```\n\n## Dry-Run Mode\n\nWhen `--dry-run` is specified:\n\n```\n=== DRY RUN MODE ===\n\nProject detected:\n  Version file: package.json (1.2.3)\n  Changelogs: CHANGELOG.md (en), CHANGELOG.zh.md (zh)\n\nLast tag: v1.2.3\nProposed version: v1.3.0\n\nChanges grouped by skill/module:\n  baoyu-cover-image:\n    - feat: add watercolor style\n    - feat: add minimalist style\n    → Commit: feat(baoyu-cover-image): add watercolor and minimalist styles\n    → README updates: options table\n\n  baoyu-comic:\n    - fix: panel layout for long dialogues\n    → Commit: fix(baoyu-comic): improve panel layout for long dialogues\n    → No README updates\n\nChangelog preview (en):\n  ## 1.3.0 - 2026-01-22\n  ### Features\n  - Add watercolor and minimalist styles to cover-image\n  ### Fixes\n  - Improve panel layout for long dialogues in comic\n\nChangelog preview (zh):\n  ## 1.3.0 - 2026-01-22\n  ### 新功能\n  - 为 cover-image 添加水彩和极简风格\n  ### 修复\n  - 改进 comic 长对话的面板布局\n\nCommits to create:\n  1. feat(baoyu-cover-image): add watercolor and minimalist styles\n  2. fix(baoyu-comic): improve panel layout for long dialogues\n  3. chore: release v1.3.0\n\nNo changes made. Run without --dry-run to execute.\n```\n\n## Example Usage\n\n```\n/release-skills              # Auto-detect version bump\n/release-skills --dry-run    # Preview only\n/release-skills --minor      # Force minor bump\n/release-skills --patch      # Force patch bump\n/release-skills --major      # Force major bump (with confirmation)\n```\n\n## When to Use\n\nTrigger this skill when user requests:\n- \"release\", \"发布\", \"create release\", \"new version\", \"新版本\"\n- \"bump version\", \"update version\", \"更新版本\"\n- \"prepare release\"\n- \"push to remote\" (with uncommitted changes)\n\n**Important**: If user says \"just push\" or \"直接 push\" with uncommitted changes, STILL follow all steps above first.\n"},"lastSynced":"2026-02-27T13:10:04.159Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated release workflows with multi-language changelog support.","zh":"非常适合需要自动化发布工作流和多语言变更日志支持的开发代理。","ja":"自動化されたリリースワークフローと多言語の変更ログサポートを必要とする開発エージェントに最適です。","ko":"자동화된 릴리즈 워크플로 및 다국어 변경 로그 지원이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan flujos de trabajo de lanzamiento automatizados con soporte de registro de cambios multilingüe.","fr":"Parfait pour les agents de développement ayant besoin de flux de travail de lancement automatisés avec une prise en charge du journal des modifications multilingue.","de":"Perfekt für Entwicklungsmittel, die automatisierte Release-Workflows mit Unterstützung für mehrsprachige Changelogs benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de fluxos de trabalho de lançamento automatizados com suporte a changelog multilíngue.","ru":"Идеально подходит для агентов разработки, которым необходимы автоматизированные рабочие процессы выпуска с поддержкой многоязычного журнала изменений.","ar":"مثالي لعمليات وكيل التطوير التي تحتاج إلى سير عمل إصدار آلي مع دعم سجل التغييرات متعددة اللغات."},"recommendation":{"en":"Empowers agents to automate release processes for various project types, including Node.js, Python, and Rust, using customizable workflow formulas and auto-detection of project configurations via package.json, pyproject.toml, and Cargo.toml files.","zh":"赋予代理自动化各种项目类型（包括 Node.js、Python 和 Rust）的发布流程的能力，使用可自定义的工作流公式和通过 package.json、pyproject.toml 和 Cargo.toml 文件自动检测项目配置。","ja":"エージェントに、Node.js、Python、Rust などのさまざまなプロジェクトタイプのリリースプロセスを自動化する能力を与え、カスタマイズ可能なワークフローフォーミュラと、package.json、pyproject.toml、Cargo.toml ファイルを介したプロジェクト構成の自動検出を使用します。","ko":"에이전트에게 Node.js, Python, Rust 등의 다양한 프로젝트 유형의 릴리즈 프로세스를 자동화할 수 있는 능력을 부여하며, 사용자 지정 가능한 워크플로 수식과 package.json, pyproject.toml, Cargo.toml 파일을 통해 프로젝트 구성의 자동 감지를 사용합니다.","es":"Habilita a los agentes a automatizar los procesos de lanzamiento para varios tipos de proyectos, incluidos Node.js, Python y Rust, utilizando fórmulas de flujo de trabajo personalizables y la detección automática de configuraciones de proyecto a través de archivos package.json, pyproject.toml y Cargo.toml.","fr":"Permet aux agents d''automatiser les processus de lancement pour différents types de projets, notamment Node.js, Python et Rust, en utilisant des formules de flux de travail personnalisables et la détection automatique des configurations de projet via les fichiers package.json, pyproject.toml et Cargo.toml.","de":"Ermöglicht es Agenten, Release-Prozesse für verschiedene Projekttypen, einschließlich Node.js, Python und Rust, zu automatisieren, indem sie anpassbare Workflow-Formeln und die automatische Erkennung von Projekt-Konfigurationen über package.json-, pyproject.toml- und Cargo.toml-Dateien verwenden.","pt":"Habilita os agentes a automatizar processos de lançamento para vários tipos de projetos, incluindo Node.js, Python e Rust, usando fórmulas de fluxo de trabalho personalizáveis e detecção automática de configurações de projeto via arquivos package.json, pyproject.toml e Cargo.toml.","ru":"Наделяет агентов возможностью автоматизировать процессы выпуска для различных типов проектов, включая Node.js, Python и Rust, используя настраиваемые формулы рабочих процессов и автоматическое обнаружение конфигураций проекта через файлы package.json, pyproject.toml и Cargo.toml.","ar":"تمكّن الوكلاء من توفير عمليات إصدار آليّة لمختلف أنواع المشاريع، بما في ذلك Node.js و Python و Rust، باستخدام صيغ سير العمل المخصصة والكشف الآلي عن تكوينات المشروع عبر الملفات package.json و pyproject.toml و Cargo.toml."},"useCases":{"en":["Automating release workflows for Node.js projects","Generating changelogs for Python packages","Streamlining release processes for Rust-based projects"],"zh":["自动化 Node.js 项目的发布工作流","为 Python 包生成变更日志","简化基于 Rust 的项目的发布流程"],"ja":["Node.js プロジェクトのリリースワークフローを自動化する","Python パッケージの変更ログを生成する","Rust ベースのプロジェクトのリリースプロセスを簡素化する"],"ko":["Node.js 프로젝트의 릴리즈 워크플ロー 자동화","Python 패키지의 변경 로그 생성","Rust 기반 프로젝트의 릴리즈 프로세스 간소화"],"es":["Automatizar flujos de trabajo de lanzamiento para proyectos Node.js","Generar registros de cambios para paquetes Python","Optimizar procesos de lanzamiento para proyectos basados en Rust"],"fr":["Automatiser les flux de travail de lancement pour les projets Node.js","Générer des journaux des modifications pour les packages Python","Optimiser les processus de lancement pour les projets basés sur Rust"],"de":["Automatisierung von Release-Workflows für Node.js-Projekte","Generierung von Changelogs für Python-Pakete","Optimierung von Release-Prozessen für Rust-basierte Projekte"],"pt":["Automatizar fluxos de trabalho de lançamento para projetos Node.js","Gerar changelogs para pacotes Python","Otimizar processos de lançamento para projetos baseados em Rust"],"ru":["Автоматизация рабочих процессов выпуска для проектов Node.js","Генерация журналов изменений для пакетов Python","Оптимизация процессов выпуска для проектов на основе Rust"],"ar":["توفير سير عمل إصدار آليّة لمشاريع Node.js","توليد سجلات التغييرات لمكتبات Python","تبسيط عمليات الإصدار لمشاريع مبنية على Rust"]},"limitations":{"en":["Requires Claude Code plugin installation","Limited to project types with supported version files (e.g., package.json, pyproject.toml, Cargo.toml)"],"zh":["需要安装 Claude Code 插件","仅限于具有支持的版本文件的项目类型（例如 package.json、pyproject.toml、Cargo.toml）"],"ja":["Claude Code プラグインのインストールが必要","サポートされているバージョンファイル（例：package.json、pyproject.toml、Cargo.toml）を持つプロジェクトタイプのみに限定"],"ko":["Claude Code 플러그イン 설치가 필요","지원되는 버전 파일(pakcage.json, pyproject.toml, Cargo.toml)을 갖는 프로젝트 유형만으로 제한"],"es":["Requiere la instalación del plugin Claude Code","Limitado a tipos de proyectos con archivos de versión compatibles (por ejemplo, package.json, pyproject.toml, Cargo.toml)"],"fr":["Nécessite l''installation du plugin Claude Code","Limité aux types de projets avec des fichiers de version pris en charge (par exemple, package.json, pyproject.toml, Cargo.toml)"],"de":["Erfordert die Installation des Claude Code-Plugins","Begrenzt auf Projekttypen mit unterstützten Versionsdateien (z. B. package.json, pyproject.toml, Cargo.toml)"],"pt":["Exige a instalação do plug-in Claude Code","Limitado a tipos de projetos com arquivos de versão suportados (por exemplo, package.json, pyproject.toml, Cargo.toml)"],"ru":["Требует установки плагина Claude Code","Ограничен типами проектов с поддерживаемыми файлами версий (например, package.json, pyproject.toml, Cargo.toml)"],"ar":["يتطلب تثبيت إضافة Claude Code","محدود بنوعيات المشاريع ذات الملفات المدعومة لإصدار (على سبيل المثال package.json و pyproject.toml و Cargo.toml)"]},"version":3},"contentHash":"220b163cfe79562e417d5fe8a2586d254aabac186a86bb667a087743196d94be","qualityScore":59}');
