INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('avivsinai/jenkins-cli/jk', 'community', 'avivsinai', 'jenkins-cli', 'avivsinai/jenkins-cli', 'jk', 0, 0, 59, '2026-03-04T13:07:01.681Z', '2026-03-04T13:24:33.206Z', 'e779439c722ed4a4e7f631bf58931479d4964104786993fa56703f8b865719b9', '{"id":"avivsinai/jenkins-cli/jk","name":"jk","description":{"zh":"jk 是一个 GitHub 风格的 Jenkins CLI 工具，用于管理 Jenkins 任务。它允许您从终端控制上下文、运行、日志和管理任务","ja":"jk は GitHub スタイルの Jenkins CLI ツールで、Jenkins タスクを管理します。端末からコンテキスト、実行、ログ、管理タスクを制御できます","ko":"jk는 GitHub 스타일의 Jenkins CLI 도구로 Jenkins 태스크를 관리합니다. 터미널에서 컨텍스트, 실행, 로그 및 관리 태스크를 제어할 수 있습니다","es":"jk es una herramienta de línea de comandos de estilo GitHub para Jenkins, que permite gestionar contextos, ejecuciones, registros y tareas de administración desde la terminal","fr":"jk est un outil en ligne de commande de style GitHub pour Jenkins, qui permet de gérer les contextes, les exécutions, les journaux et les tâches d''administration depuis le terminal","de":"jk ist ein GitHub-Style-CLI-Tool für Jenkins, das das Verwalten von Kontexten, Ausführungen, Protokollen und Administrationsaufgaben aus der Konsole ermöglicht","pt":"jk é uma ferramenta de linha de comando de estilo GitHub para gerenciar contextos, execuções, logs e tarefas de administração do Jenkins","ru":"jk — это инструмент командной строки в стиле GitHub для управления контекстами, запусками, журналами и задачами администрирования Jenkins","ar":"jk هو أداة سطر أوامر من نمط GitHub لإدارة السياقات وتنفيذها وسجلات وإدارة المهام في جينكينز","en":"GitHub-style CLI for Jenkins — manage contexts, runs, logs, and admin tasks from your terminal."},"seo":{"title":{"zh":"AI工具：jk GitHub风格的Jenkins CLI","ja":"AIエージェント：jk GitHubスタイルのJenkins CLI","ko":"AI 에이전트: jk GitHub 스타일의 Jenkins CLI","es":"Herramientas de AI: jk, CLI de Jenkins","fr":"Outils d''IA: jk, CLI GitHub pour Jenkins","de":"KI-Too