INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zubayer0077/Claude-Multi-Agent-Research-System-Skill/multi-agent-researcher', 'multi-agent-researcher', 'zubayer0077', 'Claude-Multi-Agent-Research-System-Skill', 'community', 'multi-agent-researcher zubayer0077 Claude-Multi-Agent-Research-System-Skill community Multi-Agent-Researcher支持多智能体研究的并行执行和审计，实现高效的结构化调查和workflow规划 マルチエージェント研究を実行するためのAIエージェント。並行実行と監査をサポートして、効率的な構造化調査とワークフロー計画を実現 다중 에이전트 연구를 위한 Multi-Agent-Researcher. 병렬 실행 및 감사를 지원하여 효율적인 구조화 조사를 수행하고 워크플로우 계획을 수립합니다 El agente multi-agent-researcher permite la investigación en paralelo y la planificación de flujos de trabajo estructurados L''agent multi-agent-researcher permet la recherche en parallèle et la planification de flux de travail structurés Der Agent multi-agent-researcher ermöglicht die parallele Forschung und die Planung strukturierter Workflows O multi-agent-researcher é uma ferramenta de IA que orquestra investigações com execução paralela e auditorias para uma investigação eficiente e estruturada. ИИ Агент multi-agent-researcher оркестрирует исследования с параллельным выполнением и аудитами для эффективных и структурированных расследований أداة الذكاء الاصطناعي multi-agent-researcher تشكل تحقيقات مع التنفيذ الموازي والتدقيق من أجل تحقيقات فعالة ومنظمة 🧩 Orchestrate multi-agent research with parallel execution and audits for efficient, structured investigations and seamless workflow planning. 如何使用Multi-Agent-Researcher 什么是多智能体研究 Multi-Agent-Researcher替代品 Multi-Agent-Researcher安装 Multi-Agent-Researcher设置指南 AI智能体开发 🧩 Orchestrate multi-agent research with parallel execution and audits for efficient, structured investigations and seamless workflow planning.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('emavgl/oinkoin/translate', 'community', 'emavgl', 'oinkoin', 'emavgl/oinkoin', 'translate', 341, 34, 58, '2026-02-28T10:44:17Z', '2026-03-01T05:16:06.237Z', '621fd8a99d1624c29f890d040b231f8ae39fa681c7ea5792e04b343316dfa291', '{"id":"emavgl/oinkoin/translate","name":"translate","description":{"zh":"Oinkoin是一个Flutter应用程序，帮助您管理支出，无需互联网连接。使用AI工具翻译功能轻松管理您的财务","ja":"Oinkoinはインターネット接続不要の支出管理アプリです。AIエージェントの翻訳機能を使用して簡単に管理しましょう","ko":"Oinkoin은 인터넷 연결 없이 지출을 관리하는 Flutter 애플리케이션입니다. AI 에이전트의 번역 기능을 사용하여 쉽게 관리합니다","es":"Oinkoin es una aplicación de Flutter para gestionar gastos sin internet. Ofrece funcionalidades de traducción y más","fr":"Oinkoin est une application Flutter pour gérer les dépenses sans internet. Elle offre des fonctionnalités de traduction et plus","de":"Oinkoin ist eine Flutter-App, um Ausgaben ohne Internet zu verwalten. Sie bietet Übersetzungs- und weitere Funktionen","pt":"Oinkoin é um aplicativo Flutter para gerenciamento de despesas sem necessidade de internet. Aprenda a utilizá-lo com ferramentas de IA","ru":"Oinkoin - приложение Flutter для управления расходами без интернета. Узнайте, как использовать его с ИИ Агентами","ar":"Oinkoin هو تطبيق Flutter لإدارة النفقات بدون إنترنت. تعلم كيف تستفيد منه مع أدوات الذكاء الاصطناعي","en":"Oinkoin is a flutter app for helping you managing your expenses. No internet required."},"seo":{"title":{"zh":"AI工具翻译：Oinkoin 应用程序","ja":"AIエージェント翻訳：Oinkoinアプリ","ko":"AI 에이전트 번역: Oinkoin 애플리케이션","es":"Herramientas de inteligencia artificial: Traducir con Oin...","fr":"Outils d''intelligence artificielle: Traduire avec Oinkoin","de":"KI-Tools: Übersetzen mit Oinkoin","pt":"Ferramentas de IA: Traduzir com Oinkoin","ru":"ИИ Агенты: Перевод с Oinkoin","ar":"أدوات الذكاء الاصطناعي: ترجمة مع Oinkoin","en":"translate"},"description":{"zh":"Oinkoin是一个Flutter应用程序，帮助您管理支出，无需互联网连接。使用AI工具翻译功能轻松管理您的财务","ja":"Oinkoinはインターネット接続不要の支出管理アプリです。AIエージェントの翻訳機能を使用して簡単に管理しましょう","ko":"Oinkoin은 인터넷 연결 없이 지출을 관리하는 Flutter 애플리케이션입니다. AI 에이전트의 번역 기능을 사용하여 쉽게 관리합니다","es":"Oinkoin es una aplicación de Flutter para gestionar gastos sin internet. Ofrece funcionalidades de traducción y más","fr":"Oinkoin est une application Flutter pour gérer les dépenses sans internet. Elle offre des fonctionnalités de traduction et plus","de":"Oinkoin ist eine Flutter-App, um Ausgaben ohne Internet zu verwalten. Sie bietet Übersetzungs- und weitere Funktionen","pt":"Oinkoin é um aplicativo Flutter para gerenciamento de despesas sem necessidade de internet. Aprenda a utilizá-lo com ferramentas de IA","ru":"Oinkoin - приложение Flutter для управления расходами без интернета. Узнайте, как использовать его с ИИ Агентами","ar":"Oinkoin هو تطبيق Flutter لإدارة النفقات بدون إنترنت. تعلم كيف تستفيد منه مع أدوات الذكاء الاصطناعي","en":"Oinkoin is a flutter app for helping you managing your expenses. No internet required."},"definition":{"en":"Oinkoin is a flutter app for helping you managing your expenses. No internet required."},"features":{"zh":["无需互联网连接","支持多语言","轻松管理支出","Flutter应用程序","AI工具翻译功能"],"ja":["インターネット接続不要","多言語対応","簡単な支出管理","Flutterアプリ","AIエージェント翻訳機能"],"ko":["인터넷 연결 필요 없음","다중 언어 지원","쉽게 지출 관리","Flutter 애플리케이션","AI 에이전트 번역 기능"],"es":["Traducción sin internet","Gestión de gastos en línea","Aplicación de Flutter","Funcionalidades de inteligencia artificial","Sin necesidad de conexión a internet"],"fr":["Traduction sans internet","Gestion des dépenses en ligne","Application Flutter","Fonctionnalités d''intelligence artificielle","Pas besoin de connexion à internet"],"de":["Übersetzung ohne Internet","Ausgabenverwaltung online","Flutter-App","KI-Funktionen","Keine Internetverbindung erforderlich"],"pt":["Gerenciamento de despesas sem internet","Desenvolvido com Flutter","Ferramentas de IA para ajudar usuários","Aplicativo fácil de usar","Não requer conexão com a internet"],"ru":["Управление расходами без интернета","Разработано на Flutter","ИИ Агенты для помощи пользователям","Простое в использовании приложение","Не требует подключения к интернету"],"ar":["إدارة النفقات بدون إنترنت","مطور باستخدام Flutter","أدوات الذكاء الاصطناعي لمساعدة المستخدمين","تطبيق سهل الاستخدام","لا يحتاج إلى الاتصال بالإنترنت"]},"keywords":{"zh":["AI工具翻译","Oinkoin应用程序","无需互联网连接","支出管理","Flutter应用程序","如何使用AI工具翻译","AI工具翻译功能","Oinkoin应用程序下载"],"ja":["AIエージェント翻訳","Oinkoinアプリ","インターネット接続不要","支出管理","Flutterアプリ","AIエージェント翻訳の使い方","AIエージェント翻訳機能","Oinkoinアプリのダウンロード"],"ko":["AI 에이전트 번역","Oinkoin 애플리케이션","인터넷 연결 필요 없음","지출 관리","Flutter 애플리케이션","AI 에이전트 번역 사용법","AI 에이전트 번역 기능","Oinkoin 애플리케이션 다운로드"],"es":["herramientas de inteligencia artificial","traducir sin internet","gestión de gastos en línea","Oinkoin alternativa","cómo usar Oinkoin","instalar Oinkoin","guiá de configuración de Oinkoin"],"fr":["outils d''intelligence artificielle","traduire sans internet","gestion des dépenses en ligne","Oinkoin alternative","comment utiliser Oinkoin","installer Oinkoin","guide de configuration d''Oinkoin"],"de":["KI-Tools","übersetzen ohne Internet","Ausgabenverwaltung online","Oinkoin-Alternative","wie man Oinkoin verwendet","Oinkoin installieren","Einrichtungsanleitung für Oinkoin"],"pt":["ferramentas de IA","gerenciamento de despesas","aplicativos Flutter","Oinkoin alternative","como usar Oinkoin","Oinkoin vs outros aplicativos","instalar Oinkoin","guia de configuração do Oinkoin"],"ru":["ИИ Агенты","управление расходами","приложения Flutter","Oinkoin альтернатива","как использовать Oinkoin","Oinkoin vs другие приложения","установить Oinkoin","руководство по настройке Oinkoin"],"ar":["أدوات الذكاء الاصطناعي","إدارة النفقات","تطبيقات Flutter","بديل Oinkoin","كيفية استخدام Oinkoin","Oinkoin مقابل تطبيقات أخرى","تثبيت Oinkoin","دليل إعداد Oinkoin"]}},"owner":"emavgl","repo":"oinkoin","repoPath":"emavgl/oinkoin","stars":341,"forks":34,"updatedAt":"2026-02-28T10:44:17Z","topics":[],"category":"community","skillMd":{"name":"translate","description":"Translates untranslated strings in a locale JSON file for the Oinkoin app. Use when the user wants to localise or update translations for a specific language, or says translate <locale>.","bodyPreview":"# Skill: translate\n\nTranslate untranslated strings in a locale JSON file for the Oinkoin app.\n\n## Usage\n```\n/translate <locale-file>\n```\nExample: `/translate assets/locales/it.json`\n\nIf no file is specified, address all the locale files\n\n---\n\n## How translations work in this project\n\n- All locale files live in `assets/locales/` (e.g. `it.json`, `de.json`, `pt-BR.json`).\n- `assets/locales/en-US.json` is the **source of truth**: every key AND its English value are listed there.\n- Every other local","body":"# Skill: translate\n\nTranslate untranslated strings in a locale JSON file for the Oinkoin app.\n\n## Usage\n```\n/translate <locale-file>\n```\nExample: `/translate assets/locales/it.json`\n\nIf no file is specified, address all the locale files\n\n---\n\n## How translations work in this project\n\n- All locale files live in `assets/locales/` (e.g. `it.json`, `de.json`, `pt-BR.json`).\n- `assets/locales/en-US.json` is the **source of truth**: every key AND its English value are listed there.\n- Every other locale file has the **same keys**. A string is **untranslated** when its value is identical to its key (i.e. it was never localised and still reads in English).\n- A string is **already translated** when its value differs from its key. **Never touch those.**\n\n## Step-by-step instructions\n\n### 0. Sync keys with the codebase (always run first)\nRun the sync script from the project root to ensure `en-US.json` is up-to-date and stale keys are removed from all locale files:\n```\npython3 scripts/update_en_strings.py\n```\nThis regenerates `en-US.json` from all `.i18n` strings found in `lib/`, and removes obsolete keys from every other locale file. Run it before translating so you are working against the current set of keys.\n\n### 1. Read the target locale file\nRead the full file specified by the user.\n\n### 2. Identify untranslated strings\nA string is untranslated when `value == key`. Collect every such entry.\n\nIf there are no untranslated strings, tell the user and stop.\n\n### 3. For each untranslated string — look up context before translating\nDo **not** guess from the key text alone. For each untranslated key:\n\n- Search the Dart source code (Grep in `lib/`) for the exact key string to find where it is used.\n- Look at the surrounding widget/function/page to understand the context (e.g. is it a button label, a dialog title, an error message, a settings toggle description?).\n- Only then choose the most natural, contextually appropriate translation for the target language.\n\n### 4. Write the translated strings\nEdit the locale file, replacing only the untranslated values. Keep every other entry byte-for-byte identical.\n\n### 5. Report what changed\nAfter editing, print a compact table of the strings you translated:\n\n| Key | Translation |\n|-----|-------------|\n| … | … |\n\n---\n\n## Important rules\n\n- **Never modify already-translated strings** (value ≠ key).\n- **Never change keys** — only values.\n- Preserve placeholders exactly as written: `%s`, `%d`, `%1$s`, etc.\n- Match the tone and terminology of the strings that ARE already translated in the same file — consistency matters more than literal accuracy.\n- For technical or brand terms (e.g. \"Oinkoin Pro\", \"PIN\", \"CSV\", \"JSON\") keep them untranslated.\n- If a string has no natural translation (e.g. it is already the correct word in the target language), it is fine to leave the value equal to the key — but note this in your report.\n- Process the **whole file** in one pass; do not ask for confirmation before each string.\n\n## Exceptions\n\nFor British english use en-GB.json - in this case, key and value will most of case matches. Consider all the strings as already translated and skip it.\n"},"lastSynced":"2026-03-01T05:16:06.237Z","agentAnalysis":{"suitability":{"en":"Perfect for Multilingual Agents needing advanced locale file management and translation capabilities.","zh":"适合需要高级本地化文件管理和翻译功能的多语言代理。","ja":"マルチリンガルエージェントが高度なロケールファイル管理と翻訳機能を必要とする場合に最適です。","ko":"다국어 에이전트가 고급 로케일 파일 관리 및 번역 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes Multilingües que necesitan gestión avanzada de archivos de localización y capacidades de traducción.","fr":"Parfait pour les Agents Multilingues nécessitant une gestion avancée des fichiers de localisation et des capacités de traduction.","de":"Perfekt für mehrsprachige Agents, die erweiterte Verwaltung von Lokalisierungsdateien und Übersetzungsfähigkeiten benötigen.","pt":"Perfeito para Agentes Multilíngues que necessitam de gerenciamento avançado de arquivos de localização e capacidades de tradução.","ru":"Идеально для многоязычных агентов, требующих продвинутого управления файлами локализации и возможностей перевода.","ar":"مثالي للوكلاء المتعددين اللغات الذين يحتاجون إلى إدارة متقدمة لملفات الموقع والقدرات الترجمة."},"recommendation":{"en":"Empowers agents to translate untranslated strings in locale JSON files, leveraging the Oinkoin app''s structure and assets/locales/en-US.json as the source of truth, utilizing file formats like .json and protocols for seamless integration.","zh":"赋予代理翻译未翻译字符串在locale JSON文件的能力，利用Oinkoin应用程序的结构和assets/locales/en-US.json作为真实来源，使用.json等文件格式和协议实现无缝集成。","ja":"エージェントにロケールJSONファイル内の未翻訳文字列を翻訳する能力を与え、Oinkoinアプリケーションの構造とassets/locales/en-US.jsonを真実の情報源として使用し、.jsonなどのファイル形式やプロトコルを使用してシームレスな統合を実現します。","ko":"에이전트에게 로케일 JSON 파일 내의 번역되지 않은 문자열을 번역할 수 있는 능력을 부여하며, Oinkoin 애플리케이션의 구조와 assets/locales/en-US.json을 진실된 정보源으로 사용하여, .json과 같은 파일 형식 및 프로토콜을 사용하여 무결점 통합을 구현합니다.","es":"Permite a los agents traducir cadenas no traducidas en archivos JSON de localización, aprovechando la estructura de la aplicación Oinkoin y assets/locales/en-US.json como la fuente de verdad, utilizando formatos de archivo como .json y protocolos para una integración perfecta.","fr":"Permet aux agents de traduire les chaînes non traduites dans les fichiers JSON de localisation, en tirant parti de la structure de l''application Oinkoin et de assets/locales/en-US.json comme source de vérité, en utilisant des formats de fichier comme .json et des protocoles pour une intégration transparente.","de":"Ermöglicht es Agents, nicht übersetzte Zeichenketten in Lokalisierungs-JSON-Dateien zu übersetzen, unter Nutzung der Struktur der Oinkoin-App und assets/locales/en-US.json als Single Source of Truth, unter Verwendung von Dateiformaten wie .json und Protokollen für nahtlose Integration.","pt":"Habilita os agentes a traduzir cordas não traduzidas em arquivos JSON de localização, aproveitando a estrutura do aplicativo Oinkoin e assets/locales/en-US.json como a fonte de verdade, utilizando formatos de arquivo como .json e protocolos para integração sem problemas.","ru":"Наделяет агентов возможностью переводить непереведенные строки в файлах локализации JSON, используя структуру приложения Oinkoin и assets/locales/en-US.json в качестве источника правды, используя форматы файлов, такие как .json, и протоколы для бесшовной интеграции.","ar":"يمنح الوكلاء القدرة على ترجمة السلاسل غير المترجمة في ملفات JSON للموقع، مستفيدا من هيكل تطبيق Oinkoin و assets/locales/en-US.json كمرجع الحقيقة، مستخدما تنسيقات الملفات مثل .json وبروتوكولات للتكامل السلس."},"useCases":{"en":["Translating locale files for internationalization","Updating untranslated strings in it.json, de.json, or pt-BR.json files","Maintaining consistency across all locale files"],"zh":["用于国际化的本地化文件翻译","更新it.json、de.json或pt-BR.json文件中的未翻译字符串","维护所有本地化文件的一致性"],"ja":["国際化のためのロケールファイルの翻訳","it.json、de.json、またはpt-BR.jsonファイル内の未翻訳文字列の更新","すべてのロケールファイルの整合性の維持"],"ko":["국제화를 위한 로케일 파일 번역","it.json, de.json 또는 pt-BR.json 파일 내의 번역되지 않은 문자열을 업데이트함","모든 로케일 파일의 일관성을 유지"],"es":["Traducir archivos de localización para internacionalización","Actualizar cadenas no traducidas en archivos it.json, de.json o pt-BR.json","Mantener la coherencia en todos los archivos de localización"],"fr":["Traduire des fichiers de localisation pour l''internationalisation","Mettre à jour les chaînes non traduites dans les fichiers it.json, de.json ou pt-BR.json","Maintenir la cohérence entre tous les fichiers de localisation"],"de":["Übersetzen von Lokalisierungsdateien für Internationalisierung","Aktualisieren nicht übersetzter Zeichenketten in it.json, de.json oder pt-BR.json Dateien","Konsistenz über alle Lokalisierungsdateien hinweg beibehalten"],"pt":["Traduzir arquivos de localização para internacionalização","Atualizar cordas não traduzidas em arquivos it.json, de.json ou pt-BR.json","Manter a consistência em todos os arquivos de localização"],"ru":["Перевод файлов локализации для интернационализации","Обновление непереведенных строк в файлах it.json, de.json или ru.json","Поддержание согласованности во всех файлах локализации"],"ar":["ترجمة ملفات الموقع للتعريب","تحديث السلاسل غير المترجمة في ملفات it.json، de.json أو ar.json","الحفاظ على الاتساق في جميع ملفات الموقع"]},"limitations":{"en":["Requires access to locale files in assets/locales/","No internet connection required but file system access is necessary"],"zh":["需要访问assets/locales/中的本地化文件","无需互联网连接，但需要文件系统访问"],"ja":["assets/locales/内のロケールファイルへのアクセスが必要","インターネット接続は不要ですが、ファイルシステムへのアクセスは必要"],"ko":["assets/locales/ 내 로케일 파일에 대한 액세스가 필요함","인터넷 연결은 필요하지 않지만 파일 시스템 액세스는 필수"],"es":["Requiere acceso a los archivos de localización en assets/locales/","No se requiere conexión a internet, pero es necesario el acceso al sistema de archivos"],"fr":["Nécessite un accès aux fichiers de localisation dans assets/locales/","Aucune connexion Internet requise mais un accès au système de fichiers est nécessaire"],"de":["Erfordert Zugriff auf Lokalisierungsdateien in assets/locales/","Keine Internetverbindung erforderlich, aber Dateisystemzugriff ist notwendig"],"pt":["Requer acesso a arquivos de localização em assets/locales/","Nenhuma conexão com a internet é necessária, mas o acesso ao sistema de arquivos é necessário"],"ru":["Требует доступа к файлам локализации в assets/locales/","Не требуется подключение к Интернету, но необходим доступ к файловой системе"],"ar":["يتطلب الوصول إلى ملفات الموقع في assets/locales/","لا يتطلب اتصالا بالإنترنت ولكن الوصول إلى نظام الملفات ضروري"]},"version":3},"contentHash":"621fd8a99d1624c29f890d040b231f8ae39fa681c7ea5792e04b343316dfa291","qualityScore":58}');
