INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('corbanb/x4-mono/add-router', 'add-router', 'corbanb', 'x4-mono', 'community', 'add-router corbanb x4-mono community add-router是一个包含Next.js、React Native、Electron、Hono.js的mono repo，提供了丰富的功能和工具 add-routerはNext.js、React Native、Electron、Hono.jsを含むモノリポで、多くの便利な機能を提供します add-router는 Next.js, React Native, Electron, Hono.js를 포함하는 모노 리포지토리로 풍부한 기능을 제공합니다 add-router es un mono repositorio para Next.js, React Native, Electron y Hono.js con muchas características add-router est un mono dépôt pour Next.js, React Native, Electron et Hono.js avec de nombreuses fonctionnalités add-router ist ein Mono-Repository für Next.js, React Native, Electron und Hono.js mit vielen Funktionen Um mono repositório para Next.js, React Native, Electron e Hono.js com muitos recursos. Adicione router ao seu projeto com facilidade Моно репозиторий для Next.js, React Native, Electron и Hono.js с множеством функций. Добавьте маршрутизатор к вашему проекту с легкостью مستودع واحد لمشاريع Next.js و React Native و Electron و Hono.js مع العديد من المزايا. أضف Router إلى مشروعك بسهولة A mono repo for Next.js, React Native, Electron, and Hono.js with lots of bells and whistles. add-router安装 Next.js开发工具 React Native开发效率 Electron开发简化 Hono.js开发框架 mono repo开发 如何使用add-router add-router与其他工具比较 A mono repo for Next.js, React Native, Electron, and Hono.js with lots of bells and whistles. ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Kaakati/managing-director/Scenario Planning', 'community', 'Kaakati', 'managing-director', 'Kaakati/managing-director', 'Scenario Planning', 0, 0, 57, '2026-03-01T21:28:29Z', '2026-03-02T04:03:50.648Z', 'bc8ffbeeb800654c8b4dc0ce0a3a8e4cd807580808c64a38a93f8134481885e2', '{"id":"Kaakati/managing-director/Scenario Planning","name":"Scenario Planning","description":{"zh":"场景规划是一种AI驱动的咨询系统，使用Claude Code的AI智能代理和技能框架，复制大四公司的广度和深度","ja":"シナリオプランニングは、Claude CodeのAIエージェントとスキルフレームワークを使用して、ビッグ4の広さと深さを再現するAI駆動のコンサルティングシステムです","ko":"시나리오 계획은 Claude Code의 AI 에이전트와 스킬 프레임워크를 사용하여 빅4 회사의 폭과 깊이를 복제하는 AI駆動의 컨설팅 시스템입니다","es":"Nuestra plataforma de planificación de escenarios utiliza Agentes de IA para ofrecer deliverables de alta calidad, similares a los de las grandes firmas de consultoría","fr":"Notre plateforme de planification de scénarios utilise des Agents IA pour fournir des livrables de haute qualité, similaires à ceux des grandes sociétés de conseil","de":"Unsere Szenario-Planungsplattform nutzt KI-Agents, um hochwertige Deliverables zu liefern, ähnlich wie bei großen Beratungsunternehmen","pt":"O Planejamento de Cenários é um sistema de consultoria impulsionado por IA que replica a amplitude e profundidade das Big 4","ru":"Планирование Сценариев - это система консалтинга на основе ИИ, которая реплицирует широту и глубину Big 4","ar":"تخطيط السيناريوهات هو نظام استشاري مدعوم بالذكاء الاصطناعي يقلد اتساع وعمق الشركات الكبرى الأربع","en":"An AI-powered consultancy system that replicates the breadth and depth of Big 4 firms (Deloitte, PwC, EY, KPMG) using Claude Code''s agents and skills framework. A Managing Director orchestrator routes engagements to 9 practice-area partners, each equipped with domain-specific skills delivering bo..."},"seo":{"title":{"zh":"AI智能代理-场景规划","ja":"AIエージェントのシナリオプランニング","ko":"AI 에이전트를 이용한 시