INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Nice-Wolf-Studio/agent-github-skills/search-operations', 'search-operations', 'Nice-Wolf-Studio', 'agent-github-skills', 'community', 'search-operations Nice-Wolf-Studio agent-github-skills community search-operations是一个使用gh CLI复制GitHub MCP服务器功能的AI智能工具集合 search-operationsは、gh CLIを使用してGitHub MCPサーバーの機能を複製するAIエージェントのコレクションです search-operations는 gh CLI를 사용하여 GitHub MCP 서버 기능을 복제하는 AI 에이전트의 컬렉션입니다 Colección de habilidades de Claude Code que replican la funcionalidad del servidor GitHub MCP utilizando gh CLI Collection de compétences Claude Code qui reproduisent la fonctionnalité du serveur GitHub MCP en utilisant gh CLI Sammlung von Claude-Code-Fähigkeiten, die die Funktionalität des GitHub-MCP-Servers mithilfe von gh CLI nachbilden O search-operations é uma coleção de habilidades do Claude Code que replicam a funcionalidade do servidor GitHub MCP usando gh CLI para desenvolvedores Search-operations - это коллекция навыков Claude Code, которые реплицируют функциональность сервера GitHub MCP с помощью gh CLI для разработчиков search-operations هي مجموعة من مهارات Claude Code التي تتكرر وظيفة خادم GitHub MCP باستخدام gh CLI للمطورين A collection of Claude Code skills that replicate GitHub MCP server functionality using gh CLI 如何使用search-operations 什么是gh CLI search-operations替代品 search-operations vs GitHub MCP search-operations安装 search-operations设置指南 AI智能工具 GitHub API CLI命令行工具 A collection of Claude Code skills that replicate GitHub MCP server functionality using gh CLI');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ElliotJLT/Claude-Skill-Potions/eta', 'community', 'ElliotJLT', 'Claude-Skill-Potions', 'ElliotJLT/Claude-Skill-Potions', 'eta', 0, 0, 57, '2026-03-04T13:07:01.664Z', '2026-03-04T13:21:02.540Z', '2ac9d2f5606746f4e09271f19995e5a226be24f4d36d6e5494ae96264e814339', '{"id":"ElliotJLT/Claude-Skill-Potions/eta","name":"eta","description":{"zh":"eta是一个用于优化Ops和产品工作流的AI智能工具集合，包括多种Claude技能","ja":"etaは、オペレーションと製品のワークフローを最適化するために開発されたAIエージェントのコレクションです","ko":"eta는 오퍼레이션과 제품 워크플로를 최적화하기 위한 AI 에이전트 콜렉션입니다","es":"eta es una colección de habilidades de Claude diseñada para optimizar flujos de trabajo de operaciones y productos","fr":"eta est un ensemble de compétences Claude conçu pour optimiser les flux de travail d''opérations et de produits","de":"eta ist eine Sammlung von Claude-Fähigkeiten zur Optimierung von Arbeitsabläufen für Betrieb und Produkte","pt":"A skill eta é uma coleção de habilidades do Claude para otimizar workflows de Ops e Produto","ru":"Навык eta - это коллекция возможностей Claude для оптимизации рабочих процессов","ar":"المهارة eta هي مجموعة من مهارات كلود لتحسين العمليات","en":"A collection of Claude skills I have concocted to optimise my Ops/Product workflows."},"seo":{"title":{"zh":"AI智能工具eta","ja":"AIエージェントeta","ko":"AI 에이전트 eta","es":"Herramientas de AI: eta para optimizar flujos de trabajo","fr":"Outils d''IA: eta pour optimiser les flux de travail","de":"KI-Tools: eta für optimierte Arbeitsabläufe","pt":"Ferramentas de IA: eta para Otimização de Workflows","ru":"ИИ Агенты: eta для Оптимизации Работы","ar":"أدوات الذكاء الاصطناعي: eta لتحسين العمليات","en":"eta"},"description":{"zh":"eta是一个用于优化Ops和产品工作流的AI智能工具集合，包括多种Claude技能","ja":"etaは、オペレーションと製品のワークフローを最適化するために開発されたAIエージェントのコレクションです","ko":"eta는 오퍼레이션과 제품 워크플로를 최적화하기 위한 AI 에이전트 콜렉션입니다","es":"eta es una colección de habilidades de Claude diseñada para optimizar flujos de trabajo de operaciones y productos","fr":"eta est un ensemble de compétences Claude conçu pour optimiser les flux de travail d''opérations et de produits","de":"eta ist eine Sammlung von Claude-Fähigkeiten zur Optimierung von Arbeitsabläufen für Betrieb und Produkte","pt":"A skill eta é uma coleção de habilidades do Claude para otimizar workflows de Ops e Produto","ru":"Навык eta - это коллекция возможностей Claude для оптимизации рабочих процессов","ar":"المهارة eta هي مجموعة من مهارات كلود لتحسين العمليات","en":"A collection of Claude skills I have concocted to optimise my Ops/Product workflows."},"definition":{"en":"A collection of Claude skills I have concocted to optimise my Ops/Product workflows."},"features":{"zh":["优化Ops工作流","提高产品工作流效率","支持多种Claude技能","易于集成和使用","提供实时数据分析"],"ja":["オペレーションのワークフローを最適化","製品のワークフローを効率化","複数のClaudeスキルをサポート","簡単な統合と使用","リアルタイムデータ分析を提供"],"ko":["오퍼레이션 워크플로 최적화","제품 워크플로 효율성 향상","다양한 Claude 스킬 지원","쉬운 통합 및 사용","실시간 데이터 분석 제공"],"es":["Optimización de flujos de trabajo con herramientas de AI","Integración con tecnologías como React y Node.js","Automatización de tareas con CLI","Mejora de la eficiencia operativa","Personalización de flujos de trabajo"],"fr":["Optimisation des flux de travail avec des outils d''IA","Intégration avec des technologies comme React et Node.js","Automatisation de tâches avec CLI","Amélioration de l''efficacité opérationnelle","Personnalisation des flux de travail"],"de":["Optimierung von Arbeitsabläufen mit KI-Tools","Integration mit Technologien wie React und Node.js","Automatisierung von Aufgaben mit CLI","Verbesserung der Betriebseffizienz","Anpassung von Arbeitsabläufen"],"pt":["Otimização de workflows de Ops","Otimização de workflows de Produto","Integração com ferramentas de IA","Automatização de tarefas","Análise de dados e relatórios"],"ru":["Оптимизация рабочих процессов","Автоматизация задач","Интеграция с ИИ Агентами","Анализ данных и отчеты","Улучшение производительности"],"ar":["تحسين العمليات","تutomatización من المهام","دمج مع أدوات الذكاء الاصطناعي","تحليل البيانات والتقرير","تحسين الأداء"]},"keywords":{"zh":["如何使用eta","什么是AI智能工具","eta替代品","eta vs 其他AI工具","eta安装指南","eta设置教程","AI智能工具开发","工作流优化技巧"],"ja":["etaの使い方","AIエージェントとは","etaの代替","eta vs 他のAIエージェント","etaのインストールガイド","etaの設定方法","AIエージェントの開発","ワークフローの最適化方法"],"ko":["eta 사용 방법","AI 에이전트란","eta 대체품","eta vs 다른 AI 에이전트","eta 설치 가이드","eta 설정 방법","AI 에이전트 개발","워크플로우 최적화 방법"],"es":["herramientas de AI para operaciones","eta vs otros agentes de IA","cómo usar eta para optimizar flujos de trabajo","guía de instalación de eta","configuración de eta para productos","alternativas a eta para automatización","optimización de flujos de trabajo con Python","integración de eta con tecnologías de desarrollo"],"fr":["outils d''IA pour opérations","eta vs autres agents d''IA","comment utiliser eta pour optimiser les flux de travail","guide d''installation de eta","configuration de eta pour produits","alternatives à eta pour l''automatisation","optimisation des flux de travail avec Python","intégration de eta avec des technologies de développement"],"de":["KI-Tools für Betrieb","eta vs andere KI-Agents","wie man eta verwendet, um Arbeitsabläufe zu optimieren","Installationsanleitung für eta","Konfiguration von eta für Produkte","Alternativen zu eta für Automatisierung","Optimierung von Arbeitsabläufen mit Python","Integration von eta mit Entwicklungstechnologien"],"pt":["ferramentas de ia","otimização de workflows","como usar eta","eta vs ferramentas de ia","instalar eta","guia de configuração eta","desenvolvedores de ia","ferramentas de automação"],"ru":["ИИ Агенты","оптимизация рабочих процессов","что такое eta","eta альтернатива","установка eta","руководство по настройке eta","разработчики ИИ","инструменты автоматизации"],"ar":["أدوات الذكاء الاصطناعي","تحسين العمليات","ما هي eta","eta بديل","تثبيت eta","دليل إعداد eta","مطورو الذكاء الاصطناعي","أدوات الأتمتة"]}},"owner":"ElliotJLT","repo":"Claude-Skill-Potions","repoPath":"ElliotJLT/Claude-Skill-Potions","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.664Z","topics":[],"category":"community","skillMd":{"name":"eta","description":"|","bodyPreview":"# ETA\n\n<purpose>\nProvides realistic time estimates for coding tasks before work begins. Users often\nunderestimate task complexity. This skill analyzes codebase scope, categorizes task\ncomplexity, identifies risk factors, and calculates estimates based on measured\nClaude Code performance baselines. Prevents surprise delays and enables better planning.\n</purpose>\n\n## Instructions\n\n### Step 1: Gather Task Context\n\nWhen triggered, collect:\n- Task description from the user\n- Path to relevant codebase","body":"# ETA\n\n<purpose>\nProvides realistic time estimates for coding tasks before work begins. Users often\nunderestimate task complexity. This skill analyzes codebase scope, categorizes task\ncomplexity, identifies risk factors, and calculates estimates based on measured\nClaude Code performance baselines. Prevents surprise delays and enables better planning.\n</purpose>\n\n## Instructions\n\n### Step 1: Gather Task Context\n\nWhen triggered, collect:\n- Task description from the user\n- Path to relevant codebase (default: current directory)\n- Number of files likely in scope (if known)\n\n### Step 2: Run Estimation\n\n```bash\npython scripts/estimate_task.py --task \"<task_description>\" --path \"<codebase_path>\"\n```\n\nOptional flags:\n- `--files <n>`: Override estimated files in scope\n- `--json`: Output structured JSON for programmatic use\n\n### Step 3: Present Estimate\n\nReturn the formatted estimate showing:\n- Task category (trivial/simple/medium/complex/major)\n- Scope analysis (files, lines, test coverage)\n- Time range (low-high estimate)\n- Breakdown by phase (analysis, implementation, testing, verification)\n- Risk factors with explanations\n- Checkpoint recommendations for long tasks\n\n### Step 4: Adjust Based on Feedback\n\nIf user provides more context:\n- Re-run with `--files` override if scope is clearer\n- Adjust category interpretation based on domain knowledge\n\n## NEVER\n\n- Start a complex task without providing an estimate first\n- Give single-point estimates (always provide ranges)\n- Ignore risk factors when they''re detected\n- Skip the estimate for tasks over 15 minutes\n- Promise exact completion times\n\n## ALWAYS\n\n- Run the estimate script before non-trivial tasks\n- Show the breakdown so users understand where time goes\n- Flag risk factors visibly with explanations\n- Recommend checkpoints for tasks over 30 minutes\n- Update estimates if scope changes mid-task\n\n## Examples\n\n### Example 1: User asks about task duration\n\n**Input:** \"How long will it take to add user authentication?\"\n\n**Workflow:**\n1. Run `scripts/estimate_task.py --task \"Add user authentication\" --path .`\n2. Output shows:\n   - Category: Complex\n   - Estimated time: 24-53 minutes\n   - Risk factors: High-risk changes, External dependencies\n   - Recommendation: Break into phases with commits between each\n\n### Example 2: Before starting a feature\n\n**Input:** \"Add a dark mode toggle to settings\"\n\n**Workflow:**\n1. Detect this is a non-trivial task (feature keyword)\n2. Run `scripts/estimate_task.py --task \"Add dark mode toggle to settings\" --path ./src`\n3. Present estimate: 10-22 minutes (Medium complexity)\n4. Begin implementation with checkpoint plan\n\n### Example 3: Quick fix request\n\n**Input:** \"Fix the typo in the README\"\n\n**Workflow:**\n1. Detect trivial task (typo keyword)\n2. Run quick estimate: 3-6 minutes\n3. Proceed immediately (no detailed breakdown needed for trivial tasks)\n"},"lastSynced":"2026-03-04T13:21:02.540Z","agentAnalysis":{"suitability":{"en":"Perfect for Coding Agents needing accurate time estimation for task complexity analysis.","zh":"适合需要准确时间估计用于任务复杂性分析的编码代理。","ja":"タスクの複雑性分析のための正確な時間推定が必要なコーディングエージェントに適しています。","ko":"작업 복잡성 분석을 위한 정확한 시간 추정이 필요한 코딩 에이전트에 적합합니다.","es":"Perfecto para Agentes de Codificación que necesitan una estimación precisa del tiempo para el análisis de la complejidad de las tareas.","fr":"Parfait pour les Agents de Codage ayant besoin d''une estimation précise du temps pour l''analyse de la complexité des tâches.","de":"Perfekt für Codierungsagenten, die eine genaue Zeitberechnung für die Analyse der Aufgabenkomplexität benötigen.","pt":"Perfeito para Agentes de Codificação que precisam de estimativa de tempo precisa para análise de complexidade de tarefas.","ru":"Идеально для Кодировочных Агентов, которым требуется точная оценка времени для анализа сложности задач.","ar":"مثالي للوكلاء البرمجيين الذين يحتاجون إلى تقدير دقيق للوقت لتحليل تعقيد المهام."},"recommendation":{"en":"Empowers agents to provide realistic time estimates for coding tasks by analyzing codebase scope, categorizing task complexity, and identifying risk factors based on measured performance baselines using Claude Code.","zh":"通过分析代码库范围、分类任务复杂性和根据使用 Claude Code 测量的性能基准来识别风险因素，赋予代理提供编码任务的现实时间估计的能力。","ja":"Claude Code を使用して測定されたパフォーマンスベースラインに基づいてコードベースの範囲を分析し、タスクの複雑性を分類し、リスク要因を識別することで、エージェントがコーディングタスクの現実的な時間推定を提供できる力を与えます。","ko":"Claude Code를 사용하여 측정된 성능 기준선에 따라 코드베이스 범위를 분석하고 작업 복잡성을 분류하며 위험 요인을 식별함으로써 에이전트가 코딩 작업에 대한 현실적인 시간 추정을 제공할 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a proporcionar estimaciones de tiempo realistas para tareas de codificación analizando el alcance de la base de código, categorizando la complejidad de la tarea e identificando factores de riesgo en función de líneas de base de rendimiento medidas utilizando Claude Code.","fr":"Permet aux agents de fournir des estimations de temps réalistes pour les tâches de codage en analysant la portée de la base de code, en catégorisant la complexité de la tâche et en identifiant les facteurs de risque sur la base de références de performance mesurées en utilisant Claude Code.","de":"Ermächtigt die Agenten, realistische Zeitabschätzungen für Codierungsaufgaben zu liefern, indem sie den Umfang des Codebases analysieren, die Aufgabenkomplexität kategorisieren und Risikofaktoren auf der Grundlage gemessener Leistungsreferenzwerte unter Verwendung von Claude Code identifizieren.","pt":"Habilita os agentes a fornecer estimativas de tempo realistas para tarefas de codificação, analisando o escopo da base de código, categorizando a complexidade da tarefa e identificando fatores de risco com base em linhas de base de desempenho medidas usando Claude Code.","ru":"Наделяет агентов возможностью предоставлять реалистичные оценки времени для задач кодирования, анализируя объем кодовой базы, категоризируя сложность задачи и определяя факторы риска на основе измеренных базовых показателей производительности с использованием Claude Code.","ar":"يمنح الوكلاء القدرة على تقديم تقديرات زمنية реалистية للمهام البرمجية من خلال تحليل نطاق قاعدة الشفرة وتصنيف تعقيد المهمة وتحديد عوامل الخطر بالاعتماد على مقاييس أداء قاعدة معيارية باستخدام Claude Code."},"useCases":{"en":["Estimating task duration for better project planning","Analyzing codebase complexity to prevent surprise delays","Calculating risk factors for more accurate time estimates"],"zh":["估计任务持续时间以进行更好的项目规划","分析代码库复杂性以防止意外延迟","计算风险因素以获得更准确的时间估计"],"ja":["より良いプロジェクト計画のためのタスク期間の推定","サプライズ遅延を防ぐためのコードベースの複雑性分析","より正確な時間推定のためのリスク要因の計算"],"ko":["더 나은 프로젝트 계획을 위한 작업 기간 추정","เซอร프라이즈 지연을 방지하기 위한 코드베이스 복잡성 분석","더 정확한 시간 추정을 위한 위험 요인 계산"],"es":["Estimación de la duración de la tarea para una mejor planificación del proyecto","Análisis de la complejidad de la base de código para prevenir retrasos sorpresa","Cálculo de factores de riesgo para estimaciones de tiempo más precisas"],"fr":["Estimation de la durée de la tâche pour une meilleure planification du projet","Analyse de la complexité de la base de code pour prévenir les retards inattendus","Calcul des facteurs de risque pour des estimations de temps plus précises"],"de":["Schätzung der Aufgabenlaufzeit für eine bessere Projektplanung","Analyse der Codebase-Komplexität, um überraschende Verzögerungen zu vermeiden","Berechnung von Risikofaktoren für genauere Zeitabschätzungen"],"pt":["Estimativa da duração da tarefa para uma melhor planejamento de projetos","Análise da complexidade da base de código para prevenir atrasos inesperados","Cálculo de fatores de risco para estimativas de tempo mais precisas"],"ru":["Оценка продолжительности задачи для лучшего планирования проектов","Анализ сложности кодовой базы для предотвращения неожиданных задержек","Расчет факторов риска для более точных оценок времени"],"ar":["تقدير مدة المهمة من أجل التخطيط المشروع بشكل أفضل","تحليل تعقيد قاعدة الشفرة لمنع التأخيرات غير المتوقعة","حساب عوامل الخطر من أجل تقديرات زمنية أكثر دقة"]},"limitations":{"en":["Requires access to Claude Code performance baselines","Needs task description and relevant codebase path from the user"],"zh":["需要访问 Claude Code 性能基准","需要用户提供任务描述和相关代码库路径"],"ja":["Claude Code のパフォーマンスベースラインへのアクセスが必要","ユーザーがタスクの説明と関連するコードベースパスを提供する必要がある"],"ko":["Claude Code 성능 기준선에 대한 액세스가 필요","사용자가 작업 설명 및 관련 코드베이스 경로를 제공해야 함"],"es":["Requiere acceso a las líneas de base de rendimiento de Claude Code","Necesita la descripción de la tarea y la ruta de la base de código relevante del usuario"],"fr":["Nécessite l''accès aux références de performance de Claude Code","Nécessite la description de la tâche et le chemin de la base de code pertinent de l''utilisateur"],"de":["Benötigt Zugriff auf die Leistungsreferenzwerte von Claude Code","Benötigt die Aufgabenbeschreibung und den relevanten Codebase-Pfad vom Benutzer"],"pt":["Requer acesso às linhas de base de desempenho do Claude Code","Necessita de descrição da tarefa e caminho relevante da base de código do usuário"],"ru":["Требует доступа к базовым показателям производительности Claude Code","Требует описания задачи и соответствующего пути кодовой базы от пользователя"],"ar":["يتطلب الوصول إلى معايير أداء قاعدة Claude Code","يتطلب وصف المهمة ومسار قاعدة الشفرة المعني من المستخدم"]},"version":3},"contentHash":"2ac9d2f5606746f4e09271f19995e5a226be24f4d36d6e5494ae96264e814339","qualityScore":57}');
