INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mckinsey/agents-at-scale-ark/ark-documentation', 'ark-documentation', 'mckinsey', 'agents-at-scale-ark', 'community', 'ark-documentation mckinsey agents-at-scale-ark community ark-documentation为开发者提供了无供应商依赖的操作，用于开发智能代理应用。它包含了多个智能代理应用项目中开发的模式和实践。 AIエージェントの開発を容易にするark-documentation。多数のAIエージェントアプリケーションプロジェクトで開発されたパターンとプラクティスを含みます。 AI 에이전트 애플리케이션 개발을 위한 ark-documentation. 여러 개의 AI 에이전트 애플리케이션 프로젝트에서 개발된 패턴과 프랙티스를 포함합니다. ARK Documentation proporciona operaciones de recursos de agentes de IA de forma proveedora-agnóstica, codificando patrones y prácticas desarrolladas en decenas de proyectos de aplicaciones de agentes ARK Documentation fournit des opérations de ressources d''agents IA de manière fournisseur-agnostique, codifiant des modèles et des pratiques développés dans des dizaines de projets d''applications d''agents ARK Documentation bietet Operationen von Ressourcen von KI-Agents in einer anbieter-agnostischen Weise, indem es Muster und Praktiken codiert, die in Dutzenden von Anwendungsprojekten von Agents entwickelt wurden A documentação ARK fornece operações agnósticas de provedor para recursos de agente, codificando padrões e práticas desenvolvidas em dezenas de projetos de aplicativos de agente. Документация ARK обеспечивает провайдер-агностические операции для агентских ресурсов, кодифицируя шаблоны и практики, разработанные в десятках агентских проектов. توفر وثائق ARK عمليات غير معتمدة على المزود لموارد الوكيل، وترمز الأنماط والممارسات التي تم تطويرها في عشرات مشاريع تطبيقات الوكيل. Provider-agnostic operations for agentic resources. ARK codifies patterns and practices developed across dozens of agentic application projects. AI智能代理 ark-documentation 无供应商依赖的操作 智能代理应用开发 ark-documentation安装 ark-documentation设置指南 ark-documentation替代品 ark-documentation vs 其他工具 Provider-agnostic operations for agentic resources. ARK codifies patterns and practices developed across dozens of agentic application projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Yorick-Ryu/deep-share/md2docx', 'community', 'Yorick-Ryu', 'deep-share', 'Yorick-Ryu/deep-share', 'md2docx', 0, 0, 57, '2026-03-04T13:07:01.679Z', '2026-03-04T13:24:28.195Z', 'c04d36aefba9d7d16d477ad972d3955d7954cf10c80da3be6ec8de873d1afdbb', '{"id":"Yorick-Ryu/deep-share/md2docx","name":"md2docx","description":{"zh":"md2docx是一个轻量级的浏览器扩展，支持从多个AI对话中导出Word文档","ja":"md2docxは、複数のAI会話からWord文書をエクスポートする軽量ブラウザーエクステンション","ko":"md2docx는 여러 개의 AI 대화에서 워드 문서를 내보낼 수 있는 경량 브라우저 확장 프로그램","es":"md2docx es una extensión para copiar fórmulas de conversaciones de AI y exportar a Word","fr":"md2docx est une extension pour copier des formules de conversations d''IA et exporter vers Word","de":"md2docx ist ein Add-on zum Kopieren von Formeln aus AI-Konversationen und Export in Word","pt":"O md2docx é uma ferramenta leve para exportar fórmulas de ferramentas de IA para documentos do Word. Ele suporta mais de 10 ferramentas de IA, incluindo ChatGPT e DeepSeek.","ru":"md2docx - это легкий инструмент для экспорта формул из ИИ Агентов в документы Word. Он поддерживает более 10 ИИ Агентов, включая ChatGPT и DeepSeek.","ar":"md2docx هو أداة خفيفة لتصدير الصيغ من أدوات الذكاء الاصطناعي إلى مستندات Word. وهو يدعم أكثر من 10 أداة ذكاء اصطناعي، بما في ذلك ChatGPT و DeepSeek.","en":"A lightweight browser extension designed for AI users to easily copy formulas from ChatGPT, DeepSeek, Grok and 10+ other AI conversations, export beautifully formatted Word documents, and support long conversation screenshot sharing for DeepSeek."},"seo":{"title":{"zh":"AI工具md2docx：轻松导出Word文档","ja":"AIエージェントmd2docx：美しいWord文書を簡単に作成","ko":"AI 에이전트 md2docx: 워드 문서를 쉽게 내보내기","es":"Herramientas de AI: md2docx para documentos de Word","fr":"Outils d''IA: md2docx pour documents Word","de":"KI-Tools: md2docx für Word-Dokumente","pt":"md2docx: Ferramenta de Exportação de Documentos para Ferr...","ru":"md2docx: Инструмент для экспорта документов для ИИ Агентов","ar":"md2docx: أداة لتصدير المستندات لأدوات الذكاء الاصطناعي","en":"md2docx"},"description":{"zh":"md2docx是一个轻量级的浏览器扩展，支持从多个AI对话中导出Word文档","ja":"md2docxは、複数のAI会話からWord文書をエクスポートする軽量ブラウザーエクステンション","ko":"md2docx는 여러 개의 AI 대화에서 워드 문서를 내보낼 수 있는 경량 브라우저 확장 프로그램","es":"md2docx es una extensión para copiar fórmulas de conversaciones de AI y exportar a Word","fr":"md2docx est une extension pour copier des formules de conversations d''IA et exporter vers Word","de":"md2docx ist ein Add-on zum Kopieren von Formeln aus AI-Konversationen und Export in Word","pt":"O md2docx é uma ferramenta leve para exportar fórmulas de ferramentas de IA para documentos do Word. Ele suporta mais de 10 ferramentas de IA, incluindo Chat...","ru":"md2docx - это легкий инструмент для экспорта формул из ИИ Агентов в документы Word. Он поддерживает более 10 ИИ Агентов, включая ChatGPT и DeepSeek.","ar":"md2docx هو أداة خفيفة لتصدير الصيغ من أدوات الذكاء الاصطناعي إلى مستندات Word. وهو يدعم أكثر من 10 أداة ذكاء اصطناعي، بما في ذلك ChatGPT و DeepSeek.","en":"A lightweight browser extension designed for AI users to easily copy formulas from ChatGPT, DeepSeek, Grok and 10+ other AI conversations, export beautifully..."},"definition":{"en":"A lightweight browser extension designed for AI users to easily copy formulas from ChatGPT, DeepSeek, Grok and 10+ other AI conversations, export beautifully formatted Word documents, and support long conversation screenshot sharing for DeepSeek."},"features":{"zh":["轻松从ChatGPT、DeepSeek等AI对话中复制公式","导出美观的Word文档","支持长对话截图分享","支持10+个AI对话平台","轻量级浏览器扩展"],"ja":["ChatGPT、DeepSeekなどのAI会話から簡単に数式をコピー","美しいWord文書をエクスポート","長い会話のスクリーンショットを共有","10以上のAI会話プラットフォームをサポート","軽量ブラウザーエクステンション"],"ko":["ChatGPT, DeepSeek 등의 AI 대화에서 수식을 쉽게 복사","워드 문서를 내보내기","긴 대화의 스크린샷을 공유","10개 이상의 AI 대화 플랫폼을 지원","경량 브라우저 확장 프로그램"],"es":["Copiar fórmulas de ChatGPT y otros","Exportar a documentos de Word","Compatibilidad con conversaciones largas","Soporte para 10+ herramientas de AI","Extensión ligera y fácil de usar"],"fr":["Copier des formules de ChatGPT et autres","Exporter vers des documents Word","Compatibilité avec des conversations longues","Prise en charge de 10+ outils d''IA","Extension légère et facile à utiliser"],"de":["Formeln aus ChatGPT und anderen kopieren","Exportieren in Word-Dokumente","Kompatibilität mit langen Konversationen","Unterstützung für 10+ KI-Tools","Leichtes und benutzerfreundliches Add-on"],"pt":["Exportação de fórmulas de ferramentas de IA","Suporte a mais de 10 ferramentas de IA","Exportação para documentos do Word","Compartilhamento de capturas de tela de conversas longas","Extensão leve para navegador"],"ru":["Экспорт формул из ИИ Агентов","Поддержка более 10 ИИ Агентов","Экспорт в документы Word","Обмен скриншотами длинных разговоров","Легкое расширение для браузера"],"ar":["تصدير الصيغ من أدوات الذكاء الاصطناعي","دعم أكثر من 10 أداة ذكاء اصطناعي","تصدير إلى مستندات Word","مشاركة لقطات شاشة للمحادثات الطويلة","ملحق خفيف للمتصفح"]},"keywords":{"zh":["AI工具","md2docx","Word文档导出","AI对话","ChatGPT","DeepSeek","如何使用md2docx","md2docx安装","md2docx教程"],"ja":["AIエージェント","md2docx","Word文書エクスポート","AI会話","ChatGPT","DeepSeek","md2docxの使い方","md2docxのインストール","md2docxのチュートリアル"],"ko":["AI 에이전트","md2docx","워드 문서 내보내기","AI 대화","ChatGPT","DeepSeek","md2docx 사용법","md2docx 설치","md2docx 튜토리얼"],"es":["herramientas de AI","md2docx","copiar fórmulas","exportar a Word","alternativas a ChatGPT","guía de instalación de md2docx","configuración de md2docx","uso de md2docx","qué es md2docx"],"fr":["outils d''IA","md2docx","copier des formules","exporter vers Word","alternatives à ChatGPT","guide d''installation de md2docx","configuration de md2docx","utilisation de md2docx","qu''est-ce que md2docx"],"de":["KI-Tools","md2docx","Formeln kopieren","Exportieren in Word","Alternativen zu ChatGPT","Installationsanleitung für md2docx","Konfiguration von md2docx","Verwendung von md2docx","was ist md2docx"],"pt":["ferramentas de IA","exportação de documentos","ChatGPT","DeepSeek","como usar md2docx","o que é md2docx","md2docx vs outras ferramentas","instalar md2docx","guia de configuração do md2docx"],"ru":["ИИ Агенты","экспорт документов","ChatGPT","DeepSeek","как использовать md2docx","что такое md2docx","md2docx vs другие инструменты","установить md2docx","руководство по настройке md2docx"],"ar":["أدوات الذكاء الاصطناعي","تصدير المستندات","ChatGPT","DeepSeek","كيفية استخدام md2docx","ما هو md2docx","md2docx مقابل أدوات أخرى","تثبيت md2docx","دليل إعداد md2docx"]}},"owner":"Yorick-Ryu","repo":"deep-share","repoPath":"Yorick-Ryu/deep-share","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.679Z","topics":[],"category":"community","skillMd":{"name":"md2docx","description":"Convert Markdown to Word (DOCX) documents. Use when user wants to export, convert, or create Word documents from Markdown content.","bodyPreview":"# md2docx - Markdown to Word Converter\n\nConvert Markdown text to professionally formatted Word (DOCX) documents.\n\n## Quick Start\n\n**Choose the right mode based on your environment**:\n\n```bash\n# URL mode: Returns download URL (for cloud/remote environments)\npython scripts/convert.py input.md --url\n\n# File mode: Saves file directly (for local environments)\npython scripts/convert.py input.md --file\n```\n\n## Choosing the Right Mode\n\n| Scenario | Mode | Command |\n|----------|------|---------|\n| Skill","body":"# md2docx - Markdown to Word Converter\n\nConvert Markdown text to professionally formatted Word (DOCX) documents.\n\n## Quick Start\n\n**Choose the right mode based on your environment**:\n\n```bash\n# URL mode: Returns download URL (for cloud/remote environments)\npython scripts/convert.py input.md --url\n\n# File mode: Saves file directly (for local environments)\npython scripts/convert.py input.md --file\n```\n\n## Choosing the Right Mode\n\n| Scenario | Mode | Command |\n|----------|------|---------|\n| Skill runs in cloud, user needs to download | `--url` | `python scripts/convert.py input.md --url` |\n| Skill runs locally, user wants file saved | `--file` | `python scripts/convert.py input.md --file` |\n| Remote execution (MCP, API, cloud agent) | `--url` | Returns URL for user to download |\n| Local execution (user''s machine) | `--file` | Saves .docx directly to disk |\n\n**Decision Rule**:\n- **Use `--url`** when the skill runs in a different environment than the user (cloud, remote server, MCP server)\n- **Use `--file`** when the skill runs on the same machine where the user wants the output file\n\n## How It Works\n\n1. **Prepare Markdown**: Ensure content is in standard Markdown format\n2. **Run Script**: Execute `scripts/convert.py` with appropriate mode\n3. **Get Result**: \n   - URL mode: Receive download URL\n   - File mode: File saved to specified location\n\n## API Details\n\n**Endpoints**:\n- URL mode: `https://api.deepshare.app/convert-text-to-url` → Returns `{\"url\": \"...\"}`\n- File mode: `https://api.deepshare.app/convert-text` → Returns DOCX file directly\n\n**Authentication**: Include header `X-API-Key: {api_key}`\n\n### API Key Configuration\n\nYou can configure the API key in three ways:\n\n1. **Environment Variable** (Highest Priority)\n   ```bash\n   export DEEP_SHARE_API_KEY=\"your_api_key_here\"\n   ```\n\n2. **Skill Variable** (Medium Priority)\n   Edit the `api_key` field in the YAML frontmatter of this Skill file:\n   ```yaml\n   ---\n   name: md2docx\n   api_key: \"your_api_key_here\"\n   ---\n   ```\n\n3. **Trial Key** (Fallback): `f4e8fe6f-e39e-486f-b7e7-e037d2ec216f`\n\n**Priority Order**:\n1. Environment variable `DEEP_SHARE_API_KEY` (if set)\n2. Skill''s `api_key` variable (if not empty)\n3. Trial key (limited quota)\n\n⚠️ **Trial Mode**: Limited quota. For stable production use, purchase at: https://ds.rick216.cn/purchase\n\n## Request Format\n\n```json\n{\n  \"content\": \"markdown text here\",\n  \"filename\": \"output\",\n  \"template_name\": \"templates\",\n  \"language\": \"zh\",\n  \"hard_line_breaks\": false,\n  \"remove_hr\": false\n}\n```\n\n## Parameters\n\n| Parameter | Default | Description |\n|-----------|---------|-------------|\n| `content` | required | Markdown text to convert |\n| `filename` | `\"output\"` | Output filename (without .docx) |\n| `template_name` | `\"templates\"` | Template: `templates`, `论文`, `article`, `thesis`, etc. |\n| `language` | `\"zh\"` | Template language: `zh` or `en` |\n| `hard_line_breaks` | `false` | Preserve single line breaks |\n| `remove_hr` | `false` | Remove horizontal rules |\n\n## Common Templates\n\n**Chinese** (`language: \"zh\"`):\n- `templates` - General purpose\n- `论文` - Academic paper\n- `论文-首行不缩进` - Paper without indent\n- `论文-标题加粗` - Paper with bold headings\n\n**English** (`language: \"en\"`):\n- `templates` - General purpose\n- `article` - Article/report style\n- `thesis` - Academic thesis\n\n## Conversion Script Usage\n\n### Command Line Options\n\n```bash\npython scripts/convert.py <input.md> [options]\n\nOptions:\n  --url              Return download URL (default if no mode specified)\n  --file             Save file directly to disk\n  --template, -t     Template name (default: templates)\n  --language, -l     Language: zh or en (default: zh)\n  --output, -o       Output directory for file mode\n  --api-key, -k      API key (optional)\n```\n\n### Examples\n\n```bash\n# URL mode (cloud/remote environments)\npython scripts/convert.py document.md --url\npython scripts/convert.py paper.md --url --template 论文 --language zh\n\n# File mode (local environments)\npython scripts/convert.py document.md --file\npython scripts/convert.py paper.md --file --output ./docs --template thesis --language en\n\n# With custom API key\npython scripts/convert.py doc.md --url --api-key your_key\n```\n\n## Validation Before Conversion\n\nEnsure Markdown content:\n- Headers use `#` syntax\n- Lists use `-` or `1.` syntax\n- Code blocks use triple backticks\n- Math formulas use `$...$` (inline) or `$$...$$` (block)\n- Images use publicly accessible URLs\n\n## Response Handling\n\n### URL Mode Response\n\n**Success** (200 OK):\n```json\n{\n  \"url\": \"https://flies.deepshare.app/mcp/hash/document_xxx.docx\"\n}\n```\n\n### File Mode Response\n\n**Success**: File saved to disk, path printed to stdout\n\n### Error Responses (Both Modes)\n\n- `401 Unauthorized` - Invalid API key\n- `403 Forbidden` - Quota exceeded → Purchase at https://ds.rick216.cn/purchase\n- `413 Payload Too Large` - Content exceeds 10MB\n- `500 Internal Server Error` - Service unavailable, retry\n\n## User Communication\n\n### On Success\n\nTell user:\n1. Conversion completed successfully\n2. **URL mode**: Provide the download URL\n3. **File mode**: Provide the file path where document was saved\n4. Check which API key was used:\n   - **If using environment variable or Skill variable**: No reminder needed\n   - **If using trial key**: Remind: \"⚠️ You''re using trial mode (limited quota). For stable production use, get your API key at: https://ds.rick216.cn/purchase\"\n\n### On Quota Exceeded\n\nTell user:\n1. Conversion failed: quota exceeded\n2. Purchase more credits at: https://ds.rick216.cn/purchase\n3. Or use another API key\n\n### On Other Errors\n\nTell user:\n1. What went wrong (based on error message)\n2. How to fix it\n3. Offer to retry\n\n## Tips\n\n- **API Key Configuration**:\n  - **Option 1 (Recommended)**: Set environment variable `DEEP_SHARE_API_KEY`\n    ```bash\n    export DEEP_SHARE_API_KEY=\"your_api_key_here\"\n    ```\n  - **Option 2**: Edit `api_key` in this Skill''s YAML frontmatter\n  - **Option 3**: Use trial key (limited quota)\n- **File Size**: Keep Markdown under 10MB\n- **Images**: Use `https://` URLs, not local paths\n- **Math**: Use LaTeX syntax: `$E=mc^2$` or `$$\\int_0^\\infty$$`\n- **Line Breaks**: Use `hard_line_breaks: true` for addresses, poetry\n- **Templates**: Choose based on document type (paper, article, etc.)\n\n## Example Workflows\n\n### Workflow 1: Cloud Environment (URL Mode)\n\n**User asks**: \"Convert this to Word\" (skill running in cloud)\n\n1. Save the Markdown content to a temporary file (e.g., `temp.md`)\n\n2. Run the conversion script with URL mode:\n   ```bash\n   python scripts/convert.py temp.md --url\n   ```\n\n3. The script will:\n   - Select API key by priority (env → skill → trial)\n   - Call the conversion API\n   - Return download URL\n\n4. Provide the download URL to user\n\n5. Clean up temporary file\n\n### Workflow 2: Local Environment (File Mode)\n\n**User asks**: \"Convert my notes.md to Word\" (skill running locally)\n\n1. Run the conversion script with file mode:\n   ```bash\n   python scripts/convert.py notes.md --file --output ./output\n   ```\n\n2. The script will:\n   - Select API key by priority (env → skill → trial)\n   - Call the conversion API\n   - Save the DOCX file directly\n\n3. Tell user where the file was saved\n\n4. No cleanup needed - file is the output\n"},"lastSynced":"2026-03-04T13:24:28.195Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing seamless Markdown to DOCX conversion for reporting and documentation purposes.","zh":"适用于需要无缝将 Markdown 转换为 DOCX 的 AI 代理，以用于报告和文档目的。","ja":"AI エージェントがレポートやドキュメントの目的で Markdown を DOCX に無邪気に変換する必要がある場合に最適です。","ko":"보고서 및 문서 목적으로 마크다운을 DOCX로 무결점으로 변환해야 하는 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan una conversión perfecta de Markdown a DOCX para fines de informes y documentación.","fr":"Parfait pour les agents IA ayant besoin d''une conversion fluide de Markdown en DOCX pour les rapports et les fins de documentation.","de":"Perfekt für KI-Agents, die eine nahtlose Konvertierung von Markdown in DOCX für Berichte und Dokumentationszwecke benötigen.","pt":"Perfeito para Agentes de IA que precisam de conversão sem problemas de Markdown para DOCX para fins de relatórios e documentação.","ru":"Идеально подходит для агентов ИИ, которым требуется бесшовное преобразование Markdown в DOCX для отчетов и целей документации.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى تحويل Markdown إلى DOCX بسلاسة لأغراض التقرير والتوثيق."},"recommendation":{"en":"Empowers agents to convert Markdown text into professionally formatted Word documents using Python, supporting both local and cloud environments through URL and file modes, and handling Markdown to DOCX conversion with ease.","zh":"通过 Python 实现将 Markdown 文本转换为专业格式的 Word 文档的功能，支持本地和云环境，通过 URL 和文件模式，并轻松处理 Markdown 到 DOCX 的转换。","ja":"Python を使用して、エージェントが Markdown テキストをプロフェッショナルに整形式の Word ドキュメントに変換できるようにし、ローカルおよびクラウド環境をサポートし、URL およびファイルモードを介して、Markdown から DOCX への変換を容易に行うことができます。","ko":"파이썬을 사용하여 에이전트가 마크다운 텍스트를 전문적으로 형식화된 워드 문서로 변환할 수 있도록 하며, 로컬 및 클라우드 환경을 지원하며, URL 및 파일 모드를 통해 마크다운에서 DOCX로의 변환을 쉽게 처리합니다.","es":"Habilita a los agentes a convertir texto Markdown en documentos Word profesionalmente formateados utilizando Python, y soporta tanto entornos locales como de nube a través de URL y modos de archivo, y maneja la conversión de Markdown a DOCX con facilidad.","fr":"Permet aux agents de convertir du texte Markdown en des documents Word formatés professionnellement en utilisant Python, et prend en charge à la fois les environnements locaux et cloud via les modes URL et fichier, et gère avec facilité la conversion de Markdown en DOCX.","de":"Ermächtigt Agents, Markdown-Text in professionell formatierte Word-Dokumente mithilfe von Python zu konvertieren, und unterstützt sowohl lokale als auch Cloud-Umgebungen durch URL- und Dateimodi, und handhabt die Konvertierung von Markdown in DOCX mühelos.","pt":"Habilita os agentes a converter texto Markdown em documentos do Word profissionalmente formatados usando Python, suportando ambos os ambientes local e na nuvem por meio de URL e modos de arquivo, e lidando com a conversão Markdown para DOCX com facilidade.","ru":"Наделяет агентов возможностью преобразовывать текст Markdown в профессионально отформатированные документы Word, используя Python, поддерживая как локальные, так и облачные среды через URL и файловые режимы, и легко обрабатывая преобразование Markdown в DOCX.","ar":"يعزز الوكلاء لتحويل نص Markdown إلى مستندات Word معدة بشكل احترافي باستخدام Python ، ودعم كل من البيئات المحلية والسحابية من خلال URL ووضع الملفات ، ومعالجة تحويل Markdown إلى DOCX بسهولة."},"useCases":{"en":["Converting AI-generated Markdown content into DOCX reports","Generating beautifully formatted Word documents from Markdown text","Streamlining document creation workflows using Markdown to DOCX conversion"],"zh":["将 AI 生成的 Markdown 内容转换为 DOCX 报告","从 Markdown 文本生成漂亮的 Word 文档","使用 Markdown 到 DOCX 转换来简化文档创建工作流"],"ja":["AI によって生成された Markdown コンテンツを DOCX レポートに変換する","Markdown テキストから美しく整形式の Word ドキュメントを生成する","Markdown から DOCX への変換を使用してドキュメント作成のワークフローを合理化する"],"ko":["AI가 생성한 마크다운 콘텐츠를 DOCX 보고서로 변환하는 것","마크다운 텍스트에서 아름답게 형식화된 워드 문서를 생성하는 것","마크다운에서 DOCX로의 변환을 사용하여 문서 생성 워크플로우를 최적화하는 것"],"es":["Convertir contenido Markdown generado por IA en informes DOCX","Generar documentos Word bellamente formateados a partir de texto Markdown","Optimizar flujos de trabajo de creación de documentos mediante la conversión de Markdown a DOCX"],"fr":["Convertir du contenu Markdown généré par IA en rapports DOCX","Générer des documents Word formatés de manière élégante à partir de texte Markdown","Optimiser les flux de travail de création de documents en utilisant la conversion de Markdown en DOCX"],"de":["AI-generierten Markdown-Inhalt in DOCX-Berichte konvertieren","Schön formatierte Word-Dokumente aus Markdown-Text generieren","Dokumenterstellungswerkflüsse durch die Konvertierung von Markdown in DOCX optimieren"],"pt":["Conversão de conteúdo Markdown gerado por IA em relatórios DOCX","Geração de documentos Word formatados de forma bonita a partir de texto Markdown","Otimização dos fluxos de trabalho de criação de documentos usando a conversão Markdown para DOCX"],"ru":["Преобразование markdown-контента, сгенерированного ИИ, в отчеты DOCX","Генерация красиво оформленных документов Word из текста Markdown","Оптимизация рабочих процессов создания документов с помощью преобразования Markdown в DOCX"],"ar":["تحويل المحتوى Markdown الذي تم إنشاؤه بواسطة الذكاء الاصطناعي إلى تقارير DOCX","إنشاء مستندات Word معدة بشكل جميل من نص Markdown","تبسيط تدفقات عمل إنشاء المستندات باستخدام تحويل Markdown إلى DOCX"]},"limitations":{"en":["Requires Python environment","Limited to Markdown to DOCX conversion","Dependent on specific command-line arguments for mode selection (URL or file)"],"zh":["需要 Python 环境","仅限 Markdown 到 DOCX 转换","需要特定的命令行参数来选择模式（URL 或文件）"],"ja":["Python 環境が必要","Markdown から DOCX への変換のみ","モードの選択（URL またはファイル）には特定のコマンドライン引数が必要"],"ko":["파이썬 환경이 필요함","마크다운에서 DOCX로의 변환만 가능","모드 선택(URL 또는 파일)을 위해 특정 명령줄 인수가 필요함"],"es":["Requiere entorno Python","Limitado a la conversión de Markdown a DOCX","Dependiente de argumentos de línea de comandos específicos para la selección del modo (URL o archivo)"],"fr":["Nécessite un environnement Python","Limité à la conversion de Markdown en DOCX","Dépend de arguments de ligne de commande spécifiques pour la sélection du mode (URL ou fichier)"],"de":["Benötigt Python-Umgebung","Begrenzt auf die Konvertierung von Markdown in DOCX","Abhängig von spezifischen Befehlszeilenargumenten für die Modusaufwahl (URL oder Datei)"],"pt":["Exige ambiente Python","Limitado à conversão Markdown para DOCX","Dependente de argumentos de linha de comando específicos para seleção de modo (URL ou arquivo)"],"ru":["Требуется среда Python","Ограничен преобразованием Markdown в DOCX","Зависит от конкретных аргументов командной строки для выбора режима (URL или файл)"],"ar":["يتطلب بيئة Python","محدود بالتحويل من Markdown إلى DOCX","يعتمد على حجة سطر الأوامر المحددة لاختيار الوضع (URL أو ملف)"]},"version":3},"contentHash":"c04d36aefba9d7d16d477ad972d3955d7954cf10c80da3be6ec8de873d1afdbb","qualityScore":57}');
