INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Yorick-Ryu/deep-share/md2docx', 'md2docx', 'Yorick-Ryu', 'deep-share', 'community', 'md2docx Yorick-Ryu deep-share community md2docx是一个轻量级的浏览器扩展，支持从多个AI对话中导出Word文档 md2docxは、複数のAI会話からWord文書をエクスポートする軽量ブラウザーエクステンション md2docx는 여러 개의 AI 대화에서 워드 문서를 내보낼 수 있는 경량 브라우저 확장 프로그램 md2docx es una extensión para copiar fórmulas de conversaciones de AI y exportar a Word md2docx est une extension pour copier des formules de conversations d''IA et exporter vers Word md2docx ist ein Add-on zum Kopieren von Formeln aus AI-Konversationen und Export in Word O md2docx é uma ferramenta leve para exportar fórmulas de ferramentas de IA para documentos do Word. Ele suporta mais de 10 ferramentas de IA, incluindo ChatGPT e DeepSeek. md2docx - это легкий инструмент для экспорта формул из ИИ Агентов в документы Word. Он поддерживает более 10 ИИ Агентов, включая ChatGPT и DeepSeek. md2docx هو أداة خفيفة لتصدير الصيغ من أدوات الذكاء الاصطناعي إلى مستندات Word. وهو يدعم أكثر من 10 أداة ذكاء اصطناعي، بما في ذلك ChatGPT و DeepSeek. A lightweight browser extension designed for AI users to easily copy formulas from ChatGPT, DeepSeek, Grok and 10+ other AI conversations, export beautifully formatted Word documents, and support long conversation screenshot sharing for DeepSeek. AI工具 md2docx Word文档导出 AI对话 ChatGPT DeepSeek 如何使用md2docx md2docx安装 md2docx教程 A lightweight browser extension designed for AI users to easily copy formulas from ChatGPT, DeepSeek, Grok and 10+ other AI conversations, export beautifully formatted Word documents, and support long conversation screenshot sharing for DeepSeek.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ArtemXTech/claude-code-obsidian-starter/granola', 'community', 'ArtemXTech', 'claude-code-obsidian-starter', 'ArtemXTech/claude-code-obsidian-starter', 'granola', 0, 0, 57, '2026-03-04T13:07:01.680Z', '2026-03-04T13:24:32.202Z', 'cead22e3f9c08b4787b92dbf9c849c42763952c83615c778e0ebe5ebf0b8e71d', '{"id":"ArtemXTech/claude-code-obsidian-starter/granola","name":"granola","description":{"zh":"granola免费入门套件，包含Claude Code和Obsidian的预配置vault，用于项目、任务、客户和日常例行程序","ja":"granolaスターター キットは、Claude CodeとObsidianのプリコンフィグされたボールトを含み、プロジェクト、タスク、クライアント、日常ルーティーンに使用されます","ko":"그라놀라 무료 스타터 키트에는 클라우드 코드와 옵시디언의 사전 구성된 보geç이 포함되어 있으며 프로젝트, 작업, 클라이언트 및 일일 루틴에 사용됩니다","es":"El kit de granola es un conjunto de herramientas de inteligencia artificial preconfiguradas para proyectos y tareas","fr":"Le kit granola est un ensemble d''outils d''intelligence artificielle préconfigurés pour les projets et les tâches","de":"Das Granola-Kit ist ein Satz von KI-Tools, die für Projekte und Aufgaben vorkonfiguriert sind","pt":"O kit de início Granola oferece uma solução pré-configurada para projetos, tarefas, clientes e rotinas diárias com Claude Code e Obsidian.","ru":"Набор для начала Granola предоставляет преднастроенное решение для проектов, задач, клиентов и ежедневных рутин с помощью Claude Code и Obsidian.","ar":"كيت بدء گرنولا يقدم حلًا مسبقًا للتكوين لمشاريع، مهام، عملاء ورو틴 يومية مع كلود كود وأوبسيديان.","en":"Free starter kit: Claude Code + Obsidian. Pre-configured vault with skills for projects, tasks, clients, and daily routines. Just open and go."},"seo":{"title":{"zh":"AI智能工具：granola免费入门套件","ja":"AIエージェント：granolaスターター キット","ko":"AI 에이전트: granola 무료 스타터 키트","es":"Herramientas de Inteligencia Artificial: Kit de granola","fr":"Outils d''Intelligence Artificielle: Kit granola","de":"KI-Tools: Granola-Kit","pt":"Kit de Início de Ferrament