INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('renocrypt/latex-arxiv-SKILL/arxiv-paper-writer', 'arxiv-paper-writer', 'renocrypt', 'latex-arxiv-SKILL', 'community', 'arxiv-paper-writer renocrypt latex-arxiv-SKILL community arxiv-paper-writer是一个用于创建和验证LaTeX论文和BibTeX引用的AI工具，帮助研究人员提高效率 arxiv-paper-writerは、LaTeX論文とBibTeX引用を作成して検証するためのAIエージェントです arxiv-paper-writer는 LaTeX 논문과 BibTeX 참조를 작성하고 검증하기 위한 AI 에이전트입니다 El skill arxiv-paper-writer es una herramienta de AI para crear papers de revisión de ML/AI con LaTeX y citas BibTeX verificadas Le skill arxiv-paper-writer est un outil d''IA pour créer des articles de revue de ML/IA avec LaTeX et citations BibTeX vérifiées Der arxiv-paper-writer-Skill ist ein KI-Tool für die Erstellung von ML/KI-Überprüfungsartikeln mit LaTeX und verifizierten BibTeX-Zitaten O arxiv-paper-writer é uma ferramenta de IA para criar artigos de revisão com LaTeX e citações BibTeX verificadas ИИ Агент arxiv-paper-writer предназначен для создания статей обзора с помощью LaTeX и проверки цитат BibTeX أداة arxiv-paper-writer هي أداة ذكاء اصطناعي لكتابة الأبحاث باستخدام LaTeX ومراجعة المراجع BibTeX A .codex SKILL for issue-driven ML/AI arXiv review papers: scaffold LaTeX + verify BibTeX citations end-to-end. 如何使用arxiv-paper-writer 什么是LaTeX论文 BibTeX引用验证工具 arxiv-paper-writer安装指南 LaTeX论文写作技巧 arxiv-paper-writer和其他工具的比较 研究论文写作工具 AI工具在研究中的应用 A .codex SKILL for issue-driven ML/AI arXiv review papers: scaffold LaTeX + verify BibTeX citations end-to-end.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('InterCooperative-Network/icn/icn-gateway-openapi-sync', 'community', 'InterCooperative-Network', 'icn', 'InterCooperative-Network/icn', 'icn-gateway-openapi-sync', 0, 0, 57, '2026-03-04T13:07:01.747Z', '2026-03-04T14:10:03.425Z', '76136cfe64e19b332101f151593bcbd492e61634b1c27e76d9c98e2c03abc473', '{"id":"InterCooperative-Network/icn/icn-gateway-openapi-sync","name":"icn-gateway-openapi-sync","description":{"zh":"icn-gateway-openapi-sync 是一个用于合作互联网的基质守护进程，实现应用程序将治理转换为通用约束","ja":"icn-gateway-openapi-sync は協力的なインターネットのためのサブストレートデーモン、コアが盲目的に強制する一般的な制約へのガバナンスの翻訳","ko":"icn-gateway-openapi-sync는 협력 인터넷을 위한 기질 데몬으로, 애플리케이션이 거버넌스를 일반적인 제약 조건으로 변환","es":"icn-gateway-openapi-sync es un daemon de substrato que traduce la gobernanza en restricciones genéricas para el internet cooperativo","fr":"icn-gateway-openapi-sync est un daemon de substrat qui traduit la gouvernance en contraintes génériques pour l''internet coopératif","de":"icn-gateway-openapi-sync ist ein Substrat-Daemon, der die Governance in generische Einschränkungen für das kooperative Internet übersetzt","pt":"O icn-gateway-openapi-sync é um daemon de substrate que traduz governança em restrições genéricas, permitindo que aplicativos cooperem na internet","ru":"Иcn-gateway-openapi-sync - это демон субстрата, переводящий управление в общие ограничения, позволяя приложениям работать вместе в интернете","ar":"icn-gateway-openapi-sync هو ديمون सबستريت يترجم الحوكمة إلى قيود عامة، مما يسمح للتطبيقات بالتعاون على الإنترنت","en":"A substrate daemon for the cooperative internet. Constraint engine where apps translate governance into generic constraints, kernel enforces them blindly."},"seo":{"title":{"zh":"AI智能代理 icn-gateway-openapi-sync","ja":"AIエージェント icn-gateway-openapi-sync","ko":"AI 에이전트 icn-gateway-openapi-sync","es":"Herramientas de AI: icn-gateway-openapi