INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('InterCooperative-Network/icn/icn-gateway-openapi-sync', 'icn-gateway-openapi-sync', 'InterCooperative-Network', 'icn', 'community', 'icn-gateway-openapi-sync InterCooperative-Network icn community icn-gateway-openapi-sync 是一个用于合作互联网的基质守护进程，实现应用程序将治理转换为通用约束 icn-gateway-openapi-sync は協力的なインターネットのためのサブストレートデーモン、コアが盲目的に強制する一般的な制約へのガバナンスの翻訳 icn-gateway-openapi-sync는 협력 인터넷을 위한 기질 데몬으로, 애플리케이션이 거버넌스를 일반적인 제약 조건으로 변환 icn-gateway-openapi-sync es un daemon de substrato que traduce la gobernanza en restricciones genéricas para el internet cooperativo icn-gateway-openapi-sync est un daemon de substrat qui traduit la gouvernance en contraintes génériques pour l''internet coopératif icn-gateway-openapi-sync ist ein Substrat-Daemon, der die Governance in generische Einschränkungen für das kooperative Internet übersetzt O icn-gateway-openapi-sync é um daemon de substrate que traduz governança em restrições genéricas, permitindo que aplicativos cooperem na internet Иcn-gateway-openapi-sync - это демон субстрата, переводящий управление в общие ограничения, позволяя приложениям работать вместе в интернете icn-gateway-openapi-sync هو ديمون सबستريت يترجم الحوكمة إلى قيود عامة، مما يسمح للتطبيقات بالتعاون على الإنترنت A substrate daemon for the cooperative internet. Constraint engine where apps translate governance into generic constraints, kernel enforces them blindly. AI智能代理 icn-gateway-openapi-sync 基质守护进程 应用程序治理转换 通用约束 合作互联网 如何使用icn-gateway-openapi-sync icn-gateway-openapi-sync安装 icn-gateway-openapi-sync设置指南 A substrate daemon for the cooperative internet. Constraint engine where apps translate governance into generic constraints, kernel enforces them blindly.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fxstein/ai-todo/branch-cleanup', 'community', 'fxstein', 'ai-todo', 'fxstein/ai-todo', 'branch-cleanup', 0, 0, 57, '2026-03-04T13:07:01.797Z', '2026-03-04T14:28:39.442Z', '7be9f4d7a88cebc33d766eb25e02b1693351e182240c29e32959779358cb1cdc', '{"id":"fxstein/ai-todo/branch-cleanup","name":"branch-cleanup","description":{"zh":"AI-native任务管理，适用于OpenClaw、Cursor、Claude和Copilot等AI智能代理，实现持久、版本控制的TODO跟踪","ja":"AIエージェント用のネイティブタスク管理、OpenClaw、Cursor、Claude、CopilotなどのAIエージェントとシームレスに動作","ko":"AI 에이전트용 네이티브 태스크 관리, OpenClaw, Cursor, Claude, Copilot 등의 AI 에이전트와 자연스럽게 동작","es":"Gestión de tareas nativa de IA para agentes de codificación con seguimiento de TODO persistente y control de versiones","fr":"Gestion de tâches native IA pour les agents de codage avec suivi de TODO persistant et contrôle de version","de":"KI-native Aufgabenverwaltung für Codierungsagenten mit persistentem TODO-Tracking und Versionskontrolle","pt":"O branch-cleanup é uma ferramenta de gerenciamento de tarefas de codificação para agentes de IA, como OpenClaw, Cursor, Claude e Copilot.","ru":"Branch-cleanup - это инструмент управления задачами кодирования для ИИ агентов, таких как OpenClaw, Cursor, Claude и Copilot.","ar":"branch-cleanup هو أداة لإدارة مهام التشفير لوكلاء الذكاء الاصطناعي مثل OpenClaw و Cursor و Claude و Copilot.","en":"AI-native task management for coding agents - Persistent, version-controlled TODO tracking that works naturally with AI agents like OpenClaw, Cursor, Claude, and Copilot"},"seo":{"title":{"zh":"代码智能清理：AI智能代理任务管理","ja":"コード整理：AIエージェントのタスク管理","ko":"코드 정리: AI 에이전트 태스크 관리","es":"Limpieza de ramas para Agentes de IA","fr":"Nettoyage de branches pour Agents IA","de":"Branchenreinigung für KI-Agents","pt":"Limpeza de Ramo com Agente de IA","ru":"Очистка Веток с ИИ Агентами","ar":"تنظيف الفرع مع وكلاء الذكاء الاصطناعي","en":"branch-cleanup"},"description":{"zh":"AI-native任务管理，适用于OpenClaw、Cursor、Claude和Copilot等AI智能代理，实现持久、版本控制的TODO跟踪","ja":"AIエージェント用のネイティブタスク管理、OpenClaw、Cursor、Claude、CopilotなどのAIエージェントとシームレスに動作","ko":"AI 에이전트용 네이티브 태스크 관리, OpenClaw, Cursor, Claude, Copilot 등의 AI 에이전트와 자연스럽게 동작","es":"Gestión de tareas nativa de IA para agentes de codificación con seguimiento de TODO persistente y control de versiones","fr":"Gestion de tâches native IA pour les agents de codage avec suivi de TODO persistant et contrôle de version","de":"KI-native Aufgabenverwaltung für Codierungsagenten mit persistentem TODO-Tracking und Versionskontrolle","pt":"O branch-cleanup é uma ferramenta de gerenciamento de tarefas de codificação para agentes de IA, como OpenClaw, Cursor, Claude e Copilot.","ru":"Branch-cleanup - это инструмент управления задачами кодирования для ИИ агентов, таких как OpenClaw, Cursor, Claude и Copilot.","ar":"branch-cleanup هو أداة لإدارة مهام التشفير لوكلاء الذكاء الاصطناعي مثل OpenClaw و Cursor و Claude و Copilot.","en":"AI-native task management for coding agents - Persistent, version-controlled TODO tracking that works naturally with AI agents like OpenClaw, Cursor, Claude,..."},"definition":{"en":"AI-native task management for coding agents - Persistent, version-controlled TODO tracking that works naturally with AI agents like OpenClaw, Cursor, Claude, and Copilot"},"features":{"zh":["持久、版本控制的TODO跟踪","适用于OpenClaw、Cursor、Claude和Copilot等AI智能代理","实现AI-native任务管理","支持多种编程语言","提供代码管理和优化建议"],"ja":["永続的なバージョン管理されたTODOの追跡","OpenClaw、Cursor、Claude、CopilotなどのAIエージェントとシームレスに動作","AIエージェント用のネイティブタスク管理","複数のプログラミング言語をサポート","コード管理と最適化の提案を提供"],"ko":["지속적이고 버전 관리 된 TODO 추적","OpenClaw, Cursor, Claude, Copilot 등의 AI 에이전트와 자연스럽게 동작","AI 에이전트용 네이티브 태스크 관리","다중 프로그래밍 언어 지원","코드 관리와 최적화 제안 제공"],"es":["Seguimiento de TODO persistente","Control de versiones integrado","Compatibilidad con Agentes de IA como OpenClaw y Copilot","Gestión de tareas nativa de IA","Integración con herramientas de desarrollo"],"fr":["Suivi de TODO persistant","Contrôle de version intégré","Compatibilité avec les Agents IA comme OpenClaw et Copilot","Gestion de tâches native IA","Intégration avec les outils de développement"],"de":["Persistentes TODO-Tracking","Integrierte Versionskontrolle","Kompatibilität mit KI-Agents wie OpenClaw und Copilot","KI-native Aufgabenverwaltung","Integration mit Entwicklungstools"],"pt":["Rastreamento de TODO persistente","Controle de versão","Integração com agentes de IA","Gerenciamento de tarefas de codificação","Suporte a OpenClaw, Cursor, Claude e Copilot"],"ru":["Постоянный TODO-трекинг","Версионный контроль","Интеграция с ИИ агентами","Управление задачами кодирования","Поддержка OpenClaw, Cursor, Claude и Copilot"],"ar":["تتبع TODO مدى الحياة","مراقبة الإصدار","التكامل مع وكلاء الذكاء الاصطناعي","إدارة مهام التشفير","دعم OpenClaw و Cursor و Claude و Copilot"]},"keywords":{"zh":["AI智能代理","代码管理","TODO跟踪","版本控制","OpenClaw","Cursor","Claude","Copilot","如何使用AI智能代理","AI智能代理安装指南"],"ja":["AIエージェント","コード管理","TODOの追跡","バージョン管理","OpenClaw","Cursor","Claude","Copilot","AIエージェントの使い方","AIエージェントのインストールガイド"],"ko":["AI 에이전트","코드 관리","TODO 추적","버전 관리","OpenClaw","Cursor","Claude","Copilot","AI 에이전트 사용법","AI 에이전트 설치 가이드"],"es":["cómo usar Agentes de IA","qué es la limpieza de ramas","alternativa a OpenClaw","Copilot vs OpenClaw","instalación de Agentes de IA","guía de configuración de Copilot","desarrollo de software con Agentes de IA"],"fr":["comment utiliser les Agents IA","qu''est-ce que le nettoyage de branches","alternative à OpenClaw","Copilot vs OpenClaw","installation des Agents IA","guide de configuration de Copilot","développement de logiciels avec les Agents IA"],"de":["wie man KI-Agents verwendet","was ist die Branchenreinigung","Alternative zu OpenClaw","Copilot vs OpenClaw","Installation von KI-Agents","Einrichtungsanleitung für Copilot","Softwareentwicklung mit KI-Agents"],"pt":["como usar branch-cleanup","o que é branch-cleanup","alternativa para OpenClaw","branch-cleanup vs Copilot","instalar branch-cleanup","guia de configuração do branch-cleanup"],"ru":["как использовать branch-cleanup","что такое branch-cleanup","альтернатива OpenClaw","branch-cleanup vs Copilot","установка branch-cleanup","руководство по настройке branch-cleanup"],"ar":["كيفية استخدام branch-cleanup","ما هو branch-cleanup","بديل ل OpenClaw","branch-cleanup مقابل Copilot","تثبيت branch-cleanup","دليل إعداد branch-cleanup"]}},"owner":"fxstein","repo":"ai-todo","repoPath":"fxstein/ai-todo","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.797Z","topics":[],"category":"community","skillMd":{"name":"branch-cleanup","description":"Clean up local branches after PR merges. Syncs main with origin, identifies branches with merged PRs, and proposes safe deletion. Use when the user asks to clean up branches, delete merged branches, sync branches, or mentions branch cleanup.","bodyPreview":"# Branch Cleanup\n\nAutomated workflow to sync main with origin and clean up local branches that have merged PRs.\n\n## Quick Start\n\nWhen user asks to \"clean up branches\" or \"delete merged branches\":\n\n1. **Pre-flight checks:**\n   - `git fetch origin` (update remote refs)\n   - `git branch --show-current` (verify current branch)\n   - If not on main: **Ask user:** \"Should I switch to main? (Current: {branch})\"\n\n2. **Sync main:**\n   - `git checkout main`\n   - `git pull origin main --ff-only`\n   - **If c","body":"# Branch Cleanup\n\nAutomated workflow to sync main with origin and clean up local branches that have merged PRs.\n\n## Quick Start\n\nWhen user asks to \"clean up branches\" or \"delete merged branches\":\n\n1. **Pre-flight checks:**\n   - `git fetch origin` (update remote refs)\n   - `git branch --show-current` (verify current branch)\n   - If not on main: **Ask user:** \"Should I switch to main? (Current: {branch})\"\n\n2. **Sync main:**\n   - `git checkout main`\n   - `git pull origin main --ff-only`\n   - **If conflicts:** ⚠️ Stop and report \"Main has conflicts. Resolve manually.\"\n\n3. **List local branches:**\n   - `git branch --format=''%(refname:short)''`\n   - Filter out: `main`, `master`, `develop`, `staging`, `production`, `archive*`\n   - **If no branches:** Report \"No local branches to clean up\" and STOP.\n\n4. **Check PR status for each branch:**\n   - Get PR for branch: `gh pr list --head {branch} --state merged --json number,title,url`\n   - **If merged PR found:** Add to cleanup list\n   - **If no PR or not merged:** Skip\n\n5. **Present cleanup list:**\n   - Show table with: branch name, PR number, PR title, PR URL\n   - **Ask user:** \"Delete these {count} branches? (y/n)\"\n   - **If user declines:** STOP.\n\n6. **Delete branches:**\n   - For each approved branch:\n     - `git branch -d {branch}` (safe delete)\n     - **If fails with unmerged warning:** Show warning and skip\n     - **If succeeds:** Report \"✅ Deleted {branch}\"\n   - **Final summary:** \"Deleted {count} branches, skipped {count} unmerged branches\"\n\n## Workflow Details\n\n### Step 1: Pre-flight Checks\n\n```bash\n# Fetch latest remote refs\ngit fetch origin\n\n# Check current branch\nCURRENT_BRANCH=$(git branch --show-current)\n```\n\n**If not on main:**\n- Show: \"Currently on `{CURRENT_BRANCH}`. Switch to main?\"\n- Wait for user confirmation\n\n**Safety:**\n- Never switch branches with uncommitted changes\n- Check: `git status --porcelain` (must be empty)\n\n### Step 2: Sync Main\n\n```bash\n# Switch to main\ngit checkout main\n\n# Fast-forward merge only (no conflicts)\ngit pull origin main --ff-only\n```\n\n**If fast-forward fails:**\n- ⚠️ Stop with error: \"Main branch has diverged from origin. Manual resolution required.\"\n- Do NOT attempt merge or rebase\n\n### Step 3: Identify Merged Branches\n\nFor each local branch:\n\n```bash\n# Get merged PR for branch\ngh pr list --head {branch} --state merged --json number,title,url --limit 1\n```\n\n**Branch categories:**\n\n| Status | Action |\n|--------|--------|\n| Merged PR found | Add to cleanup list |\n| Open PR found | Skip (not merged) |\n| No PR found | Skip (might be local work) |\n| Protected branch | Skip (main, master, etc.) |\n\n**Protected branches:**\n- `main`, `master`, `develop`, `staging`, `production`\n- Any branch starting with `archive` (e.g., `archive-2024`, `archive/old`)\n- Any branch matching `origin/*`\n\n### Step 4: Present Cleanup List\n\nFormat as markdown table:\n\n```markdown\n## Branches with merged PRs\n\n| Branch | PR | Title |\n|--------|-----|-------|\n| fxstein/AIT-12-feature | [#45](url) | Feature implementation |\n| oliver/ait-8-bugfix | [#38](url) | Fix login bug |\n\nTotal: 2 branches\n```\n\n**User prompt:**\n\"Delete these branches? They have merged PRs and are safe to remove. (y/n)\"\n\n### Step 5: Safe Deletion\n\n```bash\n# Safe delete (only if fully merged)\ngit branch -d {branch}\n```\n\n**If `git branch -d` fails:**\n- Shows: \"The branch ''{branch}'' is not fully merged.\"\n- **Action:** Skip and report to user\n- **Reason:** Prevents data loss\n\n**Force delete (`-D`) is NEVER used automatically.**\n\n## Edge Cases\n\n### No Merged Branches\n\nIf no branches qualify for cleanup:\n```\n✅ All local branches are up to date.\nNo merged branches found for cleanup.\n```\n\n### Partially Merged Branches\n\nIf branch has commits not in main but PR is merged:\n- `git branch -d` will fail (expected)\n- Report: \"⚠️ Skipped {branch}: has unmerged commits (possible rebase)\"\n- User can manually verify with: `git log main..{branch}`\n\n### Archive Branches\n\nBranches starting with `archive` are preserved:\n- ❌ Skip: `archive-2024`, `archive/backup`, `archive-old-features`\n- **Reason:** Archive branches contain historical work that should be manually managed\n\n### Remote Tracking Branches\n\nOnly delete **local** branches, never remote refs:\n- ✅ Delete: `fxstein/AIT-12-feature`\n- ❌ Skip: `origin/fxstein/AIT-12-feature`\n\nUse `git push origin --delete {branch}` only if user explicitly requests remote deletion.\n\n## Error Handling\n\n**If ANY error occurs:**\n1. STOP IMMEDIATELY\n2. Report the specific error\n3. Show current state: branch name, operation attempted\n4. WAIT for user input\n\n**Common errors:**\n\n| Error | Cause | Action |\n|-------|-------|--------|\n| \"Not on main\" | Current branch not main | Ask to switch |\n| \"Fast-forward failed\" | Main diverged from origin | Stop, manual resolution |\n| \"gh command not found\" | GitHub CLI not installed | Stop, ask user to install |\n| \"Branch not fully merged\" | Branch has unmerged commits | Skip branch |\n\n## Safety Guarantees\n\n- ✅ Never force-delete (`-D`) branches\n- ✅ Never delete without user confirmation\n- ✅ Never modify remote branches\n- ✅ Never switch branches with uncommitted changes\n- ✅ Always use `--ff-only` for main sync\n\n## Output Format\n\n### Success\n\n```\n🔄 Syncing main with origin...\n✅ Main is up to date\n\n📋 Found 3 branches with merged PRs:\n- fxstein/AIT-12-feature (PR #45)\n- oliver/ait-8-bugfix (PR #38)\n- fxstein/AIT-10-docs (PR #42)\n\n🗑️  Deleting branches...\n✅ Deleted fxstein/AIT-12-feature\n✅ Deleted oliver/ait-8-bugfix\n✅ Deleted fxstein/AIT-10-docs\n\n✨ Cleanup complete: 3 branches deleted\n```\n\n### With Skipped Branches\n\n```\n🗑️  Deleting branches...\n✅ Deleted fxstein/AIT-12-feature\n⚠️  Skipped fxstein/AIT-15-wip: not fully merged\n✅ Deleted oliver/ait-8-bugfix\n\n✨ Cleanup complete: 2 deleted, 1 skipped\n```\n\n## Additional Features\n\n### Dry Run Mode\n\nIf user asks for \"preview\" or \"dry run\":\n- Execute steps 1-4 only\n- Show cleanup list\n- STOP before deletion\n\n### Delete Remote Branches\n\nIf user explicitly asks to \"delete remote branches too\":\n- After local deletion succeeds\n- For each deleted branch:\n  ```bash\n  git push origin --delete {branch}\n  ```\n- Report: \"✅ Deleted {branch} (local + remote)\"\n\n## Requirements\n\n- **Git:** Version 2.0+\n- **GitHub CLI (gh):** Required for PR status checks\n- **Repository:** Must be a git repository with GitHub remote\n\n## Forbidden Actions\n\n- ❌ Never use `git branch -D` (force delete)\n- ❌ Never delete branches without user confirmation\n- ❌ Never modify `main`, `master`, or protected branches\n- ❌ Never attempt merge/rebase to resolve conflicts\n"},"lastSynced":"2026-03-04T14:28:39.442Z","agentAnalysis":{"suitability":{"en":"Perfect for Version Control Agents needing automated Git branch management and synchronization.","zh":"适合需要自动化Git分支管理和同步的版本控制代理。","ja":"バージョン管理エージェントが自動化されたGitブランチ管理と同期を必要とする場合に適しています。","ko":"자동화된 Git 브랜치 관리 및 동기화를 필요로 하는 버전 제어 에이전트에 적합합니다.","es":"Perfecto para Agentes de Control de Versiones que necesitan una gestión y sincronización automática de ramas Git.","fr":"Parfait pour les Agents de Contrôle de Version nécessitant une gestion et une synchronisation automatisées de branches Git.","de":"Perfekt für Version Control Agents, die eine automatisierte Git-Zweigverwaltung und -Synchronisierung benötigen.","pt":"Perfeito para Agentes de Controle de Versão que necessitam de gerenciamento e sincronização de branches Git automatizados.","ru":"Идеально подходит для агентов контроля версий, которым необходим автоматизированный менеджмент и синхронизация веток Git.","ar":"مثالي للوكلاء إدارة إصدارات الذين يحتاجون إلى إدارة وتزامن الفروع Git آلي."},"recommendation":{"en":"Empowers agents to automate branch cleanup workflows using Git commands like ''git fetch'' and ''git pull'', ensuring synchronized main branches and cleaned-up local repositories with merged PRs.","zh":"赋予代理人使用Git命令（如''git fetch''和''git pull''）自动化分支清理工作流程的能力，确保同步的主分支和合并PR的本地存储库。","ja":"エージェントが''git fetch''や''git pull''などのGitコマンドを使用してブランチクリーンアップのワークフローを自動化できるようにし、同期されたメインブランチとマージされたPRのローカルリポジトリを提供します。","ko":"에이전트가 ''git fetch'' 및 ''git pull''와 같은 Git 명령을 사용하여 분기 정리 워크플로를 자동화할 수 있도록 하여 동기화된 메인 분기 및 병합된 PR의 로컬 저장소를 제공합니다.","es":"Habilita a los agentes a automatizar flujos de trabajo de limpieza de ramas utilizando comandos Git como ''git fetch'' y ''git pull'', asegurando ramas principales sincronizadas y repositorios locales limpios con PR fusionados.","fr":"Permet aux agents d''automatiser les flux de travail de nettoyage des branches en utilisant des commandes Git comme ''git fetch'' et ''git pull'', garantissant des branches principales synchronisées et des référentiels locaux nettoyés avec des PR fusionnés.","de":"Ermächtigt die Agenten, Arbeitsflüsse zur Zweigbereinigung mithilfe von Git-Befehlen wie ''git fetch'' und ''git pull'' zu automatisieren, wodurch synchronisierte Hauptzweige und bereinigte lokale Repositorys mit zusammengeführten PRs sichergestellt werden.","pt":"Habilita os agentes a automatizar fluxos de trabalho de limpeza de branches usando comandos Git como ''git fetch'' e ''git pull'', garantindo branches principais sincronizados e repositórios locais limpos com PRs mesclados.","ru":"Наделяет агентов возможностью автоматизировать рабочие процессы очистки веток с помощью команд Git, таких как ''git fetch'' и ''git pull'', обеспечивая синхронизированные основные ветки и очищенные локальные репозитории с объединенными запросами на включение.","ar":"تمكين الوكلاء من توفير سير عمل آلي لتنظيف الفروع باستخدام أوامر Git مثل ''git fetch'' و ''git pull'' ، مما يضمن الفروع الرئيسية المتزامنة والمستودعات المحلية النظيفة مع طلبات الاندماج المزججة."},"useCases":{"en":["Automating branch cleanup after PR merges","Synchronizing main branches with origin repositories","Deleting local branches with merged pull requests"],"zh":["自动化分支清理后PR合并","同步主分支与源存储库","删除合并请求的本地分支"],"ja":["PRのマージ後のブランチクリーンアップの自動化","メインブランチとオリジンリポジトリの同期","マージされたプルリクエストのローカルブランチの削除"],"ko":["PR 병합 후 분기 정리 자동화","메인 분기 및 원본 저장소 동기화","병합된 풀 요청의 로컬 분기 삭제"],"es":["Automatización de la limpieza de ramas después de fusionar PR","Sincronización de ramas principales con repositorios de origen","Eliminación de ramas locales con solicitudes de extracción fusionadas"],"fr":["Automatisation du nettoyage des branches après fusion des PR","Synchronisation des branches principales avec les référentiels d''origine","Suppression des branches locales avec des demandes d''extraction fusionnées"],"de":["Automatisierung der Zweigbereinigung nach PR-Zusammenführung","Synchronisierung von Hauptzweigen mit Ursprungs-Repositorys","Löschen lokaler Zweige mit zusammengeführten Pull-Requests"],"pt":["Automatizar a limpeza de branches após mesclagem de PRs","Sincronizar branches principais com repositórios de origem","Excluir branches locais com solicitações de pull mescladas"],"ru":["Автоматизировать очистку веток после слияния запросов на включение","Синхронизировать основные ветки с репозиториями-источниками","Удалить локальные ветки с объединенными запросами на включение"],"ar":["توفير آلي لتنظيف الفروع بعد دمج طلبات الاندماج","تنسيق الفروع الرئيسية مع المستودعات الأصلية","حذف الفروع المحلية بطلبات السحب المدمجة"]},"limitations":{"en":["Requires Git installation and configuration","Needs permission to execute Git commands","Limited to Git version control system"],"zh":["需要Git安装和配置","需要执行Git命令的权限","仅限于Git版本控制系统"],"ja":["Gitのインストールと設定が必要","Gitコマンドの実行を許可する権限が必要","Gitバージョン管理システムのみに限定される"],"ko":["Git 설치 및 구성이 필요합니다.","Git 명령을 실행할 수 있는 권한 필요","Git 버전 제어 시스템에만 제한됨"],"es":["Requiere instalación y configuración de Git","Necesita permiso para ejecutar comandos Git","Limitado al sistema de control de versiones Git"],"fr":["Nécessite l''installation et la configuration de Git","A besoin d''une autorisation pour exécuter des commandes Git","Limité au système de contrôle de version Git"],"de":["Benötigt Git-Installation und -Konfiguration","Benötigt Berechtigung zur Ausführung von Git-Befehlen","Begrenzt auf das Git-Versionssystem"],"pt":["Exige instalação e configuração do Git","Necessita permissão para executar comandos Git","Limitado ao sistema de controle de versão Git"],"ru":["Требует установки и настройки Git","Требует разрешения на выполнение команд Git","Ограничен системой контроля версий Git"],"ar":["يتطلب تثبيت وتكوين Git","يتطلب إذن لتنفيذ أوامر Git","محدود بنظام إدارة الإصدارات Git"]},"version":3},"contentHash":"7be9f4d7a88cebc33d766eb25e02b1693351e182240c29e32959779358cb1cdc","qualityScore":57}');
