INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fxstein/ai-todo/branch-cleanup', 'branch-cleanup', 'fxstein', 'ai-todo', 'community', 'branch-cleanup fxstein ai-todo community AI-native任务管理，适用于OpenClaw、Cursor、Claude和Copilot等AI智能代理，实现持久、版本控制的TODO跟踪 AIエージェント用のネイティブタスク管理、OpenClaw、Cursor、Claude、CopilotなどのAIエージェントとシームレスに動作 AI 에이전트용 네이티브 태스크 관리, OpenClaw, Cursor, Claude, Copilot 등의 AI 에이전트와 자연스럽게 동작 Gestión de tareas nativa de IA para agentes de codificación con seguimiento de TODO persistente y control de versiones Gestion de tâches native IA pour les agents de codage avec suivi de TODO persistant et contrôle de version KI-native Aufgabenverwaltung für Codierungsagenten mit persistentem TODO-Tracking und Versionskontrolle O branch-cleanup é uma ferramenta de gerenciamento de tarefas de codificação para agentes de IA, como OpenClaw, Cursor, Claude e Copilot. Branch-cleanup - это инструмент управления задачами кодирования для ИИ агентов, таких как OpenClaw, Cursor, Claude и Copilot. branch-cleanup هو أداة لإدارة مهام التشفير لوكلاء الذكاء الاصطناعي مثل OpenClaw و Cursor و Claude و Copilot. AI-native task management for coding agents - Persistent, version-controlled TODO tracking that works naturally with AI agents like OpenClaw, Cursor, Claude, and Copilot AI智能代理 代码管理 TODO跟踪 版本控制 OpenClaw Cursor Claude Copilot 如何使用AI智能代理 AI智能代理安装指南 AI-native task management for coding agents - Persistent, version-controlled TODO tracking that works naturally with AI agents like OpenClaw, Cursor, Claude, and Copilot');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers-chrome/browsing', 'community', 'obra', 'superpowers-chrome', 'obra/superpowers-chrome', 'browsing', 0, 0, 57, '2026-03-04T13:07:01.798Z', '2026-03-04T14:28:53.532Z', '16cfcc0358ac2e0a5af69b6afda0a501e48b59cbba35a55d298ac4b427e0dc70', '{"id":"obra/superpowers-chrome/browsing","name":"browsing","description":{"zh":"Claude Code插件实现了通过DevTools Protocol直接控制Chrome浏览器，无需任何依赖","ja":"Claude CodeプラグインはDevTools Protocolを使用してChromeブラウザを直接制御します","ko":"Claude Code 플러그인은 DevTools Protocol을 사용하여 Chrome 브라우저를 직접 제어합니다","es":"Claude Code es un plugin para controlar directamente el navegador Chrome a través del protocolo DevTools, sin dependencias","fr":"Claude Code est un plugin pour contrôler directement le navigateur Chrome via le protocole DevTools, sans dépendances","de":"Claude Code ist ein Plugin, um den Chrome-Browser direkt über das DevTools-Protokoll zu steuern, ohne Abhängigkeiten","pt":"O plugin Claude Code permite o controle direto do navegador Chrome via DevTools Protocol, sem dependências. É ideal para desenvolvedores que buscam uma solução eficiente","ru":"Плагин Claude Code позволяет напрямую управлять браузером Chrome через DevTools Protocol, без зависимостей. Он идеален для разработчиков, которые ищут эффективное решение","ar":"يسمح إضافة Claude Code بالتحكم المباشر في متصفح Chrome عبر بروتوكول DevTools، بدون зависимости. هو解决 مثالي للمطورين الذين يبحثون عن حل فعال","en":"Claude Code plugin for direct Chrome browser control via DevTools Protocol - zero dependencies"},"seo":{"title":{"zh":"AI智能代理浏览插件 - Claude Code","ja":"AIエージェントブラウジングプラグイン - Claude Code","ko":"AI 에이전트 브라우징 플러그인 - Claude Code","es":"Herramientas de IA: Control de navegador Chrome con Claud...","fr":"Outils IA: Contrôle du navigateur Chrome avec Claude Code","de":"KI-Tools: Chrome-Browser-Steuerung mit Claude Code","pt":"Fer