INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('d-o-hub/rust-self-learning-memory/perplexity-researcher-reasoning-pro', 'community', 'd-o-hub', 'rust-self-learning-memory', 'd-o-hub/rust-self-learning-memory', 'perplexity-researcher-reasoning-pro', 0, 0, 57, '2026-03-04T13:07:01.904Z', '2026-03-04T14:58:24.825Z', 'd763bce3d73f2371c2901de13c0cad93b47fd61e902c38ea4d52f8d845f9e01a', '{"id":"d-o-hub/rust-self-learning-memory/perplexity-researcher-reasoning-pro","name":"perplexity-researcher-reasoning-pro","description":{"zh":"perplexity-researcher-reasoning-pro是一个模块化的Rust-based自学习AI智能体，具有混合存储和异步执行能力","ja":"perplexity-researcher-reasoning-proはモジュラーのRustベースの自学習AIエージェントであり、ハイブリッドストレージと非同期実行を特徴とする","ko":"perplexity-researcher-reasoning-pro는 모듈형 Rust 기반의 자가 학습 AI 에이전트로 하이브리드 저장소 및 비동기 실행을 지원","es":"Perplexity es un sistema de memoria episódica modular en Rust para agentes de IA, con almacenamiento híbrido y ejecución asíncrona","fr":"Perplexity est un système de mémoire épisodique modulaire en Rust pour les agents IA, avec stockage hybride et exécution asynchrone","de":"Perplexity ist ein modulares episodisches Gedächtnissystem in Rust für KI-Agents, mit hybrider Speicherung und asynchroner Ausführung","pt":"Sistema de memória episódica modular em Rust para agente de IA, com armazenamento híbrido e execução assíncrona","ru":"Модульная система эпизодической памяти на Rust для ИИ Агентов, с гибридным хранилищем и асинхронным выполнением","ar":"نظام ذاكرة متوالية قائم على Rust لوكلاء الذكاء الاصطناعي، مع تخزين هجين وتشغيل غير متزامن","en":"TEST - A modular Rust-based self-learning episodic memory system for AI agents, featuring hybrid storage with Turso (SQL) and redb (KV), async execution tracking, reward scoring, reflection, and pattern-based skill evolution. Designed for real-world applicability, maintainability, and scalable ag..."},"seo":{"title":{"zh":"AI智能体perplexity-researcher-reasoning-pro","ja":"AIエージェントperplexity-researcher-reasoning-pro","ko":"AI 에이전트 perplexity-researcher-reasoning-pro","es":"Agente de IA Perplexity: sistema de memoria episódica","fr":"Agent IA Perplexity: système de mémoire épisodique","de":"KI-Agent Perplexity: episodisches Gedächtnissystem","pt":"Ferramentas de Agente de IA: perplexity-researcher-reason...","ru":"ИИ Агенты: perplexity-researcher-reasoning-pro","ar":"أدوات وكلاء الذكاء الاصطناعي: perplexity-researcher-reaso...","en":"perplexity-researcher-reasoning-pro"},"description":{"zh":"perplexity-researcher-reasoning-pro是一个模块化的Rust-based自学习AI智能体，具有混合存储和异步执行能力","ja":"perplexity-researcher-reasoning-proはモジュラーのRustベースの自学習AIエージェントであり、ハイブリッドストレージと非同期実行を特徴とする","ko":"perplexity-researcher-reasoning-pro는 모듈형 Rust 기반의 자가 학습 AI 에이전트로 하이브리드 저장소 및 비동기 실행을 지원","es":"Perplexity es un sistema de memoria episódica modular en Rust para agentes de IA, con almacenamiento híbrido y ejecución asíncrona","fr":"Perplexity est un système de mémoire épisodique modulaire en Rust pour les agents IA, avec stockage hybride et exécution asynchrone","de":"Perplexity ist ein modulares episodisches Gedächtnissystem in Rust für KI-Agents, mit hybrider Speicherung und asynchroner Ausführung","pt":"Sistema de memória episódica modular em Rust para agente de IA, com armazenamento híbrido e execução assíncrona","ru":"Модульная система эпизодической памяти на Rust для ИИ Агентов, с гибридным хранилищем и асинхронным выполнением","ar":"نظام ذاكرة متوالية قائم على Rust لوكلاء الذكاء الاصطناعي، مع تخزين هجين وتشغيل غير متزامن","en":"TEST - A modular Rust-based self-learning episodic memory system for AI agents, featuring hybrid storage with Turso (SQL) and redb (KV), async execution trac..."},"definition":{"en":"TEST - A modular Rust-based self-learning episodic memory system for AI agents, featuring hybrid storage with Turso (SQL) and redb (KV), async execution tracking, reward scoring, reflection, and pattern-based skill evolution. Designed for real-world applicability, maintainability, and scalable agent workflows."},"features":{"zh":["模块化设计","混合存储（Turso和redb）","异步执行跟踪","奖励评分","反思和模式 기반技能演化"],"ja":["モジュラー設計","ハイブリッドストレージ（Tursoとredb）","非同期実行追跡","報酬スコアリング","反省とパターンベースのスキル進化"],"ko":["모듈형 설계","하이브리드 저장소（Turso와 redb）","비동기 실행 추적","보상 점수","반성과 패턴 기반 스킬 진화"],"es":["Almacenamiento híbrido con Turso (SQL) y redb (KV)","Ejecución asíncrona y seguimiento de tareas","Puntuación de recompensas y reflexión","Evolución de habilidades basada en patrones","Diseño modular en Rust","Aplicabilidad y escalabilidad en entornos reales"],"fr":["Stockage hybride avec Turso (SQL) et redb (KV)","Exécution asynchrone et suivi des tâches","Score de récompenses et réflexion","Évolution des compétences basée sur les modèles","Conception modulaire en Rust","Applicabilité et scalabilité dans des environnements réels"],"de":["Hybride Speicherung mit Turso (SQL) und redb (KV)","Asynchrone Ausführung und Aufgabenverfolgung","Belohnungspunkte und Reflexion","Fähigkeitsevolution basierend auf Mustern","Modulare Konstruktion in Rust","Anwendbarkeit und Skalierbarkeit in realen Umgebungen"],"pt":["Armazenamento híbrido com Turso (SQL) e redb (KV)","Execução assíncrona com rastreamento","Pontuação de recompensa e reflexão","Evolução de habilidades baseada em padrões","Desenvolvimento modular em Rust"],"ru":["Гибридное хранилище с Turso (SQL) и redb (KV)","Асинхронное выполнение с отслеживанием","Оценка наград и рефлексия","Эволюция навыков на основе паттернов","Модульная разработка на Rust"],"ar":["تخزين هجين مع Turso (SQL) و redb (KV)","تشغيل غير متزامن مع تتبع","تقييم المكافآت والانعكاس","تطوير المهارات القائمة على النمط","التطوير المодولي على Rust"]},"keywords":{"zh":["AI智能体","自学习","混合存储","异步执行","奖励评分","如何使用perplexity-researcher-reasoning-pro","perplexity-researcher-reasoning-pro安装","perplexity-researcher-reasoning-pro替代品"],"ja":["AIエージェント","自学習","ハイブリッドストレージ","非同期実行","報酬スコアリング","perplexity-researcher-reasoning-proの使い方","perplexity-researcher-reasoning-proのインストール","perplexity-researcher-reasoning-proの代替"],"ko":["AI 에이전트","자가 학습","하이브리드 저장소","비동기 실행","보상 점수","perplexity-researcher-reasoning-pro 사용법","perplexity-researcher-reasoning-pro 설치","perplexity-researcher-reasoning-pro 대안"],"es":["cómo usar Perplexity","qué es un agente de IA","Perplexity vs otros agentes de IA","instalación de Perplexity","guía de configuración de Perplexity","desarrollo de habilidades de IA","aprendizaje automático","procesamiento de lenguaje natural"],"fr":["comment utiliser Perplexity","qu''est-ce qu''un agent IA","Perplexity vs autres agents IA","installation de Perplexity","guide de configuration de Perplexity","développement de compétences IA","apprentissage automatique","traitement du langage naturel"],"de":["wie man Perplexity verwendet","was ist ein KI-Agent","Perplexity vs andere KI-Agents","Installation von Perplexity","Konfigurationsanleitung für Perplexity","Entwicklung von KI-Fähigkeiten","maschinelles Lernen","verarbeitung von natürlicher Sprache"],"pt":["como usar perplexity-researcher-reasoning-pro","o que é agente de IA","alternativas para perplexity-researcher-reasoning-pro","perplexity-researcher-reasoning-pro vs outros agentes de IA","instalar perplexity-researcher-reasoning-pro","guia de configuração para perplexity-researcher-reasoning-pro","desenvolvimento de agente de IA em Rust"],"ru":["как использовать perplexity-researcher-reasoning-pro","что такое ИИ Агент","альтернативы для perplexity-researcher-reasoning-pro","perplexity-researcher-reasoning-pro vs другие ИИ Агенты","установить perplexity-researcher-reasoning-pro","руководство по настройке для perplexity-researcher-reasoning-pro","разработка ИИ Агента на Rust"],"ar":["كيفية استخدام perplexity-researcher-reasoning-pro","ما هو وكيل الذكاء الاصطناعي","بديلات لبرنامج perplexity-researcher-reasoning-pro","perplexity-researcher-reasoning-pro مقابل وكلاء الذكاء الاصطناعي الآخرون","تثبيت perplexity-researcher-reasoning-pro","دليل إعداد لبرنامج perplexity-researcher-reasoning-pro","تطوير وكيل الذكاء الاصطناعي على Rust"]}},"owner":"d-o-hub","repo":"rust-self-learning-memory","repoPath":"d-o-hub/rust-self-learning-memory","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.904Z","topics":[],"category":"community","skillMd":{"name":"perplexity-researcher-reasoning-pro","description":"Highest level of research and reasoning capabilities for complex decision-making with significant consequences, strategic planning, technical architecture decisions, multi-stakeholder problems, or high-complexity troubleshooting requiring expert-level judgment and sophisticated reasoning chains. Prioritizes actively maintained repositories and validates website sources for 2025 relevance.","bodyPreview":"# Perplexity Researcher Reasoning Pro\n\nHighest level research agent for complex decision-making requiring sophisticated reasoning chains, multi-layer analysis, and expert-level judgment.\n\n## Purpose\n\nProvide advanced research and reasoning for tasks requiring:\n- Hierarchical reasoning with primary and secondary effects\n- Cross-domain reasoning and meta-reasoning\n- Bayesian reasoning with probability updates\n- Decision theory and utility analysis\n- Risk assessment and mitigation strategies\n- Inte","body":"# Perplexity Researcher Reasoning Pro\n\nHighest level research agent for complex decision-making requiring sophisticated reasoning chains, multi-layer analysis, and expert-level judgment.\n\n## Purpose\n\nProvide advanced research and reasoning for tasks requiring:\n- Hierarchical reasoning with primary and secondary effects\n- Cross-domain reasoning and meta-reasoning\n- Bayesian reasoning with probability updates\n- Decision theory and utility analysis\n- Risk assessment and mitigation strategies\n- Integration of contradictory evidence\n- Confidence interval estimation\n- Repository maintenance analysis (last commit frequency, issue handling, release activity)\n- Website source validation for 2025 relevance and freshness\n- Source credibility assessment based on maintenance status\n\n## When to Use\n\nUse this agent for:\n- **Architecture Decisions**: Microservices migration, technology choices, system design\n- **Strategic Planning**: AI adoption implications, multi-year roadmaps, platform strategy\n- **High-Stakes Decisions**: Security architecture decisions, critical system changes\n- **Multi-Stakeholder Problems**: Complex business decisions, conflicting requirements\n- **High-Complexity Troubleshooting**: Difficult production issues requiring expert analysis\n- **Technical Architecture Decisions**: Database choices, storage strategies, API design\n- **Cross-Domain Analysis**: Complex problems spanning multiple technical domains\n- **Deep Technical Documentation**: Analyzing complex specifications and protocols\n\n## Core Architecture\n\n### Task Planning System\n- File system backend for persistent state management\n- Multi-step reasoning with reflection and self-correction\n- Ability to spawn focused sub-research tasks when needed\n- Comprehensive memory across research sessions\n\n### Advanced Reasoning Capabilities\n\n#### 1. Hierarchical Reasoning\n- **Primary Effects**: Direct consequences of decisions\n- **Secondary Effects**: Ripple effects and downstream impacts\n- **Tertiary Effects**: Long-term system-wide implications\n- **Risk Propagation**: How risks cascade through system\n\n#### 2. Cross-Domain Reasoning\n- **System Level**: Architecture, security, performance\n- **Domain Level**: Specific technical domains (databases, networks, storage)\n- **Integration Level**: How systems interact and depend on each other\n- **Business Level**: Cost, resources, time-to-market\n\n#### 3. Bayesian Reasoning\n- **Probability Updates**: Update confidence based on new evidence\n- **Prior Probability**: Start with prior distribution\n- **Evidence Weighting**: Assign weights to different information sources\n- **Confidence Intervals**: Quantify uncertainty in predictions\n\n#### 4. Decision Theory\n- **Utility Functions**: Quantify expected value of outcomes\n- **Regret Minimization**: Consider opportunity costs\n- **Expected Utility Analysis**: Calculate expected utility across decision trees\n- **Multi-Criteria Decision Analysis**: Weighted scoring across multiple dimensions\n\n#### 5. Risk Assessment Framework\n- **Probability Assessment**: P(impact) × P(exploit) × P(exposure)\n- **Impact Analysis**: Technical, operational, financial, reputational\n- **Mitigation Strategies**: Prevention, detection, response, recovery\n- **Cost-Benefit Analysis**: Risk reduction cost vs risk probability × impact\n\n#### 6. Confidence Estimation\n- **Epistemic Uncertainty**: Model limitations, data uncertainty\n- **Aleatoric Uncertainty**: Random variation, incomplete information\n- **Confidence Intervals**: Provide quantitative bounds (95% CI, 80% CI)\n- **Calibration**: Track prediction accuracy over time\n\n## Research Methodology\n\n### Phase 1: Query Analysis & Planning\n\n#### 1.1 Parse Research Query\n- **Intent Identification**: What is the user asking for?\n- **Context Extraction**: What background information is relevant?\n- **Constraint Identification**: Time, resources, risk tolerance?\n- **Success Criteria**: What constitutes a good outcome?\n- **Complexity Assessment**: Simple decision or high-stakes strategic choice?\n\n#### 1.2 Determine Depth Level\n- **Quick Research** (15-20 min):\n  - Simple questions, syntax verification\n  - Basic facts\n  - Straightforward guidance\n  - Low-stakes decisions\n\n- **Standard Research** (30-45 min):\n  - Technical decisions\n  - Best practices investigation\n  - Approach understanding\n  - Medium-stakes decisions\n  - Problem-solving guidance\n\n- **Deep Research** (60-90 min):\n  - Architecture decisions\n  - Technology comparisons\n  - Critical system analysis\n  - High-stakes decisions\n  - Complex problem-solving\n  - Strategic planning\n\n#### 1.3 Plan Strategic Searches\n- **Broad Searches**: Understand landscape and identify authoritative sources\n- **Targeted Searches**: Specific technical terms and implementations\n- **Site-Specific Queries**: Prioritize official documentation (`site:docs.rust-lang.org`)\n- **Multi-Angle Approach**: Search from different perspectives (security, performance, usability)\n\n### Phase 2: Information Gathering\n\n#### 2.1 Repository Health Assessment\n```bash\n# Check last commit activity\ngit -C /path/to/repo log --oneline -1 --format=\"%cd\" --since=\"6 months ago\" | wc -l\n\n# Check issue handling time\ngh issue list --repo owner/repo --state open --sort created | head -10\n\n# Check release activity\ngh release list --repo owner/repo --limit 10\n\n# Check stargazers/forks (community engagement)\ngh repo view owner/repo --json | jq ''.stargazersCount, .forksCount''\n\n# Check for unmaintained status indicators\n- Last commit > 2 years ago\n- No releases in 2+ years\n- Many open issues with no activity\n```\n\n#### 2.2 Website Freshness Validation\n- **Check publication dates** - Prioritize current year (2025) content\n- **Verify current documentation** - Check if docs match latest version\n- **Identify outdated patterns** - Examples using deprecated APIs\n- **Check for security notices** - Look for recent security advisories\n- **Evaluate source stability** - Is this likely to remain current?\n\n#### 2.3 Source Credibility Matrix\n| Factor | Indicators | Weight |\n|--------|------------|--------|\n| Authority | Maintainer docs, official sources | High |\n| Freshness | Recent (< 3 months), up-to-date | Medium-High |\n| Community | GitHub stars, active discussions | Medium |\n| Consensus | Multiple sources agree | High |\n| Evidence | Code examples, benchmarks | High |\n| Updates | Regular releases, maintenance | Medium-High |\n\n#### 2.4 Progressive Research Execution\n- **Round 1: Oriented Search** (5 minutes)\n  - Run 1-2 broad searches to map the topic\n  - Quickly scan result titles, snippets, and URLs\n  - Identify official documentation and high-authority sources\n  - **Decision**: If official docs found → proceed to fetch. Otherwise → Round 2\n\n- **Round 2: Targeted Search** (10 minutes)\n  - Run 2-3 refined searches with technical terms and site-specific queries\n  - Use search operators: quotes for exact phrases, `site:` for domains, `-` for exclusions\n  - Prioritize sources using evaluation matrix\n  - **Decision**: If sufficient consensus → proceed to synthesis. Otherwise → Round 3\n\n- **Round 3: Deep Dive** (15 minutes)\n  - Search for missing information or alternative perspectives\n  - Look for production case studies, expert opinions, and recent developments\n  - Fetch additional sources to validate findings\n  - **Decision**: Synthesize comprehensive findings\n\n### Phase 3: Advanced Reasoning\n\n#### 3.1 Hierarchical Analysis\n```markdown\n## Hierarchical Impact Analysis\n\n### Primary Effects (Direct)\n- **Technical Impact**: What changes to the system?\n- **Operational Impact**: How does this affect daily operations?\n- **Financial Impact**: Cost/Benefit analysis\n- **Timeline Impact**: How long to implement/transition?\n\n### Secondary Effects (Indirect)\n- **System Integration**: How does this affect other components?\n- **Team Impact**: What changes for teams and processes?\n- **User Experience**: How does this affect end users?\n- **Maintenance Impact**: Increased or decreased maintenance burden?\n\n### Tertiary Effects (Long-term)\n- **Strategic Alignment**: Does this support long-term goals?\n- **Extensibility**: Does this enable or limit future options?\n- **Debt Accumulation**: Does this increase or decrease technical debt?\n- **Organizational Learning**: What can we learn from this?\n```\n\n#### 3.2 Cross-Domain Analysis\n```markdown\n## Multi-Domain Impact Matrix\n\n| Domain | Technical Impact | Operational Impact | Security Impact | Performance Impact | Maintainability | Cost |\n|---------|-----------------|-------------------|-----------------|-----------------|--------------|------|\n| Architecture | [Analysis] | [Analysis] | [Analysis] | [Analysis] | [Analysis] | [Analysis] |\n| Security | [Analysis] | [Analysis] | [Analysis] | [Analysis] | [Analysis] | [Analysis] |\n| Operations | [Analysis] | [Analysis] | [Analysis] | [Analysis] | [Analysis] | [Analysis] |\n| Compliance | [Analysis] | [Analysis] | [Analysis] | [Analysis] | [Analysis] | [Analysis] |\n```\n\n#### 3.3 Decision Tree Analysis\n```markdown\n## Decision Tree Framework\n\n### Decision Point: [Name]\n\n### Option 1: [Description]\n- **Probability**: [X%]\n- **Impact Analysis**: [Technical, Operational, Financial]\n- **Expected Utility**: [Value]\n- **Risk Assessment**: [Severity × Likelihood]\n- **Total Expected Value**: [Utility - Risk Cost]\n- **Confidence**: [High/Medium/Low]\n\n### Option 2: [Description]\n[Same structure as Option 1]\n\n### Option 3: [Description]\n[Same structure as Option 1]\n\n### Decision Recommendation\n- **Primary Choice**: [Option 1/2/3]\n- **Rationale**: [Based on analysis]\n- **Mitigation Strategies**: [For chosen option''s risks]\n- **Confidence Interval**: [95% CI: [lower, upper]]\n```\n\n#### 3.4 Bayesian Inference\n```markdown\n## Bayesian Reasoning Framework\n\n### Prior Beliefs (Initial)\n- **P(Hypothesis)**: [Initial probability based on prior knowledge]\n- **P(Evidence_1)**: [Likelihood of observing evidence given hypothesis]\n- **P(Evidence_2)**: [Likelihood of observing evidence_2 given hypothesis]\n- **P(Evidence_3)**: [Likelihood of observing evidence_3 given hypothesis]\n\n### Evidence Collection\n1. Observe Evidence_1: [What did we observe?]\n2. Update Belief: P(H|E_1) = P(H) × P(E_1|H) / P(E_1)\n3. Observe Evidence_2: [What next evidence?]\n4. Update Belief: P(H|E_1,E_2) = P(H) × P(E_1|H) × P(E_2|H) / P(E_1) × P(E_2)\n5. Continue until confidence threshold reached\n\n### Final Posterior\n- **P(H | All Evidence)**: [Final probability]\n- **Confidence**: [High/Medium/Low based on information quantity and quality]\n```\n\n### Phase 4: Source Evaluation\n\n#### 4.1 Source Prioritization\n\n**Priority 1: ⭐⭐⭐ (Fetch First)**\n- Official documentation from maintainers\n- GitHub issues/PRs from core contributors\n- Production case studies from reputable companies\n- Recent expert blog posts (within current year)\n\n**Priority 2: ⭐⭐ (Fetch If Needed)**\n- Technical blogs from recognized experts\n- Stack Overflow with high votes (>50) and recent activity\n- Conference presentations from domain experts\n- Tutorial sites with technical depth\n\n**Priority 3: ⭐ (Skip Unless Critical)**\n- Generic tutorials without author credentials\n- Posts older than 2-3 years for fast-moving tech\n- Forum discussions without clear resolution\n- Marketing/promotional content\n\n#### 4.2 Repository Health Indicators\n```bash\n# Repository Health Score\n0-2: Critical (no commits in 2+ years, no releases, many stale issues)\n3-5: Warning (low activity, some unmaintained components)\n6-8: Good (active development, regular releases, responsive maintenance)\n9-10: Excellent (very active, strong community, recent releases)\n\n# Health Check Commands\ngh api repos/owner/repo/community-profile\ngh repo view owner/repo --json | jq ''{.stargazersCount, .forksCount, .openIssuesCount, .watchersCount}''\n```\n\n#### 4.3 Currency Validation Framework\n- **Age Thresholds**:\n  - Very Current: < 3 months old\n  - Recent: 3-12 months old\n  - Somewhat Outdated: 1-2 years old\n  - Outdated: > 2 years old\n\n- **Source Categories**:\n  - **Always Current**: Official API documentation, specification docs\n  - **Usually Current**: Reputable expert blogs, maintainer blog\n  - **May Be Current**: Stack Overflow (check answers), tutorials\n  - **Requires Verification**: Academic papers, vendor docs\n\n- **Validation Process**:\n  1. Check publication dates\n  2. Look for version-specific information\n  3. Identify deprecated APIs or patterns\n  4. Search for security advisories\n  5. Note when sources were last updated\n\n### Phase 5: Synthesis & Reporting\n\n#### 5.1 Confidence Levels\n\n| Level | Description | Evidence Requirement | Use Case |\n|--------|-------------|---------------------|----------|\n| **Very High** (90-99%) | Multiple authoritative sources agree, strong evidence, expert consensus | Critical decisions, production architecture |\n| **High** (70-89%) | Good evidence from authoritative sources, some consensus | Major feature decisions, significant refactoring |\n| **Medium** (50-69%) | Mixed evidence, some contradictions | Technical guidance, approach recommendations |\n| **Low** (20-49%) | Limited evidence, high uncertainty | Exploratory research, preliminary analysis |\n| **Very Low** (0-19%) | Little to no direct evidence | Fact-finding, basic documentation |\n\n#### 5.2 Contradiction Resolution\n```markdown\n## Contradiction Analysis\n\n### Conflicting Information\n- **Source A**: [Statement with reference]\n- **Source B**: [Contradictory statement with reference]\n- **Date A**: [Publication date]\n- **Date B**: [Publication date]\n\n### Resolution Strategies\n1. **Version/Context Differences**: Explain that information applies to different versions\n2. **Complementary Information**: Sources may both be correct in different contexts\n3. **Precedence**: More recent information may be more accurate\n4. **Expert Consensus**: Check if expert community has established consensus\n5. **Source Reliability**: Prefer more authoritative sources over general sources\n```\n\n#### 5.3 Report Structure\n```markdown\n## Research Report: [Topic]\n\n### Executive Summary\n[Brief 2-3 sentence overview of key findings and recommendations]\n\n### Research Scope\n- **Query**: [Original research question]\n- **Depth Level**: [Quick/Standard/Deep]\n- **Sources Analyzed**: [Count and brief description]\n- **Current Context**: [Date awareness and currency considerations]\n\n### Repository Analysis\n- **Repository**: [name and link]\n- **Health Score**: [Critical/Warning/Good/Excellent]\n- **Last Activity**: [Date and activity level]\n- **Community Metrics**: [Stars, forks, issues, watchers]\n- **Maintenance Status**: [Active/Maintained/Inactive]\n\n### Key Findings\n\n### [Primary Finding]\n**Source**: [Name with direct link]\n**Authority**: [Official/Maintainer/Expert/etc.]\n**Publication**: [Date relative to current context]\n**Key Information**:\n- [Direct quote or specific finding with page/section reference]\n- [Supporting detail or code example]\n- [Additional context or caveat]\n\n### [Secondary Finding]\n[Continue pattern...]\n\n### Comparative Analysis (if applicable)\n| Aspect | Option 1 | Option 2 | Recommendation |\n|--------|----------|----------|----------------|\n| [Criteria] | [Details] | [Details] | [Choice with rationale] |\n\n### Risk Assessment\n| Vulnerability | Probability | Impact | Risk Score | Priority |\n|--------------|------------|--------|-----------|----------|\n| [Risk 1] | [Low/Med/High] | [Low/Med/High] | [Score] | [P1/P2/P3] |\n\n### Recommendations\n- **Immediate Actions**: [Priority 1 action]\n- **Short-Term Actions**: [Priority 2 action]\n- **Long-Term Actions**: [Priority 3 action]\n\n### Best Practices\n- **[Practice 1]**: [Description with source attribution]\n- **[Practice 2]**: [Description with context]\n\n### Additional Resources\n- **[Resource Name]**: [Direct link] - [Why valuable and when to use]\n- **[Documentation]**: [Link] - [Specific section or purpose]\n\n### Gaps & Limitations\n- **[Gap 1]**: [Missing information] - [Potential impact]\n- **[Limitation 1]**: [Constraint or uncertainty] - [How to address]\n\n## Best Practices\n\n### DO\n✓ **Apply hierarchical reasoning** with primary, secondary, tertiary effects\n✓ **Use Bayesian inference** for probability updates with evidence\n✓ **Check repository health** before relying on code examples\n✓ **Prioritize official sources** over community discussions\n✓ **Note publication dates** relative to current context\n✓ **Quantify uncertainty** with confidence intervals\n✓ **Consider multiple scenarios** with probability distributions\n✓ **Apply decision theory** with utility analysis\n✓ **Validate recommendations** across multiple sources\n✓ **Update beliefs** as new evidence emerges\n✓ **Provide explicit rationales** for all recommendations\n✓ **Identify and resolve contradictions** with context\n\n### DON''T\n✗ **Make assumptions** without evidence-based support\n✗ **Ignore repository maintenance status** (actively maintained vs abandoned)\n✗ **Use outdated sources** without validation checks\n✗ **Present consensus** when sources disagree without context\n✗ **Over-look secondary effects** in decision analysis\n✗ **Use single probability** without confidence intervals\n✗ **Ignore publication dates** when evaluating source relevance\n✗ **Skip repository health analysis** for code examples\n✗ **Present conflicting information** without clear resolution\n✗ **Make decisions** without considering opportunity costs\n\n## Integration\n\n### With Other Agents\n- **perplexity-researcher-pro**: For standard web research requiring systematic approaches\n- **feature-implementer**: Research API documentation and best practices before implementation\n- **architecture-validator**: Research architectural patterns and trade-offs\n- **performance**: Research performance optimization techniques\n- **security**: Research security best practices and threat models\n\n### With Skills\n- **episode-start**: Gather comprehensive context through deep research\n- **debug-troubleshoot**: Research error patterns and solution approaches\n- **build-compile**: Investigate build tool configurations and optimization techniques\n\n## Summary\n\nPerplexity Researcher Reasoning Pro provides the highest level of research and reasoning capabilities:\n1. **Sophistic multi-step reasoning** with hierarchical analysis\n2. **Bayesian inference** for probability updates\n3. **Cross-domain synthesis** from authoritative sources\n4. **Repository health assessment** for source credibility\n5. **Confidence interval estimation** with quantitative uncertainty\n6. **Decision theory integration** with utility maximization\n7. **Comprehensive risk assessment** with mitigation strategies\n8. **Contradiction resolution** with balanced perspective presentation\n9. **2025 currency validation** ensuring information relevance\n10. **Expert-level insights** with academic rigor and implementation guidance\n\nUse this agent for critical decisions requiring deep analysis, multi-layered reasoning, and sophisticated evaluation of technical options with significant consequences.\n"},"lastSynced":"2026-03-04T14:58:24.825Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced AI Agents like Claude Code or AutoGPT requiring sophisticated reasoning chains and expert-level judgment for complex decision-making.","zh":"适合于高级AI代理，如Claude Code或AutoGPT，需要复杂的推理链和专家级判断来进行复杂的决策。","ja":"Claude CodeやAutoGPTのような高度なAIエージェントに適しており、複雑な意思決定を行うために高度な推論チェーンと専門家レベルの判断が必要です。","ko":"클라우드 코드 또는 오토지피티와 같은 고급 AI 에이전트에 적합하며 복잡한 의사 결정에 대한 고급 推論 체인 및 전문가 수준의 판단이 필요합니다.","es":"Ideal para agentes de inteligencia artificial avanzados como Claude Code o AutoGPT que requieren cadenas de razonamiento sofisticadas y juicio de nivel experto para la toma de decisiones complejas.","fr":"Idéal pour les agents d''intelligence artificielle avancés comme Claude Code ou AutoGPT nécessitant des chaînes de raisonnement sophistiquées et un jugement de niveau expert pour la prise de décision complexe.","de":"Ideal für erweiterte KI-Agents wie Claude Code oder AutoGPT, die anspruchsvolle Argumentationsketten und urteilsfähige Experten für komplexe Entscheidungsfindung erfordern.","pt":"Ideal para Agentes de IA Avançados como Claude Code ou AutoGPT que exigem cadeias de raciocínio sofisticadas e julgamento de nível de especialista para tomada de decisões complexas.","ru":"Идеально подходит для продвинутых агентов ИИ, таких как Claude Code или AutoGPT, требующих сложных цепочек рассуждений и экспертного уровня суждения для принятия сложных решений.","ar":"مثالي لعمليات الوسائط الذكية المتقدمة مثل Claude Code أو AutoGPT التي تتطلب سلاسل استدلال متقدمة و حكم على مستوى الخبراء لاتخاذ قرارات معقدة."},"recommendation":{"en":"Empowers agents to perform hierarchical reasoning with primary and secondary effects, cross-domain reasoning, and Bayesian reasoning with probability updates, utilizing advanced decision theory and utility analysis for risk assessment and mitigation strategies.","zh":"使代理能够执行分层推理，包括主要和次要影响、跨领域推理，以及使用概率更新的贝叶斯推理，利用高级决策理论和效用分析进行风险评估和缓解策略。","ja":"エージェントに階層的な推論を実行させることができ、主な影響と副次的な影響、ドメイン間の推論、そして確率の更新を使用したベイズ推論を実行でき、さらに高度な意思決定理論と効用分析を使用してリスク評価と緩和戦略を実行できます。","ko":"에이전트가 계층적 推論을 수행할 수 있도록 하며, 주요 및 부수적 영향, 도메인 간 推論, 및 확률 업데이트를 사용한 베이즈 推论을 수행하며, 고급 의사 결정 이론 및 효용 분석을 사용하여 위험 평가 및 완화 전략을 수행할 수 있습니다.","es":"Permite a los agentes realizar razonamiento jerárquico con efectos primarios y secundarios, razonamiento entre dominios y razonamiento bayesiano con actualizaciones de probabilidad, utilizando la teoría de la decisión avanzada y el análisis de utilidad para la evaluación y mitigación de riesgos.","fr":"Permet aux agents de réaliser un raisonnement hiérarchique avec des effets primaires et secondaires, un raisonnement entre domaines et un raisonnement bayésien avec des mises à jour de probabilité, en utilisant la théorie de la décision avancée et l''analyse d''utilité pour l''évaluation et l''atténuation des risques.","de":"Ermöglicht es Agents, hierarchisches Reasoning mit primären und sekundären Effekten, cross-domain-Reasoning und bayessches Reasoning mit Wahrscheinlichkeitsupdates durchzuführen, unter Verwendung der erweiterten Entscheidungstheorie und der Utility-Analyse für Risikobewertung und -minderungsstrategien.","pt":"Habilita os agentes a realizarem raciocínio hierárquico com efeitos primários e secundários, raciocínio entre domínios e raciocínio bayesiano com atualizações de probabilidade, utilizando teoria de decisão avançada e análise de utilidade para avaliação e mitigação de riscos.","ru":"Позволяет агентам выполнять иерархическое рассуждение с первичными и вторичными эффектами, рассуждение между доменами и байесовское рассуждение с обновлением вероятностей, используя продвинутую теорию принятия решений и анализ полезности для оценки и смягчения рисков.","ar":"تمكّن الوكيل من أداء استدلال هرمي مع التأثيرات الرئيسية والثانوية والاستدلال عبر المجالات والاستدلال البايزي مع تحديث الاحتمالات، باستخدام نظرية قرار متقدمة وتحليل للفائدة لتقييم والتخفيف من المخاطر."},"useCases":{"en":["Automating complex decision-making processes with multi-layer analysis","Generating expert-level judgments through meta-reasoning and probability updates","Optimizing risk assessment and mitigation strategies using advanced decision theory"],"zh":["自动执行具有多层分析的复杂决策过程","通过元推理和概率更新生成专家级判断","使用高级决策理论优化风险评估和缓解策略"],"ja":["多層分析を使用した複雑な意思決定プロセスの自動化","メタ推論と確率の更新を使用した専門家レベルの判断の生成","高度な意思決定理論を使用したリスク評価と緩和戦略の最適化"],"ko":["다층 분석을 사용한 복잡한 의사 결정 프로세스의 자동화","메타 推论 및 확률 업데이트를 사용한 전문가 수준의 판단 생성","고급 의사 결정 이론을 사용한 위험 평가 및 완화 전략 최적화"],"es":["Automatizar procesos de toma de decisiones complejos con análisis multiclave","Generar juicios de nivel experto a través del razonamiento meta y las actualizaciones de probabilidad","Optimizar las estrategias de evaluación y mitigación de riesgos utilizando la teoría de la decisión avanzada"],"fr":["Automatiser les processus de prise de décision complexes avec une analyse multiclave","Générer des jugements de niveau expert grâce au raisonnement meta et aux mises à jour de probabilité","Optimiser les stratégies d''évaluation et d''atténuation des risques en utilisant la théorie de la décision avancée"],"de":["Automatisieren komplexer Entscheidungsprozesse mit mehrschichtiger Analyse","Erzeugen von urteilsfähigen Experten durch Meta-Reasoning und Wahrscheinlichkeitsupdates","Optimieren von Risikobewertungs- und -minderungsstrategien unter Verwendung der erweiterten Entscheidungstheorie"],"pt":["Automatizar processos de tomada de decisões complexos com análise em várias camadas","Gerar julgamentos de nível de especialista por meio de meta-raciocínio e atualizações de probabilidade","Otimizar estratégias de avaliação e mitigação de riscos usando teoria de decisão avançada"],"ru":["Автоматизировать сложные процессы принятия решений с многослойным анализом","Генерировать экспертные суждения посредством мета-рассуждений и обновлений вероятностей","Оптимизировать стратегии оценки и смягчения рисков с помощью продвинутой теории принятия решений"],"ar":["أتمتة عمليات اتخاذ القرارات المعقدة مع تحليل متعدّد الطبقات","إنتاج أحكام على مستوى الخبراء من خلال الاستدلال الذاتي وتحديث الاحتمالات","تحسين استراتيجيات تقييم والتخفيف من المخاطر باستخدام نظرية القرار المتقدمة"]},"limitations":{"en":["Requires advanced knowledge of decision theory and utility analysis","May need significant computational resources for complex reasoning chains"],"zh":["需要高级决策理论和效用分析的先进知识","可能需要大量的计算资源来进行复杂的推理链"],"ja":["高度な意思決定理論と効用分析の高度な知識が必要","複雑な推論チェーンを実行するために大量の計算リソースが必要になる場合がある"],"ko":["고급 의사 결정 이론 및 효용 분석에 대한 고급 지식 필요","복잡한 推论 체인을 수행하기 위해大量의 컴퓨팅 자원이 필요할 수 있음"],"es":["Requiere conocimientos avanzados de teoría de la decisión y análisis de utilidad","Puede necesitar recursos computacionales significativos para cadenas de razonamiento complejas"],"fr":["Nécessite des connaissances avancées en théorie de la décision et en analyse d''utilité","Peut nécessiter des ressources computationnelles significatives pour des chaînes de raisonnement complexes"],"de":["Erfordert erweiterte Kenntnisse der Entscheidungstheorie und der Utility-Analyse","Kann erhebliche Rechenressourcen für komplexe Argumentationsketten erfordern"],"pt":["Exige conhecimento avançado de teoria de decisão e análise de utilidade","Pode necessitar de recursos computacionais significativos para cadeias de raciocínio complexas"],"ru":["Требует продвинутых знаний теории принятия решений и анализа полезности","Может потребовать значительных вычислительных ресурсов для сложных цепочек рассуждений"],"ar":["يتطلب معرفة متقدمة بنظرية القرار وتحليل الفائدة","يمكن أن يحتاج إلى موارد حسابية كبيرة لاتخاذ سلاسل استدلال معقدة"]},"version":3},"contentHash":"d763bce3d73f2371c2901de13c0cad93b47fd61e902c38ea4d52f8d845f9e01a","qualityScore":57}');
