INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('omriariav/workspace-cli/gws-chat', 'gws-chat', 'omriariav', 'workspace-cli', 'community', 'gws-chat omriariav workspace-cli community Google Workspaxce CLI是实现高效工作流程的强大工具，通过命令行界面简化任务 Google Workspaxce CLIは効率的なワークフローを実現する強力なツールです。コマンドラインインターフェースを使用してタスクを簡素化します Google Workspaxce CLI는 효율적인 워크플로우를 구현하는 강력한 도구로, 명령줄 인터페이스를 통해 작업을 간소화합니다 gws-chat es una herramienta de línea de comandos no oficial de Google Workspace, diseñada para mejorar la productividad gws-chat est un outil de ligne de commande non officiel de Google Workspace, conçu pour améliorer la productivité gws-chat ist ein inoffizielles Kommandozeilen-Tool von Google Workspace, das zur Steigerung der Produktivität entwickelt wurde O gws-chat é uma ferramenta de linha de comando para interagir com o Google Workspace de forma eficiente, permitindo que os desenvolvedores automatem tarefas e acessem recursos facilmente gws-chat - это неофициальный CLI для Google Workspace, который позволяет разработчикам автоматизировать задачи и легко доступать к ресурсам gws-chat هو أداة سطر أوامر غير رسمية لجوجل ووركسبايس التي تمكن المطورين من Automating المهام والوصول إلى الموارد بسهولة Unofficial Google Workspaxce CLI AI工具 Google Workspaxce CLI 命令行界面 任务自动化 Google Workspaxce集成 如何使用Google Workspaxce CLI Google Workspaxce CLI安装 Google Workspaxce CLI设置指南 Unofficial Google Workspaxce CLI ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ranbot-ai/awesome-skills/using-neon', 'community', 'ranbot-ai', 'awesome-skills', 'ranbot-ai/awesome-skills', 'using-neon', 0, 0, 57, '2026-03-04T13:07:01.960Z', '2026-03-04T15:13:38.747Z', '15f93fb7b0396c7ea830556b85e361bf4658b7d84d9b603084eeaa173699726f', '{"id":"ranbot-ai/awesome-skills/using-neon","name":"using-neon","description":{"zh":"Neon是用于定制AI代理工作流程的工具，帮助开发者提高效率","ja":"NeonはAIエージェントのワークフローをカスタマイズするためのツールであり、開発者の効率を向上させる","ko":"Neon은 AI 에이전트 워크플로우를 맞춤형으로 제작하기 위한 도구로 개발자들의 효율성을 높여줍니다","es":"Neon es una herramienta para personalizar flujos de trabajo de Claude AI, permitiendo a los desarrolladores crear soluciones de AI Agents más eficaces","fr":"Neon est un outil pour personnaliser les flux de travail de Claude AI, permettant aux développeurs de créer des solutions d''Agents IA plus efficaces","de":"Neon ist ein Tool zum Anpassen von Claude AI-Workflows, mit dem Entwickler effizientere AI-Tool-Lösungen erstellen können","pt":"O Neon é uma ferramenta poderosa para personalizar workflows de IA com Claude. Aprenda a usá-lo para melhorar a eficiência","ru":"Neon - это мощный инструмент для настройки рабочих процессов ИИ с Claude. Узнайте, как им пользоваться, чтобы повысить эффективность","ar":"Neon هو أداة قوية لتحسين تدفقات العمل مع Claude. تعلم كيفية استخدامه لتحسين الكفاءة","en":"Awesome Claude Skills, Tools for Customizing Claude AI workflows"},"seo":{"title":{"zh":"使用Neon的AI代理工具","ja":"Neonを使用したAIエージェントのカスタマイズ","ko":"Neon을 사용하여 AI 에이전트 맞춤형 제작","es":"Herramientas de AI Agents: Uso de Neon","fr":"Outils d''Agents IA: Utilisation de Neon","de":"AI-Tools: Mit Neon arbeiten","pt":"Ferramentas de IA: Usando Neon para Personalizar Workflows","ru":"ИИ Агенты: Использование Neon для Настройки Работы Claude AI","ar":"أدوات الذكاء الاصطناعي: استخدام Neon لتحسين تدفقات العمل","en":"using-neon"},"description":{"zh":"Neon是用于定制AI代理工作流程的工具，帮助开发者提高效率","ja":"NeonはAIエージェントのワークフローをカスタマイズするためのツールであり、開発者の効率を向上させる","ko":"Neon은 AI 에이전트 워크플로우를 맞춤형으로 제작하기 위한 도구로 개발자들의 효율성을 높여줍니다","es":"Neon es una herramienta para personalizar flujos de trabajo de Claude AI, permitiendo a los desarrolladores crear soluciones de AI Agents más eficaces","fr":"Neon est un outil pour personnaliser les flux de travail de Claude AI, permettant aux développeurs de créer des solutions d''Agents IA plus efficaces","de":"Neon ist ein Tool zum Anpassen von Claude AI-Workflows, mit dem Entwickler effizientere AI-Tool-Lösungen erstellen können","pt":"O Neon é uma ferramenta poderosa para personalizar workflows de IA com Claude. Aprenda a usá-lo para melhorar a eficiência","ru":"Neon - это мощный инструмент для настройки рабочих процессов ИИ с Claude. Узнайте, как им пользоваться, чтобы повысить эффективность","ar":"Neon هو أداة قوية لتحسين تدفقات العمل مع Claude. تعلم كيفية استخدامه لتحسين الكفاءة","en":"Awesome Claude Skills, Tools for Customizing Claude AI workflows"},"definition":{"en":"Awesome Claude Skills, Tools for Customizing Claude AI workflows"},"features":{"zh":["支持AI代理工作流程定制","提供高效的开发工具","支持多种编程语言","提供灵活的工作流程管理","支持实时调试和测试"],"ja":["AIエージェントのワークフローをカスタマイズ","開発効率を向上させるツールを提供","複数のプログラミング言語をサポート","柔軟なワークフロー管理を提供","リアルタイムでのデバッグとテストをサポート"],"ko":["AI 에이전트 워크플로우를 맞춤형으로 제작","개발 효율성을 높여주는 도구를 제공","다양한 프로그래밍 언어를 지원","유연한 워크플로우 관리를 제공","실시간 디버깅과 테스트를 지원"],"es":["Personalización de flujos de trabajo de Claude AI","Integración con herramientas de desarrollo de AI Agents","Mejora de la eficiencia en la creación de soluciones de AI","Compatibilidad con tecnologías como React y Node.js","Acceso a una comunidad de desarrolladores de AI Agents","Documentación y soporte técnico para desarrolladores"],"fr":["Personnalisation des flux de travail de Claude AI","Intégration avec des outils de développement d''Agents IA","Amélioration de l''efficacité dans la création de solutions d''IA","Compatibilité avec des technologies comme React et Node.js","Accès à une communauté de développeurs d''Agents IA","Documentation et support technique pour les développeurs"],"de":["Anpassung von Claude AI-Workflows","Integration mit Entwicklungstools für AI-Tools","Verbesserung der Effizienz bei der Erstellung von AI-Lösungen","Kompatibilität mit Technologien wie React und Node.js","Zugang zu einer Entwickler-Community für AI-Tools","Dokumentation und technischer Support für Entwickler"],"pt":["Personalização de workflows de IA","Integração com Claude","Melhoria da eficiência","Ferramentas de automação","Suporte a desenvolvedores"],"ru":["Настройка рабочих процессов ИИ","Интеграция с Claude","Повышение эффективности","Инструменты автоматизации","Поддержка разработчиков"],"ar":["تحسين تدفقات العمل","التكامل مع Claude","تحسين الكفاءة","أدوات الأتمتة","دعم المطورين"]},"keywords":{"zh":["如何使用Neon","Neon教程","AI代理工具","Neon与其他工具的比较","Neon安装指南","Neon设置教程","使用Neon开发AI代理"],"ja":["Neonの使い方","Neonチュートリアル","AIエージェントツール","Neonと他のツールの比較","Neonのインストールガイド","Neonの設定方法","Neonを使用したAIエージェントの開発"],"ko":["Neon을 사용하는 방법","Neon 튜토리얼","AI 에이전트 도구","Neon과 다른 도구의 비교","Neon 설치 가이드","Neon 설정 방법","Neon을 사용하여 AI 에이전트 개발"],"es":["cómo usar Neon","herramientas de AI Agents","personalización de flujos de trabajo de Claude AI","desarrollo de AI Agents","Neon vs Claude AI","instalación de Neon","guía de configuración de Neon","mejores prácticas para AI Agents","Neon para desarrolladores"],"fr":["comment utiliser Neon","outils d''Agents IA","personnalisation des flux de travail de Claude AI","développement d''Agents IA","Neon vs Claude AI","installation de Neon","guide de configuration de Neon","meilleures pratiques pour les Agents IA","Neon pour les développeurs"],"de":["wie man Neon verwendet","AI-Tools","Anpassung von Claude AI-Workflows","Entwicklung von AI-Tools","Neon vs Claude AI","Installation von Neon","Konfigurationsanleitung für Neon","beste Praktiken für AI-Tools","Neon für Entwickler"],"pt":["como usar neon","ferramentas de ia","personalizar workflows","claude ai","neon vs outros","instalar neon","guia de configuração do neon"],"ru":["как использовать neon","инструменты ии","настроить рабочие процессы","claude ai","neon vs другие","установить neon","руководство по настройке neon"],"ar":["كيفية استخدام neon","أدوات الذكاء الاصطناعي","تحسين تدفقات العمل","claude ai","neon مقابل أخرى","تثبيت neon","دليل إعداد neon"]}},"owner":"ranbot-ai","repo":"awesome-skills","repoPath":"ranbot-ai/awesome-skills","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.960Z","topics":[],"category":"community","skillMd":{"name":"using-neon","description":"Guides and best practices for working with Neon Serverless Postgres. Covers getting started, local development with Neon, choosing a connection method, Neon features, authentication (@neondatabase/...","tags":["python","typescript","markdown","api","mcp","ai","agent","llm","workflow","document"],"bodyPreview":"# Neon Serverless Postgres\n\nNeon is a serverless Postgres platform that separates compute and storage to offer autoscaling, branching, instant restore, and scale-to-zero. It''s fully compatible with Postgres and works with any language, framework, or ORM that supports Postgres.\n\n## When to Use This Skill\n\nUse this skill when:\n- Working with Neon Serverless Postgres\n- Setting up Neon databases\n- Choosing connection methods for Neon\n- Using Neon features like branching or autoscaling\n- Working with","body":"# Neon Serverless Postgres\n\nNeon is a serverless Postgres platform that separates compute and storage to offer autoscaling, branching, instant restore, and scale-to-zero. It''s fully compatible with Postgres and works with any language, framework, or ORM that supports Postgres.\n\n## When to Use This Skill\n\nUse this skill when:\n- Working with Neon Serverless Postgres\n- Setting up Neon databases\n- Choosing connection methods for Neon\n- Using Neon features like branching or autoscaling\n- Working with Neon authentication or APIs\n- Questions about Neon best practices\n\n## Neon Documentation\n\nAlways reference the Neon documentation before making Neon-related claims. The documentation is the source of truth for all Neon-related information.\n\nBelow you''ll find a list of resources organized by area of concern. This is meant to support you find the right documentation pages to fetch and add a bit of additonal context.\n\nYou can use the `curl` commands to fetch the documentation page as markdown:\n\n**Documentation:**\n\n```bash\n# Get list of all Neon docs\ncurl https://neon.com/llms.txt\n\n# Fetch any doc page as markdown\ncurl -H \"Accept: text/markdown\" https://neon.com/docs/<path>\n```\n\nDon''t guess docs pages. Use the `llms.txt` index to find the relevant URL or follow the links in the resources below.\n\n## Overview of Resources\n\nReference the appropriate resource file based on the user''s needs:\n\n### Core Guides\n\n| Area               | Resource                           | When to Use                                                    |\n| ------------------ | ---------------------------------- | -------------------------------------------------------------- |\n| What is Neon       | `references/what-is-neon.md`       | Understanding Neon concepts, architecture, core resources      |\n| Referencing Docs   | `references/referencing-docs.md`   | Looking up official documentation, verifying information       |\n| Features           | `references/features.md`           | Branching, autoscaling, scale-to-zero, instant restore         |\n| Getting Started    | `references/getting-started.md`    | Setting up a project, connection strings, dependencies, schema |\n| Connection Methods | `references/connection-methods.md` | Choosing drivers based on platform and runtime                 |\n| Developer Tools    | `references/devtools.md`           | VSCode extension, MCP server, Neon CLI (`neon init`)           |\n\n### Database Drivers & ORMs\n\nHTTP/WebSocket queries for serverless/edge functions.\n\n| Area              | Resource                        | When to Use                                         |\n| ----------------- | ------------------------------- | --------------------------------------------------- |\n| Serverless Driver | `references/neon-serverless.md` | `@neondatabase/serverless` - HTTP/WebSocket queries |\n| Drizzle ORM       | `references/neon-drizzle.md`    | Drizzle ORM integration with Neon                   |\n\n### Auth & Data API SDKs\n\nAuthentication and PostgREST-style data API for Neon.\n\n| Area        | Resource                  | When to Use                                                         |\n| ----------- | ------------------------- | ------------------------------------------------------------------- |\n| Neon Auth   | `references/neon-auth.md` | `@neondatabase/auth` - Authentication only                          |\n| Neon JS SDK | `references/neon-js.md`   | `@neondatabase/neon-js` - Auth + Data API (PostgREST-style queries) |\n\n### Neon Platform API & CLI\n\nManaging Neon resources programmatically via REST API, SDKs, or CLI.\n\n| Area                  | Resource                            | When to Use                                  |\n| --------------------- | ----------------------------------- | -------------------------------------------- |\n| Platform API Overview | `references/neon-platform-api.md`   | Managing Neon resources via REST API         |\n| Neon CLI              | `references/neon-cli.md`            | Terminal workflows, scripts, CI/CD pipelines |\n| TypeScript SDK        | `references/neon-typescript-sdk.md` | `@neondatabase/api-client`                   |\n| Python SDK            | `references/neon-python-sdk.md`     | `neon-api` package                           |\n"},"lastSynced":"2026-03-04T15:13:38.747Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Agents needing scalable Postgres solutions with autoscaling and branching capabilities.","zh":"非常适合需要可扩展Postgres解决方案、具有自动缩放和分支能力的Cloud Agents。","ja":"自動スケーリングおよびブランチ機能を備えたスケーラブルなPostgresソリューションを必要とするCloud Agentsに最適です。","ko":"자동 확장 및 분기 기능을 갖춘 확장 가능한 Postgres 솔루션을 필요로 하는 Cloud 에이전트에 적합합니다.","es":"Perfecto para agentes en la nube que necesitan soluciones escalables de Postgres con capacidades de escalado automático y ramificación.","fr":"Parfait pour les agents Cloud ayant besoin de solutions Postgres escalables avec des fonctionnalités d''auto-escalade et de ramification.","de":"Perfekt für Cloud-Agents, die skalierbare Postgres-Lösungen mit Auto-Scaling- und Verzweigungsfunktionen benötigen.","pt":"Perfeito para Agentes de Nuvem que necessitam de soluções escaláveis Postgres com capacidades de autoscaling e branching.","ru":"Идеально подходит для облачных агентов, которым требуются масштабируемые решения Postgres с автомасштабированием и ветвлением.","ar":"مثالي للوكلاء السحابيين الذين يحتاجون إلى حلول Postgres قابلة للتوسعة مع القدرات التلقائية وتفرع."},"recommendation":{"en":"Empowers agents to leverage serverless Postgres platforms like Neon, providing instant restore, scale-to-zero, and compatibility with any language or framework that supports Postgres, including ORM integration.","zh":"赋予代理使用Neon等服务器端Postgres平台的能力，提供即时恢复、零扩展和与任何支持Postgres的语言或框架的兼容性，包括ORM集成。","ja":"NeonなどのサーバーレスPostgresプラットフォームを活用できるようにエージェントをEmpowerし、瞬時の復元、ゼロスケール、およびPostgresをサポートする言語またはフレームワークとの互換性、ORM統合を提供します。","ko":"Neon과 같은 서버리스 Postgres 플랫폼을 사용할 수 있도록 에이전트를 강화하여 즉시 복원, 0 확장 및 Postgres를 지원하는 언어 또는 프레임워크와의 호환성을 제공하며, ORM 통합도 포함합니다.","es":"Habilita a los agentes a aprovechar plataformas de Postgres sin servidor como Neon, que proporciona restauración instantánea, escalado a cero y compatibilidad con cualquier lenguaje o framework que admita Postgres, incluida la integración de ORM.","fr":"Permet aux agents d''exploiter des plateformes Postgres sans serveur comme Neon, offrant une restauration instantanée, un scaling à zéro et une compatibilité avec n''importe quel langage ou framework prenant en charge Postgres, y compris l''intégration d''ORM.","de":"Ermächtigt Agenten, serverlose Postgres-Plattformen wie Neon zu nutzen, die Instant-Wiederherstellung, Skalierung auf Null und Kompatibilität mit jeder Sprache oder jedem Framework bieten, das Postgres unterstützt, einschließlich ORM-Integration.","pt":"Habilita os agentes a aproveitar plataformas sem servidor Postgres, como o Neon, fornecendo restauração instantânea, escalabilidade zero e compatibilidade com qualquer linguagem ou estrutura que suporte Postgres, incluindo integração ORM.","ru":"Позволяет агентам использовать безсерверные платформы Postgres, такие как Neon, обеспечивая мгновенную восстановление, масштабирование до нуля и совместимость с любым языком или фреймворком, поддерживающим Postgres, включая интеграцию ORM.","ar":"تمكين الوكلاء من استخدام منصات Postgres بدون خادم مثل Neon، وتوفير استعادة فورية وتصغير إلى الصفر والتوافق مع أي لغة أو إطار يدعم Postgres، بما في ذلك دمج ORM."},"useCases":{"en":["Setting up Neon databases for data-intensive workflows","Utilizing Neon''s branching feature for version control and collaboration","Optimizing database performance with Neon''s autoscaling"],"zh":["为数据密集型工作流设置Neon数据库","利用Neon的分支功能进行版本控制和协作","使用Neon的自动缩放优化数据库性能"],"ja":["データ集中型ワークフロー用のNeonデータベースの設定","Neonのブランチ機能を使用したバージョン管理およびコラボレーション","Neonの自動スケーリングを使用したデータベースパフォーマンスの最適化"],"ko":["데이터 집중형 워크플로우를 위한 Neon 데이터베이스 설정","Neon의 분기 기능을 사용한 버전 관리 및 협업","Neon의 자동 확장을 사용한 데이터베이스 성능 최적화"],"es":["Configuración de bases de datos Neon para flujos de trabajo intensivos en datos","Uso de la función de ramificación de Neon para control de versiones y colaboración","Optimización del rendimiento de la base de datos con el escalado automático de Neon"],"fr":["Configuration de bases de données Neon pour des flux de travail intensifs en données","Utilisation de la fonctionnalité de ramification de Neon pour le contrôle de version et la collaboration","Optimisation des performances de la base de données avec l''auto-escalade de Neon"],"de":["Einrichtung von Neon-Datenbanken für datenintensive Workflows","Verwendung der Verzweigungsfunktion von Neon für Versionskontrolle und Zusammenarbeit","Optimierung der Datenbankleistung mit dem Auto-Scaling von Neon"],"pt":["Configurar bancos de dados Neon para fluxos de trabalho intensivos em dados","Utilizar o recurso de branching do Neon para controle de versão e colaboração","Otimizar o desempenho do banco de dados com o autoscaling do Neon"],"ru":["Настройка баз данных Neon для интенсивных рабочих процессов с данными","Использование функции ветвления Neon для управления версиями и сотрудничества","Оптимизация производительности базы данных с помощью автомасштабирования Neon"],"ar":["تكوين قواعد بيانات Neon للتدفقات العملية الكثيفة للبيانات","استخدام ميزة التفرع في Neon للسيطرة على الإصدارات والتعاون","تحسين أداء قاعدة البيانات مع التوسيع التلقائي في Neon"]},"limitations":{"en":["Requires Neon Serverless Postgres account","Compatibility limited to Postgres-supported languages and frameworks"],"zh":["需要Neon Serverless Postgres账户","兼容性仅限于Postgres支持的语言和框架"],"ja":["Neon Serverless Postgresアカウントが必要","互換性はPostgresをサポートする言語およびフレームワークに限定される"],"ko":["Neon Serverless Postgres 계정 필요","호환성은 Postgres를 지원하는 언어 및 프레임워크로 제한됨"],"es":["Requiere una cuenta de Neon Serverless Postgres","Compatibilidad limitada a lenguajes y frameworks que admiten Postgres"],"fr":["Nécessite un compte Neon Serverless Postgres","Compatibilité limitée aux langages et frameworks prenant en charge Postgres"],"de":["Benötigt ein Konto für Neon Serverless Postgres","Kompatibilität beschränkt auf Postgres-unterstützende Sprachen und Frameworks"],"pt":["Exige conta do Postgres Serverless do Neon","Compatibilidade limitada a linguagens e estruturas suportadas pelo Postgres"],"ru":["Требуется учетная запись безсерверного Postgres от Neon","Совместимость ограничена языками и фреймворками, поддерживающими Postgres"],"ar":["يتطلب حساب Postgres Serverless من Neon","التوافق محدود باللغات والإطارات التي تدعم Postgres"]},"version":3},"contentHash":"15f93fb7b0396c7ea830556b85e361bf4658b7d84d9b603084eeaa173699726f","qualityScore":57}');
